2-926f-4a2a-b3f4-55ee20e63cb8'::uuid,'3cf775c9-cf72-4c06-80fc-3440efa12932'::uuid,'50598529-1646-4073-b5a9-05792b29f936'::uuid,'c725b987-3f26-4f26-bdd6-3e818f56e170'::uuid,'2b772531-e29e-469d-86b4-0d6ca62c6e96'::uuid) and not exists (select 1 from public.lesson_topics_yedek_20261008 y where y.id = t.id);
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir sorunun olduğunda İngilizce tavsiye istemeyi, arkadaşına tavsiye vermeyi ve sana verilen tavsiyeye teşekkür etmeyi öğreneceksin.</p><h3>Tavsiye istemek</h3><ul><li><b>What should I do?</b> = Ne yapmalıyım?</li><li><b>Should I + fiil?</b> = ... yapmalı mıyım? <i>Should I tell the teacher?</i></li><li><b>Can you give me some advice?</b> = Bana biraz tavsiye verebilir misin?</li></ul><p>Önce sorununu anlat, sonra sor: <i>I always forget my homework. What should I do?</i></p><h3>Tavsiye vermek</h3><table><tr><th>Kalıp</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>You should + fiil</b></td><td>... yapmalısın</td><td><i>You should drink some water.</i></td></tr><tr><td><b>You shouldn't + fiil</b></td><td>... yapmamalısın</td><td><i>You shouldn't play games all night.</i></td></tr><tr><td><b>Why don't you + fiil?</b></td><td>Neden ... yapmıyorsun? (öneri)</td><td><i>Why don't you ask Ece for help?</i></td></tr><tr><td><b>If I were you, I'd + fiil</b></td><td>Senin yerinde olsam ...</td><td><i>If I were you, I'd go to bed early.</i></td></tr><tr><td><b>You'd better + fiil</b></td><td>... yapsan iyi olur</td><td><i>You'd better take an umbrella.</i></td></tr></table><p>Bu kalıpların hepsinde fiil <b>yalın</b> hâlde gelir; to ya da -ing eklenmez.</p><h3>Mini sohbet: tavsiyeye cevap ver</h3><p><i>Can: I have a test tomorrow and I'm nervous. What should I do?</i><br><i>Elif: You should study a little tonight. And you shouldn't go to bed late.</i><br><i>Can: Good idea! Thanks for your advice.</i></p><ul><li>Tavsiyeyi beğendiysen: <b>Good idea!</b> (İyi fikir!) <b>Thanks, I'll try that.</b> (Teşekkürler, deneyeceğim.)</li><li><i>Should I...?</i> sorusuna kısa cevap: <b>Yes, you should.</b> / <b>No, you shouldn't.</b></li></ul><h3>Dikkat!</h3><ul><li>Should'dan sonra to gelmez: <i>You should to study.</i> → <i>You should study.</i></li><li>Should'dan sonra -ing gelmez: <i>You should studying.</i> → <i>You should study.</i></li><li>Why don't you sorusunda sıra bozulmaz: <i>Why you don't ask?</i> → <i>Why don't you ask?</i></li><li>If I were you kalıbında were kullanılır: <i>If I am you...</i> → <i>If I were you...</i></li></ul><h3>Kısaca</h3><p>Tavsiye istemek için What should I do? de; tavsiye vermek için You should, Why don't you...? ya da If I were you, I'd... kullan. Sana tavsiye verildiğinde Good idea, thanks! diye cevap ver.</p>","ornekler":[{"en":"— I have a headache. — You should drink some water.","tr":"— Başım ağrıyor. — Biraz su içmelisin."},{"en":"You shouldn't play computer games all night.","tr":"Bütün gece bilgisayar oyunu oynamamalısın."},{"en":"What should I do? I always forget my homework.","tr":"Ne yapmalıyım? Ödevimi hep unutuyorum."},{"en":"Why don't you write a list every evening?","tr":"Neden her akşam bir liste yazmıyorsun?"},{"en":"If I were you, I'd go to bed early.","tr":"Senin yerinde olsam erken yatardım."},{"en":"You'd better take an umbrella. It's raining.","tr":"Şemsiye alsan iyi olur. Yağmur yağıyor."},{"en":"— Should I tell the teacher? — Yes, you should.","tr":"— Öğretmene söylemeli miyim? — Evet, söylemelisin."},{"en":"— Why don't you ask Ece for help? — Good idea!","tr":"— Neden Ece'den yardım istemiyorsun? — İyi fikir!"},{"en":"Thanks for your advice. I'll try that.","tr":"Tavsiyen için teşekkürler. Bunu deneyeceğim."},{"en":"You should speak English every day with Papi.","tr":"Her gün Papi ile İngilizce konuşmalısın."}],"test":[{"tip":"secim","soru":"Arkadaşın \"I'm so tired.\" dedi. Hangisi doğru bir tavsiyedir?","secenekler":["You should to sleep.","You should go to bed early.","You go bed early."],"dogru":1,"aciklama":"Should'dan sonra fiil yalın gelir: You should go to bed early."},{"tip":"bosluk","soru":"You should ___ more water.","tr":"Daha fazla su içmelisin.","secenekler":["to drink","drinking","drink"],"dogru":2,"aciklama":"Should'dan sonra to ya da -ing gelmez, fiil yalın olur: should drink."},{"tip":"bosluk","soru":"Why don't you ___ your teacher?","tr":"Neden öğretmenine sormuyorsun?","secenekler":["ask","asking","asked"],"dogru":0,"aciklama":"Why don't you'dan sonra fiil yalın gelir: Why don't you ask...?"},{"tip":"secim","soru":"\"Senin yerinde olsam...\" demek için hangisini kullanırsın?","secenekler":["If I am you, ...","If I were you, ...","When I am you, ..."],"dogru":1,"aciklama":"Kalıp If I were you şeklindedir; were kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","should","I","do"],"cevap":"What should I do?","tr":"Ne yapmalıyım?","aciklama":"Tavsiye isterken: What should I do?"},{"tip":"secim","soru":"Arkadaşın sana \"You should wear a coat.\" dedi. Ne cevap verirsin?","secenekler":["Good idea, thanks!","Yes, I should wear.","No, I'm should."],"dogru":0,"aciklama":"Tavsiyeye teşekkür ederken Good idea, thanks! dersin."},{"tip":"bosluk","soru":"You ___ eat too much candy. It's bad for your teeth.","tr":"Çok fazla şeker yememelisin. Dişlerine zararlı.","secenekler":["should","don't should","shouldn't"],"dogru":2,"aciklama":"Yapmaması gereken bir şey için shouldn't kullanılır; don't should yanlıştır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Why","don't","you","ask","Ece"],"cevap":"Why don't you ask Ece?","tr":"Neden Ece'ye sormuyorsun?","aciklama":"Öneri kalıbı: Why don't you + fiil?"},{"tip":"dogruyanlis","soru":"\"You should to study more.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Should'dan sonra to gelmez: You should study more."},{"tip":"dogruyanlis","soru":"\"Why don't you...?\" kalıbı birine öneri ya da tavsiye vermek için kullanılır.","dogru":true,"aciklama":"Doğru! Why don't you ask Ece? = Neden Ece'ye sormuyorsun? (Sor bence.)"}],"kelimeSozlugu":{"should":{"tr":"-meli, -malı","alt":"tavsiye verir"},"shouldn't":{"tr":"-memeli, -mamalı","alt":"should not"},"advice":{"tr":"tavsiye, öğüt","alt":"sayılamaz: an advice denmez"},"idea":{"tr":"fikir","alt":"Good idea! = İyi fikir!"},"headache":{"tr":"baş ağrısı","alt":""},"try":{"tr":"denemek","alt":""},"better":{"tr":"daha iyi","alt":"You'd better = ... yapsan iyi olur"}}}$dm$::jsonb where id = 'd5e4ad58-8764-4bfc-bd5d-92137de1d721' and topic_name = 'Asking for and giving advice — Tavsiye İsteme ve Verme';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir mağazada, kafede ya da yolculukta İngilizce kibarca bir şey istemeyi, fiyat ve yol sormayı ve anlamadığında tekrar istemeyi öğreneceksin.</p><h3>Kibar başla: Excuse me ve please</h3><ul><li>Birinin dikkatini çekmek ya da bir şey sormak için: <b>Excuse me, ...</b> (Affedersiniz, ...)</li><li>Bir şey isterken cümlenin sonuna <b>please</b> eklemeyi unutma.</li><li>Anlamadıysan: <b>Sorry, could you say that again, please?</b> (Pardon, tekrar söyler misiniz lütfen?)</li><li>Bir şey alınca: <b>Thank you!</b> Sana teşekkür edilince: <b>You're welcome.</b></li></ul><h3>Mağazada ve kafede</h3><table><tr><th>İngilizce</th><th>Türkçe</th></tr><tr><td><b>How much is this T-shirt?</b></td><td>Bu tişört ne kadar?</td></tr><tr><td><b>Can I try it on, please?</b></td><td>Deneyebilir miyim lütfen?</td></tr><tr><td><b>Do you have this in blue?</b></td><td>Bunun mavisi var mı?</td></tr><tr><td><b>Do you have a smaller size?</b></td><td>Daha küçük bedeni var mı?</td></tr><tr><td><b>I'd like an orange juice, please.</b></td><td>Bir portakal suyu istiyorum lütfen.</td></tr><tr><td><b>Can I have the bill, please?</b></td><td>Hesabı alabilir miyim lütfen?</td></tr></table><p><i>Zeynep: Excuse me, how much is this T-shirt?</i><br><i>Shop assistant: It's twelve pounds.</i><br><i>Zeynep: Can I try it on, please?</i><br><i>Shop assistant: Sure. Here you are.</i></p><p>Bir kıyafeti üzerinde denemek <b>try on</b> demektir. Nesne it olunca ortaya gelir: <i>try it on</i>.</p><h3>Yolculukta ve yol sorarken</h3><ul><li><b>Excuse me, where is the bus stop?</b> = Affedersiniz, otobüs durağı nerede?</li><li><b>Which bus goes to the airport?</b> = Havalimanına hangi otobüs gidiyor?</li><li><b>Is it far?</b> = Uzak mı? Cevap: <i>No, it's a five-minute walk.</i> (Hayır, beş dakikalık yürüme mesafesi.)</li><li><b>Two tickets for the museum, please.</b> = Müze için iki bilet lütfen. Tek bilet için: <i>One ticket, please.</i></li></ul><h3>Dikkat!</h3><ul><li>“Give me” kaba duyulur: <i>Give me water.</i> → <i>Can I have some water, please?</i></li><li>Fiyat sorarken iki kalıbı karıştırma: <i>How much is it cost?</i> → <i>How much is it?</i> ya da <i>How much does it cost?</i></li><li>Yer sorarken the unutulmaz: <i>Where is bus stop?</i> → <i>Where is the bus stop?</i></li><li>Bir şey sormadan önce Sorry değil Excuse me de; Sorry özür dilerken ya da anlamadığında kullanılır.</li></ul><h3>Kısaca</h3><p>Excuse me ile başla, Can I have...? ya da I'd like... ile iste ve please demeyi unutma. Fiyat için How much is it?, yol için Where is the...? sor; anlamazsan Sorry, could you say that again? de.</p>","ornekler":[{"en":"Excuse me, where is the bus stop?","tr":"Affedersiniz, otobüs durağı nerede?"},{"en":"— How much is this T-shirt? — It's twelve pounds.","tr":"— Bu tişört ne kadar? — On iki sterlin."},{"en":"Can I try it on, please?","tr":"Deneyebilir miyim lütfen?"},{"en":"Do you have this in a smaller size?","tr":"Bunun daha küçük bedeni var mı?"},{"en":"I'd like an orange juice, please.","tr":"Bir portakal suyu istiyorum lütfen."},{"en":"Can I have the bill, please?","tr":"Hesabı alabilir miyim lütfen?"},{"en":"Two tickets for the museum, please.","tr":"Müze için iki bilet lütfen."},{"en":"— Is it far? — No, it's a five-minute walk.","tr":"— Uzak mı? — Hayır, beş dakikalık yürüme mesafesi."},{"en":"Sorry, could you say that again, please?","tr":"Pardon, tekrar söyler misiniz lütfen?"},{"en":"Which bus goes to the airport?","tr":"Havalimanına hangi otobüs gidiyor?"}],"test":[{"tip":"secim","soru":"Kafede su istiyorsun. Hangisi kibar bir istektir?","secenekler":["Give me water.","Can I have some water, please?","I want water, give."],"dogru":1,"aciklama":"Kibar istek: Can I have ..., please? Give me kaba duyulur."},{"tip":"bosluk","soru":"___ me, where is the toilet?","tr":"Affedersiniz, tuvalet nerede?","secenekler":["Sorry","Excuse","Please"],"dogru":1,"aciklama":"Bir şey sormadan önce Excuse me (affedersiniz) denir."},{"tip":"secim","soru":"Bir şeyin fiyatını sormak için hangisini kullanırsın?","secenekler":["How much is it?","How many is it?","How much it costs?"],"dogru":0,"aciklama":"Fiyat sorusu: How much is it? ya da How much does it cost?"},{"tip":"bosluk","soru":"Can I try it ___, please?","tr":"Deneyebilir miyim lütfen?","secenekler":["in","at","on"],"dogru":2,"aciklama":"Kıyafet denemek try on'dur: Can I try it on?"},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Do","you","have","this","in","blue"],"cevap":"Do you have this in blue?","tr":"Bunun mavisi var mı?","aciklama":"Renk sorarken: Do you have this in + renk?"},{"tip":"secim","soru":"Mağazada denediğin tişört sana büyük geldi. Ne dersin?","secenekler":["It's very big, I don't want.","Do you have more small?","Do you have a smaller size?"],"dogru":2,"aciklama":"Daha küçük beden için: Do you have a smaller size?"},{"tip":"bosluk","soru":"I'd ___ a cheese sandwich, please.","tr":"Peynirli bir sandviç istiyorum lütfen.","secenekler":["like","liking","likes"],"dogru":0,"aciklama":"I'd like = istiyorum (kibar). I'd'den sonra fiil yalın gelir."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Which","bus","goes","to","the","airport"],"cevap":"Which bus goes to the airport?","tr":"Havalimanına hangi otobüs gidiyor?","aciklama":"Which bus (hangi otobüs) özne olduğu için do kullanılmaz: Which bus goes...?"},{"tip":"dogruyanlis","soru":"\"How much is it cost?\" doğru bir sorudur.","dogru":false,"aciklama":"Doğrusu: How much is it? ya da How much does it cost?"},{"tip":"secim","soru":"Satıcı poşetini uzatıp \"Here you are.\" dedi. Ne dersin?","secenekler":["You're welcome.","Thank you!","Here you are."],"dogru":1,"aciklama":"Bir şey alınca Thank you! denir. You're welcome teşekküre verilen cevaptır."}],"kelimeSozlugu":{"excuse me":{"tr":"affedersiniz","alt":"dikkat çekmek için"},"how much":{"tr":"ne kadar","alt":"fiyat sorarken"},"try on":{"tr":"üzerinde denemek","alt":"Can I try it on?"},"size":{"tr":"beden","alt":""},"bill":{"tr":"hesap","alt":"restoran ve kafede"},"ticket":{"tr":"bilet","alt":""},"far":{"tr":"uzak","alt":""},"bus stop":{"tr":"otobüs durağı","alt":""}}}$dm$::jsonb where id = 'ecfbd961-4d72-48a3-8d62-9ef762b85036' and topic_name = 'Dealing with everyday situations (shops, travel, etc.) — Günlük Durumlarla Başa Çıkma';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Dün ya da geçen hafta olan bir olayı sırasıyla anlatmayı ve yarın ya da gelecek hafta yapacağın şeyleri sırayla söylemeyi öğreneceksin. Bunun için sıralama kelimelerini ve doğru zamanı kullanacaksın.</p><h3>Sıralama kelimeleri</h3><p>Bir hikâyeyi karışık değil, adım adım anlatmak için bu kelimeleri cümlenin başına koyarız. Ardından genellikle virgül gelir.</p><table><tr><th>İngilizce</th><th>Türkçe</th><th>Ne zaman?</th></tr><tr><td><b>first</b></td><td>önce, ilk olarak</td><td>ilk adım</td></tr><tr><td><b>then</b></td><td>sonra</td><td>ortadaki adımlar</td></tr><tr><td><b>after that</b></td><td>ondan sonra</td><td>ortadaki adımlar</td></tr><tr><td><b>next</b></td><td>sonra, ardından</td><td>ortadaki adımlar</td></tr><tr><td><b>suddenly</b></td><td>aniden</td><td>beklenmedik bir şey olunca</td></tr><tr><td><b>finally</b></td><td>en sonunda</td><td>son adım</td></tr></table><h3>Geçmişteki bir olayı anlatmak</h3><p>Olay bittiyse <b>geçmiş zaman (past simple)</b> kullanırsın: <b>özne + fiilin 2. hâli</b>. Zaman ifadeleri: <i>yesterday</i> (dün), <i>last Saturday</i> (geçen cumartesi).</p><p><i>Last Saturday we went to the cinema. First, we bought the tickets. Then, we went inside. After that, we ate popcorn and watched the film. Suddenly, the lights went off! Finally, we walked home together.</i></p><p>Arkadaşın hikâyeyi anlatırken sorabilirsin: <i>What did you do after that?</i> (Ondan sonra ne yaptınız?) <i>What happened next?</i> (Sonra ne oldu?)</p><h3>Gelecekteki planları anlatmak</h3><p>Yapmaya karar verdiğin planlar için <b>am/is/are going to + fiil</b>, o anda verdiğin kararlar ve tahminler için <b>will + fiil</b> kullanırsın. Zaman ifadeleri: <i>tomorrow</i> (yarın), <i>next week</i> (gelecek hafta).</p><ul><li><i>Tomorrow, I'm going to visit my cousins.</i> = Yarın kuzenlerimi ziyaret edeceğim.</li><li><i>First, I'll do my homework. Then, I'll play games.</i> = Önce ödevimi yapacağım. Sonra oyun oynayacağım.</li><li><i>Tomorrow will be fun.</i> = Yarın eğlenceli olacak.</li></ul><h3>Dikkat!</h3><ul><li>Geçmiş zaman ifadesiyle fiilin 2. hâlini kullan: <i>Yesterday I go to the park.</i> → <i>Yesterday I went to the park.</i></li><li>Gelecekten bahsederken geçmiş zaman kullanma: <i>Tomorrow I visited my uncle.</i> → <i>Tomorrow I'm going to visit my uncle.</i></li><li>Going to'dan önce am/is/are unutulmaz: <i>We going to have a picnic.</i> → <i>We are going to have a picnic.</i></li><li>Then (sonra) ile than (-den daha) farklıdır: <i>Than, we ate pizza.</i> → <i>Then, we ate pizza.</i></li></ul><h3>Kısaca</h3><p>Olayları first, then, after that ve finally ile sırayla anlat. Geçmiş için fiilin 2. hâlini, gelecek için going to ya da will kullan.</p>","ornekler":[{"en":"First, we bought the tickets. Then, we went inside.","tr":"Önce biletleri aldık. Sonra içeri girdik."},{"en":"After that, we ate popcorn and watched the film.","tr":"Ondan sonra patlamış mısır yedik ve filmi izledik."},{"en":"Finally, we walked home together.","tr":"En sonunda hep birlikte eve yürüdük."},{"en":"Suddenly, it started to rain.","tr":"Aniden yağmur yağmaya başladı."},{"en":"Yesterday, Ali fell off his bike.","tr":"Dün Ali bisikletinden düştü."},{"en":"Tomorrow, I'm going to visit my cousins.","tr":"Yarın kuzenlerimi ziyaret edeceğim."},{"en":"Next week, we are going to have a picnic.","tr":"Gelecek hafta piknik yapacağız."},{"en":"First, I'll do my homework. Then, I'll play games.","tr":"Önce ödevimi yapacağım. Sonra oyun oynayacağım."},{"en":"Last Saturday was boring, but tomorrow will be fun.","tr":"Geçen cumartesi sıkıcıydı ama yarın eğlenceli olacak."},{"en":"What did you do after that?","tr":"Ondan sonra ne yaptın?"}],"test":[{"tip":"secim","soru":"Bir hikâyenin ilk adımını anlatırken hangi kelimeyle başlarsın?","secenekler":["First","Finally","After that"],"dogru":0,"aciklama":"First = önce, ilk olarak. Finally son adım içindir."},{"tip":"bosluk","soru":"Yesterday we ___ to the zoo.","tr":"Dün hayvanat bahçesine gittik.","secenekler":["go","went","will go"],"dogru":1,"aciklama":"Yesterday geçmişi anlatır, go fiilinin 2. hâli gelir: went."},{"tip":"bosluk","soru":"Tomorrow I'm going to ___ my grandma.","tr":"Yarın büyükannemi ziyaret edeceğim.","secenekler":["visited","visiting","visit"],"dogru":2,"aciklama":"Going to'dan sonra fiil yalın gelir: going to visit."},{"tip":"secim","soru":"Bir hikâyede sıralama kelimelerinin doğru sırası hangisi?","secenekler":["Finally → First → Then","Then → Finally → First","First → Then → Finally"],"dogru":2,"aciklama":"Önce First, ortada Then, en sonda Finally kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["What","happened","next"],"cevap":"What happened next?","tr":"Sonra ne oldu?","aciklama":"Hikâyenin devamını sorarken: What happened next? (Sonra ne oldu?)"},{"tip":"bosluk","soru":"___, it started to rain and we ran home.","tr":"Aniden yağmur yağmaya başladı ve eve koştuk.","secenekler":["Tomorrow","Suddenly","Next week"],"dogru":1,"aciklama":"Cümle geçmişte (started, ran). Beklenmedik olay için Suddenly (aniden) kullanılır."},{"tip":"secim","soru":"\"Gelecek hafta piknik yapacağız.\" cümlesinin doğru İngilizcesi hangisi?","secenekler":["Next week we are going to have a picnic.","Next week we had a picnic.","Next week we going to have a picnic."],"dogru":0,"aciklama":"Gelecek plan: are going to + fiil. Are unutulmamalı."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I'm","going","to","visit","my","cousins"],"cevap":"I'm going to visit my cousins.","tr":"Kuzenlerimi ziyaret edeceğim.","aciklama":"Gelecek plan: I'm (I am) + going to + yalın fiil."},{"tip":"dogruyanlis","soru":"\"Tomorrow I visited my uncle.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Tomorrow gelecektir: Tomorrow I'm going to visit my uncle."},{"tip":"dogruyanlis","soru":"\"Finally\" kelimesi bir hikâyenin son adımını anlatırken kullanılır.","dogru":true,"aciklama":"Doğru! Finally = en sonunda."}],"kelimeSozlugu":{"first":{"tr":"önce, ilk olarak","alt":""},"then":{"tr":"sonra","alt":"than ile karıştırma"},"after that":{"tr":"ondan sonra","alt":""},"next":{"tr":"sonra; gelecek","alt":"next week = gelecek hafta"},"suddenly":{"tr":"aniden","alt":""},"finally":{"tr":"en sonunda","alt":""},"yesterday":{"tr":"dün","alt":""},"tomorrow":{"tr":"yarın","alt":""}}}$dm$::jsonb where id = '1ecfb76e-04f1-4c90-a0e8-ca004e1639f7' and topic_name = 'Describing past and future events — Geçmiş ve Gelecek Olayları Betimleme';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir şey hakkında ne düşündüğünü İngilizce söylemeyi ve fikrinin nedenini açıklamayı öğreneceksin. Arkadaşının fikrine katıldığını ya da katılmadığını kibarca söylemeyi de öğreneceksin.</p><h3>Fikrini söyle</h3><table><tr><th>Kalıp</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>I think + cümle</b></td><td>Bence ...</td><td><i>I think cats are cute.</i></td></tr><tr><td><b>I don't think + cümle</b></td><td>Bence ... değil</td><td><i>I don't think this game is difficult.</i></td></tr><tr><td><b>In my opinion, + cümle</b></td><td>Bana göre ...</td><td><i>In my opinion, English is a fun lesson.</i></td></tr><tr><td><b>I'm not sure.</b></td><td>Emin değilim.</td><td><i>I'm not sure. Maybe you are right.</i></td></tr></table><p>Türkçede “Bence bu oyun zor değil.” deriz. İngilizcede olumsuzluk genellikle think'e gelir: <i>I don't think this game is difficult.</i> Bu çok daha doğal duyulur.</p><h3>Nedenini söyle: because ve so</h3><ul><li><b>because</b> = çünkü. Nedeni söyler: <i>I like summer because there is no school.</i> (Yazı severim çünkü okul yok.)</li><li><b>so</b> = bu yüzden. Sonucu söyler: <i>It was raining, so we stayed at home.</i> (Yağmur yağıyordu, bu yüzden evde kaldık.)</li><li>Biri <b>Why?</b> (Neden?) diye sorarsa kısaca <b>Because...</b> ile cevap verebilirsin: <i>Why do you like Papi? Because he is funny.</i></li></ul><h3>Fikir sor, katıl ya da katılma</h3><p><i>Deniz: What do you think about the new film?</i><br><i>Zeynep: I think it's great! The music is amazing.</i><br><i>Deniz: I agree! I loved it too.</i></p><ul><li>Fikir sorarken: <b>What do you think about...?</b> (... hakkında ne düşünüyorsun?)</li><li>Katılıyorsan: <b>I agree.</b> (Katılıyorum.) <b>You're right.</b> (Haklısın.) <b>Me too.</b> (Ben de.)</li><li>Katılmıyorsan kibarca: <b>I don't agree.</b> ya da <b>I'm not sure.</b> ve sonra nedenini söyle.</li></ul><h3>Dikkat!</h3><ul><li>Agree bir fiildir, önüne am gelmez: <i>I am agree.</i> → <i>I agree.</i></li><li>“Bana göre” için <i>According to me</i> doğal değildir → <i>In my opinion</i> ya da <i>I think</i> kullan.</li><li>Because'tan sonra tam cümle gelir: <i>because of it is fun</i> → <i>because it is fun</i>.</li><li><i>I think it isn't easy.</i> yerine daha doğal olan: <i>I don't think it's easy.</i></li></ul><h3>Kısaca</h3><p>Fikrini I think veya In my opinion ile söyle, nedenini because ile açıkla. Arkadaşına What do you think? diye sor ve I agree ya da I don't agree ile cevap ver.</p>","ornekler":[{"en":"I think cats are better pets than dogs.","tr":"Bence kediler köpeklerden daha iyi evcil hayvanlardır."},{"en":"In my opinion, English is a fun lesson.","tr":"Bana göre İngilizce eğlenceli bir ders."},{"en":"I don't think this game is difficult.","tr":"Bence bu oyun zor değil."},{"en":"I like summer because there is no school.","tr":"Yazı severim çünkü okul yok."},{"en":"— What do you think about the new film? — It's great!","tr":"— Yeni film hakkında ne düşünüyorsun? — Harika!"},{"en":"— Why do you like Papi? — Because he is funny.","tr":"— Papi'yi neden seviyorsun? — Çünkü komik."},{"en":"— I think pizza is the best food. — I agree!","tr":"— Bence pizza en güzel yemek. — Katılıyorum!"},{"en":"— I think maths is boring. — I don't agree.","tr":"— Bence matematik sıkıcı. — Katılmıyorum."},{"en":"It was raining, so we stayed at home.","tr":"Yağmur yağıyordu, bu yüzden evde kaldık."},{"en":"I'm not sure. Maybe you are right.","tr":"Emin değilim. Belki haklısın."}],"test":[{"tip":"secim","soru":"\"Katılıyorum.\" demek için hangisini kullanırsın?","secenekler":["I am agree.","I agree.","I agreeing."],"dogru":1,"aciklama":"Agree bir fiildir, önüne am gelmez: I agree."},{"tip":"bosluk","soru":"I like Saturdays ___ there is no school.","tr":"Cumartesileri severim çünkü okul yok.","secenekler":["because","so","but"],"dogru":0,"aciklama":"Nedeni söylemek için because (çünkü) kullanılır."},{"tip":"secim","soru":"Arkadaşın \"What do you think about this book?\" diye sordu. Ne cevap verirsin?","secenekler":["Yes, I do.","I'm thinking.","I think it's very interesting."],"dogru":2,"aciklama":"Fikir sorulduğunda I think + cümle ile cevap verilir."},{"tip":"bosluk","soru":"___ my opinion, football is the best sport.","tr":"Bana göre futbol en iyi spordur.","secenekler":["On","In","At"],"dogru":1,"aciklama":"Kalıp her zaman In my opinion şeklindedir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","don't","think","it's","difficult"],"cevap":"I don't think it's difficult.","tr":"Bence zor değil.","aciklama":"Olumsuzluk think'e gelir: I don't think + cümle."},{"tip":"secim","soru":"\"Bence bu oyun zor değil.\" cümlesini en doğal nasıl söylersin?","secenekler":["I don't think this game is difficult.","I think not this game is difficult.","According to me, this game difficult."],"dogru":0,"aciklama":"İngilizcede olumsuzluk genellikle think'e gelir: I don't think..."},{"tip":"bosluk","soru":"It was raining, ___ we stayed at home.","tr":"Yağmur yağıyordu, bu yüzden evde kaldık.","secenekler":["because","or","so"],"dogru":2,"aciklama":"Sonucu söylemek için so (bu yüzden) kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Why","do","you","like","cats"],"cevap":"Why do you like cats?","tr":"Kedileri neden seviyorsun?","aciklama":"Neden sorusu: Why + do + you + fiil?"},{"tip":"dogruyanlis","soru":"\"According to me\" İngilizcede fikir bildirmenin en doğal yoludur.","dogru":false,"aciklama":"Doğal olan In my opinion ya da I think kullanmaktır."},{"tip":"dogruyanlis","soru":"\"I don't think it's true.\" Bu cümle doğru mu?","dogru":true,"aciklama":"Doğru! Bence doğru değil demenin doğal yolu: I don't think it's true."}],"kelimeSozlugu":{"think":{"tr":"düşünmek","alt":"I think = bence"},"opinion":{"tr":"fikir, görüş","alt":"In my opinion = bana göre"},"because":{"tr":"çünkü","alt":"nedeni söyler"},"so":{"tr":"bu yüzden","alt":"sonucu söyler"},"agree":{"tr":"katılmak, aynı fikirde olmak","alt":""},"sure":{"tr":"emin","alt":"I'm not sure = emin değilim"},"right":{"tr":"haklı; doğru","alt":"You're right = haklısın"},"maybe":{"tr":"belki","alt":""}}}$dm$::jsonb where id = '16cf340c-daa0-4a43-8c25-648cb53ac6ba' and topic_name = 'Giving opinions and reasons — Fikir ve Gerekçe Bildirme';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>İki şeyi, iki kişiyi ya da iki yeri İngilizce karşılaştırmayı öğreneceksin: hangisi daha büyük, daha hızlı, daha ilginç? İki şeyin aynı olduğunu söylemeyi ve arkadaşına “Hangisi daha ...?” diye sormayı da öğreneceksin.</p><h3>Daha ... : -er than ve more ... than</h3><p>Türkçedeki “-den daha” yerine İngilizcede sıfatın ardından <b>than</b> gelir.</p><table><tr><th>Sıfat</th><th>Kural</th><th>Daha ...</th></tr><tr><td>tall, fast, small</td><td>kısa sıfat + <b>-er</b></td><td>taller, faster, smaller</td></tr><tr><td>big, hot</td><td>son harf çiftlenir + <b>-er</b></td><td>bigger, hotter</td></tr><tr><td>happy, easy</td><td>y düşer, <b>-ier</b> gelir</td><td>happier, easier</td></tr><tr><td>difficult, interesting</td><td>uzun sıfat: <b>more</b> + sıfat</td><td>more difficult, more interesting</td></tr><tr><td>good / bad</td><td>düzensiz</td><td><b>better / worse</b></td></tr></table><ul><li><i>Istanbul is bigger than Izmir.</i> = İstanbul İzmir'den daha büyüktür.</li><li><i>Maths is more difficult than art for me.</i> = Benim için matematik resimden daha zor.</li><li><i>This game is better than that one.</i> = Bu oyun şundan daha iyi.</li></ul><h3>Aynı mı? as ... as</h3><ul><li><b>as + sıfat + as</b> = ... kadar: <i>Ece is as tall as Zeynep.</i> (Ece, Zeynep kadar uzun. Boyları aynı.)</li><li><b>not as + sıfat + as</b> = ... kadar değil: <i>My bike isn't as fast as your bike.</i> (Bisikletim seninki kadar hızlı değil.)</li></ul><h3>Karşılaştırma soruları</h3><p><i>Elif: Which is faster, a cat or a dog?</i><br><i>Ali: A dog, I think. Dogs are faster than cats.</i><br><i>Elif: Who is older, you or your sister?</i><br><i>Ali: My sister. She is older than me.</i></p><ul><li>Şeyler için: <b>Which is + sıfat-er, A or B?</b></li><li>İnsanlar için: <b>Who is + sıfat-er, A or B?</b></li></ul><h3>Dikkat!</h3><ul><li>More ile -er birlikte kullanılmaz: <i>more bigger</i> → <i>bigger</i>.</li><li>Türkçedeki “-den” için from değil than kullanılır: <i>taller from me</i> → <i>taller than me</i>.</li><li>Good düzensizdir: <i>gooder</i> ya da <i>more good</i> → <i>better</i>. Bad için de <i>worse</i>.</li><li>As ... as kalıbında than kullanılmaz: <i>as tall than</i> → <i>as tall as</i>.</li></ul><h3>Kısaca</h3><p>Kısa sıfatlara -er, uzun sıfatlara more ekle ve ardından than kullan; good ve bad için better ve worse de. İki şey aynıysa as ... as, aynı değilse not as ... as kullan.</p>","ornekler":[{"en":"Istanbul is bigger than Izmir.","tr":"İstanbul İzmir'den daha büyüktür."},{"en":"My brother is taller than me.","tr":"Ağabeyim benden daha uzun."},{"en":"Maths is more difficult than art for me.","tr":"Benim için matematik resimden daha zor."},{"en":"This game is better than that one.","tr":"Bu oyun şundan daha iyi."},{"en":"Today's weather is worse than yesterday's.","tr":"Bugünkü hava dünkünden daha kötü."},{"en":"Ece is as tall as Zeynep.","tr":"Ece, Zeynep kadar uzun."},{"en":"My bike isn't as fast as your bike.","tr":"Bisikletim seninki kadar hızlı değil."},{"en":"— Which is faster, a cat or a dog? — A dog, I think.","tr":"— Hangisi daha hızlı, kedi mi köpek mi? — Bence köpek."},{"en":"Papi is smaller than an eagle.","tr":"Papi bir kartaldan daha küçük."},{"en":"Who is older, you or your sister?","tr":"Kim daha büyük, sen mi kız kardeşin mi?"}],"test":[{"tip":"bosluk","soru":"An elephant is ___ than a horse.","tr":"Fil attan daha büyüktür.","secenekler":["bigger","more big","biggest"],"dogru":0,"aciklama":"Big kısa bir sıfattır: son harf çiftlenir, -er eklenir: bigger."},{"tip":"secim","soru":"\"good\" kelimesinin \"daha iyi\" hâli hangisidir?","secenekler":["gooder","more good","better"],"dogru":2,"aciklama":"Good düzensizdir: good → better (daha iyi)."},{"tip":"bosluk","soru":"My sister is older ___ me.","tr":"Ablam benden daha büyük.","secenekler":["from","than","as"],"dogru":1,"aciklama":"Karşılaştırmada -den daha için than kullanılır."},{"tip":"secim","soru":"\"Bu kitap o kitaptan daha ilginç.\" cümlesinin doğru İngilizcesi hangisi?","secenekler":["This book is interestinger than that book.","This book is more interesting than that book.","This book is more interesting from that book."],"dogru":1,"aciklama":"Uzun sıfatlarda more kullanılır, ardından than gelir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I'm","taller","than","my","brother"],"cevap":"I'm taller than my brother.","tr":"Ben erkek kardeşimden daha uzunum.","aciklama":"Kalıp: özne + am/is/are + sıfat-er + than + karşılaştırılan."},{"tip":"bosluk","soru":"Ali is as tall ___ Mert.","tr":"Ali, Mert kadar uzun.","secenekler":["than","like","as"],"dogru":2,"aciklama":"Aynılık kalıbı as ... as şeklindedir: as tall as."},{"tip":"secim","soru":"Arkadaşın \"Which is faster, a car or a bike?\" diye sordu. Doğru cevap hangisi?","secenekler":["A car is faster.","A car is more fast.","A car faster."],"dogru":0,"aciklama":"Fast kısa bir sıfattır: faster. Cümlede is unutulmaz."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["It's","heavier","than","my","bag"],"cevap":"It's heavier than my bag.","tr":"O, benim çantamdan daha ağır.","aciklama":"Heavy → heavier (y düşer, -ier gelir), sonra than my bag."},{"tip":"dogruyanlis","soru":"\"My bike is more fast than yours.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Fast kısa sıfattır, more almaz: My bike is faster than yours."},{"tip":"dogruyanlis","soru":"\"Ece is as tall as Zeynep.\" cümlesi, ikisinin boyunun aynı olduğunu anlatır.","dogru":true,"aciklama":"Doğru! As tall as = ... kadar uzun, yani boyları aynı."}],"kelimeSozlugu":{"than":{"tr":"-den, -dan (daha)","alt":"taller than me"},"more":{"tr":"daha","alt":"uzun sıfatlarla"},"bigger":{"tr":"daha büyük","alt":"big"},"better":{"tr":"daha iyi","alt":"good"},"worse":{"tr":"daha kötü","alt":"bad"},"taller":{"tr":"daha uzun","alt":"tall"},"faster":{"tr":"daha hızlı","alt":"fast"},"difficult":{"tr":"zor","alt":"more difficult"}}}$dm$::jsonb where id = '7a1db7fc-b51d-40a0-b4a8-737771b990b5' and topic_name = 'Making comparisons — Karşılaştırma Yapma';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Arkadaşınla İngilizce plan yapmayı öğreneceksin: birini davet etmek, bir öneri sunmak, daveti kabul etmek ya da kibarca reddetmek, sonra da saat ve yer kararlaştırmak.</p><h3>Boş musun? Ne yapıyorsun?</h3><p>Plan yapmadan önce arkadaşının boş olup olmadığını sorarsın. Önceden ayarlanmış planlar için <b>am/is/are + fiil-ing</b> (şimdiki zaman) kullanılır:</p><ul><li><i>What are you doing this weekend?</i> = Bu hafta sonu ne yapıyorsun?</li><li><i>Are you free on Saturday?</i> = Cumartesi boş musun?</li><li>Cevaplar: <i>Nothing special.</i> (Özel bir şey yok.) <i>I'm visiting my grandma.</i> (Büyükannemi ziyaret ediyorum.)</li></ul><h3>Öneri ve davet kalıpları</h3><table><tr><th>Kalıp</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>Let's + fiil</b></td><td>Hadi ...</td><td><i>Let's go to the cinema.</i></td></tr><tr><td><b>How about + fiil-ing?</b></td><td>... -meye ne dersin?</td><td><i>How about playing football?</i></td></tr><tr><td><b>Shall we + fiil?</b></td><td>... -elim mi?</td><td><i>Shall we go to the park?</i></td></tr><tr><td><b>Would you like to + fiil?</b></td><td>... ister misin? (kibar)</td><td><i>Would you like to come to my party?</i></td></tr></table><h3>Ne cevap verirsin?</h3><ul><li>Kabul ederken: <b>Sure!</b> (Tabii!) <b>That sounds great!</b> (Harika olur!) <b>I'd love to!</b> (Çok isterim!)</li><li>Kibarca reddederken önce özür dile, sonra sebebini söyle: <b>Sorry, I can't. I have to study.</b> (Üzgünüm, gelemem. Ders çalışmam lazım.) ya da <b>I'd love to, but...</b> (Çok isterim ama...)</li><li>Başka bir zaman önerebilirsin: <i>How about Sunday?</i> (Pazara ne dersin?)</li></ul><h3>Saat ve yer kararlaştırma</h3><p><i>Can: What time shall we meet?</i><br><i>Elif: At three o'clock.</i><br><i>Can: Where shall we meet?</i><br><i>Elif: Let's meet in front of the cinema.</i><br><i>Can: Great! See you on Saturday.</i></p><p>Günlerle <b>on</b> (on Saturday), saatlerle <b>at</b> (at three o'clock) kullanılır.</p><h3>Dikkat!</h3><ul><li>How about'tan sonra fiil -ing alır: <i>How about go swimming?</i> → <i>How about going swimming?</i></li><li>Let's'ten sonra to gelmez: <i>Let's to go.</i> → <i>Let's go.</i></li><li>Would you like'tan sonra to gelir: <i>Would you like come?</i> → <i>Would you like to come?</i> Cevap da <i>Yes, I would like.</i> değil, <i>I'd love to!</i> olur.</li><li>Günlerle at değil on kullanılır: <i>at Saturday</i> → <i>on Saturday</i>.</li></ul><h3>Kısaca</h3><p>Let's, How about...?, Shall we...? ve Would you like to...? ile öneri yap; I'd love to! ile kabul et, Sorry, I can't... ile kibarca reddet. Sonra What time shall we meet? ve Where shall we meet? diye sorup planı tamamla.</p>","ornekler":[{"en":"— What are you doing this weekend? — Nothing special.","tr":"— Bu hafta sonu ne yapıyorsun? — Özel bir şey yok."},{"en":"— Are you free on Saturday? — Yes, I am.","tr":"— Cumartesi boş musun? — Evet, boşum."},{"en":"Let's go to the cinema on Sunday.","tr":"Hadi pazar günü sinemaya gidelim."},{"en":"How about playing football in the park?","tr":"Parkta futbol oynamaya ne dersin?"},{"en":"— Would you like to come to my party? — I'd love to!","tr":"— Partime gelmek ister misin? — Çok isterim!"},{"en":"I'd love to, but I have to study.","tr":"Çok isterim ama ders çalışmam gerekiyor."},{"en":"Sorry, I can't. I'm visiting my grandma on Sunday.","tr":"Üzgünüm, gelemem. Pazar günü büyükannemi ziyaret ediyorum."},{"en":"— What time shall we meet? — At three o'clock.","tr":"— Saat kaçta buluşalım? — Saat üçte."},{"en":"Let's meet in front of the cinema.","tr":"Sinemanın önünde buluşalım."},{"en":"Great! See you on Saturday.","tr":"Harika! Cumartesi görüşürüz."}],"test":[{"tip":"secim","soru":"Arkadaşın \"Would you like to come to my party?\" dedi. Gitmek istiyorsun. Ne cevap verirsin?","secenekler":["Yes, I like.","I'd love to!","Yes, I would like."],"dogru":1,"aciklama":"Daveti sevinerek kabul etmenin doğal yolu: I'd love to! (Çok isterim!)"},{"tip":"bosluk","soru":"How about ___ to the park?","tr":"Parka gitmeye ne dersin?","secenekler":["go","going","to go"],"dogru":1,"aciklama":"How about'tan sonra fiil -ing alır: How about going...?"},{"tip":"bosluk","soru":"Let's ___ at the bus stop.","tr":"Otobüs durağında buluşalım.","secenekler":["meet","to meet","meeting"],"dogru":0,"aciklama":"Let's'ten sonra fiil yalın gelir: Let's meet."},{"tip":"secim","soru":"Arkadaşın seni sinemaya çağırdı ama ödevin var. Hangisi kibar bir cevaptır?","secenekler":["Sorry, I can't. I have to do my homework.","No. I don't go.","I'm not want."],"dogru":0,"aciklama":"Kibarca reddederken önce özür dile, sonra sebebini söyle: Sorry, I can't. I have to..."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","time","shall","we","meet"],"cevap":"What time shall we meet?","tr":"Saat kaçta buluşalım?","aciklama":"Buluşma saatini birlikte kararlaştırırken: What time shall we meet?"},{"tip":"bosluk","soru":"Are you free ___ Saturday?","tr":"Cumartesi boş musun?","secenekler":["in","at","on"],"dogru":2,"aciklama":"Günlerle on kullanılır: on Saturday, on Sunday."},{"tip":"secim","soru":"Buluşma saatini sormak için hangisini kullanırsın?","secenekler":["What time we meet?","What time does we meet?","What time shall we meet?"],"dogru":2,"aciklama":"Ortak karar sorarken shall we kullanılır: What time shall we meet?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Let's","meet","in","front","of","the","cinema"],"cevap":"Let's meet in front of the cinema.","tr":"Sinemanın önünde buluşalım.","aciklama":"Let's + fiil, sonra yer: in front of the cinema (sinemanın önünde)."},{"tip":"dogruyanlis","soru":"\"Would you like come to the zoo?\" Bu cümle doğru mu?","dogru":false,"aciklama":"Would you like'tan sonra to gelir: Would you like to come to the zoo?"},{"tip":"dogruyanlis","soru":"\"I'm playing tennis with Can tomorrow.\" cümlesi yarın için önceden yapılmış bir planı anlatır.","dogru":true,"aciklama":"Doğru! Ayarlanmış planlar için am/is/are + fiil-ing kullanılır."}],"kelimeSozlugu":{"weekend":{"tr":"hafta sonu","alt":""},"free":{"tr":"boş, müsait","alt":"Are you free? = Boş musun?"},"let's":{"tr":"hadi ... -elim","alt":"let us"},"how about":{"tr":"... -e ne dersin?","alt":"ardından fiil-ing gelir"},"shall":{"tr":"... -elim mi?","alt":"Shall we...?"},"meet":{"tr":"buluşmak","alt":""},"in front of":{"tr":"önünde","alt":""},"sounds":{"tr":"kulağa ... geliyor","alt":"That sounds great!"}}}$dm$::jsonb where id = '9863e41d-0259-4b7c-9222-bb82653361a6' and topic_name = 'Making plans and arrangements — Plan ve Düzenlemeler Yapma';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Neyi ne kadar sevdiğini ya da sevmediğini İngilizce söylemeyi, iki şey arasında hangisini tercih ettiğini anlatmayı ve arkadaşına neleri sevdiğini sormayı öğreneceksin.</p><h3>Ne kadar seviyorsun?</h3><p>Bu fiiller en çok sevmekten en az sevmeye doğru sıralanmıştır. Ardından bir isim ya da <b>fiil-ing</b> gelir.</p><table><tr><th>İngilizce</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>love</b></td><td>bayılmak, çok sevmek</td><td><i>I love playing basketball.</i></td></tr><tr><td><b>really like</b></td><td>çok sevmek</td><td><i>Ece really likes drawing.</i></td></tr><tr><td><b>like / enjoy</b></td><td>sevmek, hoşlanmak</td><td><i>I enjoy swimming.</i></td></tr><tr><td><b>don't mind</b></td><td>fark etmez, sorun değil</td><td><i>I don't mind washing the dishes.</i></td></tr><tr><td><b>don't like</b></td><td>sevmemek</td><td><i>I don't like rainy days.</i></td></tr><tr><td><b>hate</b></td><td>nefret etmek</td><td><i>I hate spiders.</i></td></tr><tr><td><b>can't stand</b></td><td>hiç dayanamamak</td><td><i>Mert can't stand loud music.</i></td></tr></table><p>He, she, it ile fiile -s eklenir: <i>She likes</i>, <i>He enjoys</i>.</p><h3>Tercih yapmak</h3><ul><li><b>I prefer A to B.</b> = A'yı B'ye tercih ederim. <i>I prefer cats to dogs.</i></li><li><b>I like A more than B.</b> = A'yı B'den daha çok severim. <i>I like summer more than winter.</i></li><li>Soru: <b>Which do you prefer, A or B?</b> = A mı B mi, hangisini tercih edersin? Kısa cevap: <i>Pizza!</i> ya da <i>I prefer pizza.</i></li></ul><h3>Sor ve cevap ver</h3><p><i>Ayşe: What kind of music do you like?</i><br><i>Can: I like pop. What about you?</i><br><i>Ayşe: I love pop too! But I don't like rap.</i><br><i>Can: Me neither.</i></p><ul><li><b>What kind of ... do you like?</b> = Ne tür ... seversin?</li><li>Aynı şeyi seviyorsan: <b>Me too!</b> (Ben de!)</li><li>Aynı şeyi sevmiyorsan: <b>Me neither.</b> (Ben de sevmem.)</li></ul><h3>Dikkat!</h3><ul><li>Very much cümlenin sonuna gelir: <i>I like very much football.</i> → <i>I like football very much.</i></li><li>Prefer ile than değil to kullanılır: <i>I prefer tea than milk.</i> → <i>I prefer tea to milk.</i></li><li>Like bir fiildir, önüne am gelmez: <i>I am like chocolate.</i> → <i>I like chocolate.</i></li><li>Olumsuz bir cümleye katılırken too değil neither: <i>I don't like it too.</i> → <i>Me neither.</i></li></ul><h3>Kısaca</h3><p>Love, like, don't mind, don't like, hate ve can't stand ile ne kadar sevdiğini söyle; tercihin için I prefer A to B kullan. Arkadaşına What kind of ... do you like? diye sor, Me too ya da Me neither ile cevap ver.</p>","ornekler":[{"en":"I love playing basketball with my friends.","tr":"Arkadaşlarımla basketbol oynamaya bayılırım."},{"en":"Ece really likes drawing animals.","tr":"Ece hayvan resimleri çizmeyi çok sever."},{"en":"I don't mind washing the dishes.","tr":"Bulaşık yıkamak bana sorun olmaz."},{"en":"Mert can't stand loud music.","tr":"Mert yüksek sesli müziğe hiç dayanamaz."},{"en":"I prefer cats to dogs.","tr":"Kedileri köpeklere tercih ederim."},{"en":"— Which do you prefer, pizza or pasta? — Pizza!","tr":"— Pizza mı makarna mı, hangisini tercih edersin? — Pizza!"},{"en":"— What kind of music do you like? — I like pop.","tr":"— Ne tür müzik seversin? — Pop müzik severim."},{"en":"— I hate spiders. — Me too!","tr":"— Örümceklerden nefret ederim. — Ben de!"},{"en":"— I don't like rainy days. — Me neither.","tr":"— Yağmurlu günleri sevmem. — Ben de sevmem."},{"en":"I like football very much, but I prefer swimming.","tr":"Futbolu çok severim ama yüzmeyi tercih ederim."}],"test":[{"tip":"secim","soru":"Hangisi \"hiç dayanamamak\" anlamındadır, yani en güçlü sevmeme ifadesidir?","secenekler":["don't mind","like","can't stand"],"dogru":2,"aciklama":"Can't stand = hiç dayanamamak. Don't mind ise fark etmez demektir."},{"tip":"bosluk","soru":"I enjoy ___ in the sea.","tr":"Denizde yüzmekten hoşlanırım.","secenekler":["swimming","to swim","swim"],"dogru":0,"aciklama":"Enjoy'dan sonra fiil -ing alır: enjoy swimming."},{"tip":"bosluk","soru":"I prefer tea ___ milk.","tr":"Çayı süte tercih ederim.","secenekler":["than","to","from"],"dogru":1,"aciklama":"Kalıp prefer A to B şeklindedir: I prefer tea to milk."},{"tip":"secim","soru":"Arkadaşın \"I don't like broccoli.\" dedi. Sen de sevmiyorsun. Ne dersin?","secenekler":["Me too.","Me neither.","I don't too."],"dogru":1,"aciklama":"Olumsuz bir cümleye katılırken Me neither (Ben de sevmem) denir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Mert","can't","stand","loud","music"],"cevap":"Mert can't stand loud music.","tr":"Mert yüksek sesli müziğe hiç dayanamaz.","aciklama":"Can't stand + isim = hiç dayanamamak."},{"tip":"secim","soru":"\"Futbolu çok severim.\" cümlesinin doğru İngilizcesi hangisi?","secenekler":["I very like football.","I like very much football.","I like football very much."],"dogru":2,"aciklama":"Very much, sevilen şeyden sonra, cümlenin sonunda gelir."},{"tip":"bosluk","soru":"— Which do you ___, juice or milk? — Juice, please.","tr":"— Meyve suyu mu süt mü, hangisini tercih edersin? — Meyve suyu, lütfen.","secenekler":["prefer","preferring","prefers"],"dogru":0,"aciklama":"Do you'dan sonra fiil yalın gelir: Which do you prefer?"},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","kind","of","music","do","you","like"],"cevap":"What kind of music do you like?","tr":"Ne tür müzik seversin?","aciklama":"Kalıp: What kind of + isim + do you like?"},{"tip":"dogruyanlis","soru":"\"I don't mind\" kalıbı \"bana fark etmez, sorun değil\" anlamına gelir.","dogru":true,"aciklama":"Doğru! I don't mind washing the dishes = Bulaşık yıkamak bana sorun olmaz."},{"tip":"dogruyanlis","soru":"\"I am like chocolate.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Like bir fiildir, önüne am gelmez: I like chocolate."}],"kelimeSozlugu":{"love":{"tr":"çok sevmek, bayılmak","alt":""},"enjoy":{"tr":"hoşlanmak, keyif almak","alt":"ardından fiil-ing gelir"},"don't mind":{"tr":"fark etmez, sorun değil","alt":""},"hate":{"tr":"nefret etmek","alt":""},"can't stand":{"tr":"hiç dayanamamak","alt":""},"prefer":{"tr":"tercih etmek","alt":"prefer A to B"},"kind":{"tr":"tür, çeşit","alt":"what kind of = ne tür"},"neither":{"tr":"ben de (olumsuzda)","alt":"Me neither."}}}$dm$::jsonb where id = '7493a19d-21a8-43bd-ba02-e8ed481e6307' and topic_name = 'Talking about likes, dislikes and preferences — Beğeniler, Hoşlanılmayanlar ve Tercihler';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Başından geçen bir olayı, bir tatili ya da bir anıyı İngilizce anlatmayı öğreneceksin. Arkadaşına “Hiç ... yaptın mı?” diye sormayı ve onun anısına güzel bir cevap vermeyi de öğreneceksin.</p><h3>Zamanı söylüyorsan: geçmiş zaman</h3><p>Olayın ne zaman olduğunu söylüyorsan (yesterday, last summer, two years ago) <b>geçmiş zaman (past simple)</b> kullanırsın: <b>özne + fiilin 2. hâli</b>.</p><table><tr><th>Zaman ifadesi</th><th>Türkçe</th><th>Örnek</th></tr><tr><td>yesterday</td><td>dün</td><td><i>Yesterday I played chess with Can.</i></td></tr><tr><td>last summer</td><td>geçen yaz</td><td><i>Last summer I visited my grandparents.</i></td></tr><tr><td>two years ago</td><td>iki yıl önce</td><td><i>Two years ago we went to Antalya.</i></td></tr><tr><td>when I was six</td><td>altı yaşındayken</td><td><i>When I was six, I broke my arm.</i></td></tr></table><p>Soruda ve olumsuz cümlede <b>did</b> kullanılır, fiil yalın kalır: <i>Did you have fun?</i> (Eğlendin mi?) <i>I didn't like the food.</i> (Yemeği beğenmedim.)</p><h3>Zaman önemli değilse: Have you ever...?</h3><p>“Hayatında hiç ... yaptın mı?” diye sormak için <b>Have you ever + fiilin 3. hâli?</b> kalıbını kullanırsın. Burada ne zaman olduğu önemli değil, sadece o deneyimi yaşayıp yaşamadığın önemli.</p><ul><li><i>Have you ever been to Istanbul?</i> = Hiç İstanbul'a gittin mi?</li><li><i>Have you ever seen a snake?</i> = Hiç yılan gördün mü?</li><li>Cevap evet ise: <b>Yes, I have.</b> Hayır ise: <b>No, I haven't.</b> ya da kısaca <b>No, never.</b></li><li>Hiç yapmadığın bir şey için: <i>I have never eaten sushi.</i> = Hiç suşi yemedim.</li></ul><p>Arkadaşın “Yes, I have.” derse sohbet geçmiş zamanla devam eder: <i>When did you go?</i> (Ne zaman gittin?)</p><h3>Mini sohbet: anını anlat, ilgini göster</h3><p><i>Ece: Have you ever been to a water park?</i><br><i>Mert: Yes, I have. I went to one last summer.</i><br><i>Ece: Really? What was it like?</i><br><i>Mert: It was amazing! We had a great time.</i></p><ul><li>Anını anlatırken: <b>It was amazing / great / boring.</b> (Harikaydı / çok güzeldi / sıkıcıydı.) <b>We had a great time.</b> (Çok eğlendik.)</li><li>Arkadaşın anlatırken ilgini göster: <b>Really?</b> (Gerçekten mi?) <b>Wow, lucky you!</b> (Vay, şanslısın!) <b>That sounds fun!</b> (Kulağa eğlenceli geliyor!)</li><li>Eski bir anıyı hatırlarken: <b>I remember when...</b> (... zamanı hatırlıyorum.) <i>I remember when we won the match.</i></li></ul><h3>Dikkat!</h3><ul><li>Zamanı söylüyorsan have kullanma: <i>I have been to Izmir last summer.</i> yanlış → <i>I went to Izmir last summer.</i> doğru.</li><li>Did'den sonra fiil yalın olur: <i>Did you went?</i> → <i>Did you go?</i></li><li>Have you ever sorusuna did ile cevap verilmez: <i>Yes, I did.</i> → <i>Yes, I have.</i></li><li>Ever'dan sonra fiilin 3. hâli gelir: <i>Have you ever saw a lion?</i> → <i>Have you ever seen a lion?</i></li></ul><h3>Kısaca</h3><p>Zamanını söylediğin anılarda geçmiş zaman (I went, I visited), hayattaki deneyimleri sorarken Have you ever...? kullan. Anını “It was amazing!” gibi bir cümleyle bitir, arkadaşının anısına da “Really? Lucky you!” diye ilgi göster.</p>","ornekler":[{"en":"Last summer, I visited my grandparents in Izmir.","tr":"Geçen yaz İzmir'de büyükannemle büyükbabamı ziyaret ettim."},{"en":"— Have you ever been to Antalya? — Yes, I have.","tr":"— Hiç Antalya'ya gittin mi? — Evet, gittim."},{"en":"— Have you ever seen a snake? — No, never.","tr":"— Hiç yılan gördün mü? — Hayır, hiç görmedim."},{"en":"We won the football match last Saturday.","tr":"Geçen cumartesi futbol maçını kazandık."},{"en":"— What was it like? — It was amazing!","tr":"— Nasıldı? — Harikaydı!"},{"en":"When I was six, I broke my arm.","tr":"Altı yaşındayken kolumu kırdım."},{"en":"I have never eaten sushi.","tr":"Hiç suşi yemedim."},{"en":"We had a great time at the water park.","tr":"Su parkında çok eğlendik."},{"en":"I didn't like the camp food at all.","tr":"Kamptaki yemekleri hiç beğenmedim."},{"en":"— Did you have fun? — Yes, it was the best holiday ever.","tr":"— Eğlendin mi? — Evet, şimdiye kadarki en güzel tatildi."}],"test":[{"tip":"secim","soru":"Arkadaşın \"Have you ever been to Istanbul?\" diye sordu. Daha önce gittin. Ne cevap verirsin?","secenekler":["Yes, I have.","Yes, I did.","Yes, I was."],"dogru":0,"aciklama":"Have you ever...? sorusuna have ile cevap verilir: Yes, I have."},{"tip":"bosluk","soru":"Last summer I ___ my grandparents.","tr":"Geçen yaz büyükannemle büyükbabamı ziyaret ettim.","secenekler":["visit","visited","have visited"],"dogru":1,"aciklama":"Last summer bir geçmiş zaman ifadesidir, fiilin 2. hâli gelir: visited."},{"tip":"secim","soru":"Arkadaşın \"We went to Bodrum. It was great!\" dedi. En uygun tepki hangisi?","secenekler":["Yes, I have.","No, I didn't.","Wow, lucky you!"],"dogru":2,"aciklama":"Arkadaşının anısına ilgi göstermek için Wow, lucky you! (Vay, şanslısın!) dersin."},{"tip":"bosluk","soru":"Have you ever ___ a horse?","tr":"Hiç ata bindin mi?","secenekler":["ridden","rode","ride"],"dogru":0,"aciklama":"Have you ever'dan sonra fiilin 3. hâli gelir: ride, rode, ridden."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Have","you","ever","been","to","Antalya"],"cevap":"Have you ever been to Antalya?","tr":"Hiç Antalya'ya gittin mi?","aciklama":"Deneyim sorusu: Have you ever + fiilin 3. hâli?"},{"tip":"secim","soru":"\"Geçen yaz İzmir'e gittim.\" cümlesinin doğru İngilizcesi hangisi?","secenekler":["I have gone to Izmir last summer.","I went to Izmir last summer.","I go to Izmir last summer."],"dogru":1,"aciklama":"Last summer gibi bir zaman söylendiği için geçmiş zaman kullanılır: I went."},{"tip":"bosluk","soru":"— What was it like? — It ___ amazing!","tr":"— Nasıldı? — Harikaydı!","secenekler":["is","were","was"],"dogru":2,"aciklama":"Geçmişteki bir şeyi anlatıyoruz ve özne it: It was amazing!"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["It","was","the","best","holiday","ever"],"cevap":"It was the best holiday ever.","tr":"Şimdiye kadarki en güzel tatildi.","aciklama":"Anını anlatırken geçmiş zaman: It was ... Ever sonda: the best holiday ever."},{"tip":"dogruyanlis","soru":"\"Did you went to the cinema?\" Bu cümle doğru mu?","dogru":false,"aciklama":"Did'den sonra fiil yalın olur: Did you go to the cinema?"},{"tip":"secim","soru":"Arkadaşın \"Have you ever tried sushi?\" dedi. Hiç denemedin. Ne cevap verirsin?","secenekler":["No, I haven't.","No, I didn't.","No, I don't."],"dogru":0,"aciklama":"Have you ever...? sorusuna olumsuz cevap: No, I haven't. ya da No, never."}],"kelimeSozlugu":{"ever":{"tr":"hiç","alt":"sorularda: Have you ever...?"},"never":{"tr":"hiç, asla","alt":"olumsuz anlam verir"},"last":{"tr":"geçen","alt":"last summer = geçen yaz"},"ago":{"tr":"önce","alt":"two years ago = iki yıl önce"},"remember":{"tr":"hatırlamak","alt":""},"amazing":{"tr":"harika","alt":""},"visited":{"tr":"ziyaret etti","alt":"visit fiilinin geçmiş hâli"},"lucky":{"tr":"şanslı","alt":"Lucky you! = Şanslısın!"}}}$dm$::jsonb where id = 'ac306b89-cd96-4277-909c-b84e111147de' and topic_name = 'Talking about past experiences — Geçmiş Deneyimlerden Bahsetme';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir arkadaşına, ailene ya da öğretmenine İngilizce kısa bir mesaj veya e-posta yazmayı öğreneceksin. Birini partine davet edebilecek, teşekkür edebilecek, özür dileyebilecek ve gelen bir mesaja cevap verebileceksin.</p><h3>Bir mesajın beş parçası</h3><table><tr><th>Parça</th><th>Arkadaşa</th><th>Büyüklere (öğretmen, akraba)</th></tr><tr><td>1. Selamlama</td><td><i>Hi Ece,</i></td><td><i>Dear Mrs Brown,</i></td></tr><tr><td>2. Açılış</td><td><i>How are you?</i></td><td><i>I hope you are well.</i></td></tr><tr><td>3. Asıl mesaj</td><td>Neden yazdığını söyle: davet, teşekkür, haber.</td><td>Kısa ve açık yaz.</td></tr><tr><td>4. Kapanış</td><td><i>Write back soon! See you!</i></td><td><i>Thank you very much.</i></td></tr><tr><td>5. İmza</td><td><i>Love, Zeynep</i></td><td><i>Best wishes, Zeynep</i></td></tr></table><p>Selamlamadan sonra virgül koy ve mesaja yeni bir satırda başla. <b>Dear</b> (sevgili, değerli) büyüklere ve mektuplarda, <b>Hi</b> arkadaşlara yazılır. <b>Love</b> aile ve yakın arkadaşlar içindir; öğretmenine <b>Best wishes</b> yazmak daha uygundur.</p><h3>En çok kullanılan kalıplar</h3><table><tr><th>Ne yapmak istiyorsun?</th><th>İngilizce</th><th>Türkçe</th></tr><tr><td>Davet etmek</td><td><b>Would you like to come to my party?</b></td><td>Partime gelmek ister misin?</td></tr><tr><td>Teşekkür etmek</td><td><b>Thanks for the present!</b></td><td>Hediye için teşekkürler!</td></tr><tr><td>Daveti kabul etmek</td><td><b>Thanks for inviting me. I'd love to come!</b></td><td>Davet için teşekkürler. Gelmeyi çok isterim!</td></tr><tr><td>Daveti reddetmek</td><td><b>Sorry, I can't come.</b></td><td>Üzgünüm, gelemiyorum.</td></tr><tr><td>Geç cevap için özür</td><td><b>Sorry for my late reply.</b></td><td>Geç cevap verdiğim için özür dilerim.</td></tr><tr><td>Cevap istemek</td><td><b>Please let me know.</b></td><td>Lütfen bana haber ver.</td></tr></table><p>Birini davet etmek <b>invite</b> demektir. Davet ediyorsan günü ve saati yazmayı unutma: <i>on Saturday at three o'clock</i> (cumartesi saat üçte).</p><h3>Örnek bir mesaj</h3><p><i>Hi Mert,</i><br><i>How are you? I'm having a birthday party on Saturday at three o'clock. Would you like to come? Please let me know.</i><br><i>Write back soon!</i><br><i>Love, Elif</i></p><p>Mert'in cevabı: <i>Hi Elif, thanks for inviting me. I'd love to come! See you on Saturday. Mert</i></p><h3>Dikkat!</h3><ul><li><b>for</b>'dan sonra fiil -ing alır: <i>Thanks for invite me.</i> → <i>Thanks for inviting me.</i></li><li>Günlerle <b>on</b> kullanılır: <i>in Saturday</i> → <i>on Saturday</i></li><li>Would you like'tan sonra <b>to</b> gelir: <i>Would you like come?</i> → <i>Would you like to come?</i></li><li><b>looking forward to</b> kalıbında to'dan sonra -ing gelir: <i>I'm looking forward to see you.</i> → <i>I'm looking forward to seeing you.</i></li></ul><h3>Kısaca</h3><p>Mesajına Hi ya da Dear ile başla, neden yazdığını kısaca söyle ve Love ya da Best wishes ile adını yazarak bitir. Davet için Would you like to come...?, teşekkür için Thanks for... kalıbını kullan.</p>","ornekler":[{"en":"Hi Ece, how are you?","tr":"Merhaba Ece, nasılsın?"},{"en":"Dear Grandma, thank you for the lovely present.","tr":"Canım anneannem, güzel hediyen için çok teşekkür ederim."},{"en":"Would you like to come to my birthday party on Saturday?","tr":"Cumartesi doğum günü partime gelmek ister misin?"},{"en":"Thanks for inviting me. I'd love to come!","tr":"Beni davet ettiğin için teşekkürler. Gelmeyi çok isterim!"},{"en":"Sorry, I can't come. I've got a football match.","tr":"Üzgünüm, gelemiyorum. Futbol maçım var."},{"en":"Sorry for my late reply.","tr":"Geç cevap verdiğim için özür dilerim."},{"en":"Please let me know if you can come.","tr":"Gelip gelemeyeceğini lütfen bana haber ver."},{"en":"I'm looking forward to seeing you.","tr":"Seni görmeyi dört gözle bekliyorum."},{"en":"Write back soon! Best wishes, Deniz","tr":"Yakında cevap yaz! En iyi dileklerimle, Deniz"},{"en":"See you on Saturday! Love, Zeynep","tr":"Cumartesi görüşürüz! Sevgiler, Zeynep"}],"test":[{"tip":"secim","soru":"Öğretmenine e-posta yazıyorsun. Hangisiyle başlamak uygun?","secenekler":["Hey!","Dear Mrs Brown,","Love, Mrs Brown"],"dogru":1,"aciklama":"Büyüklere Dear + isim ile başlarız. Love mesajın sonunda, imzadan önce yazılır."},{"tip":"bosluk","soru":"Thanks ___ the lovely present!","tr":"Güzel hediye için teşekkürler!","secenekler":["to","of","for"],"dogru":2,"aciklama":"Bir şey için teşekkür ederken Thanks for ... deriz."},{"tip":"secim","soru":"Arkadaşına yazdığın mesajı nasıl bitirirsin?","secenekler":["Dear, Ece","Love, Ece","Hello, Ece"],"dogru":1,"aciklama":"Arkadaşa ya da aileye yazılan mesaj Love + adın ile biter. Dear ve Hello başta kullanılır."},{"tip":"bosluk","soru":"Would you like ___ to my party?","tr":"Partime gelmek ister misin?","secenekler":["come","coming","to come"],"dogru":2,"aciklama":"Kalıp: Would you like to + fiil? (... ister misin?)"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Sorry","for","my","late","reply"],"cevap":"Sorry for my late reply.","tr":"Geç cevap verdiğim için özür dilerim.","aciklama":"Geç cevap verince mesaja Sorry for my late reply ile başlayabilirsin."},{"tip":"secim","soru":"Ali yazmış: \"Can you come to my party on Saturday?\" Gidemiyorsun. En iyi cevap hangisi?","secenekler":["Sorry, I can't come. I've got a swimming lesson.","No. I don't want.","Yes, I can't come."],"dogru":0,"aciklama":"Kibarca reddederken Sorry, I can't come deyip kısaca nedenini söyleriz."},{"tip":"bosluk","soru":"I'm looking forward to ___ you.","tr":"Seni görmeyi dört gözle bekliyorum.","secenekler":["seeing","see","saw"],"dogru":0,"aciklama":"looking forward to kalıbından sonra fiil -ing alır: seeing."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Thanks","for","inviting","me","to","your","party"],"cevap":"Thanks for inviting me to your party.","tr":"Beni partine davet ettiğin için teşekkürler.","aciklama":"Thanks for + fiil-ing: Thanks for inviting me."},{"tip":"dogruyanlis","soru":"\"Thanks for invite me.\" Bu cümle doğru mu?","dogru":false,"aciklama":"for'dan sonra fiil -ing alır: Thanks for inviting me."},{"tip":"secim","soru":"Arkadaşın mesajının sonuna \"Write back soon!\" yazmış. Ne demek istiyor?","secenekler":["Hemen geri gel!","Yakında tekrar oku!","Bana yakında cevap yaz!"],"dogru":2,"aciklama":"Write back = cevap yazmak. Write back soon! = Bana yakında cevap yaz!"}],"kelimeSozlugu":{"dear":{"tr":"sevgili, değerli","alt":"mektup ve e-posta başında"},"love":{"tr":"sevgiler","alt":"mesajın sonunda"},"best wishes":{"tr":"en iyi dileklerimle","alt":"kibar kapanış"},"invite":{"tr":"davet etmek","alt":""},"reply":{"tr":"cevap","alt":""},"let me know":{"tr":"bana haber ver","alt":""},"write back":{"tr":"cevap yazmak","alt":""},"looking forward to":{"tr":"dört gözle beklemek","alt":"ardından fiil -ing"}}}$dm$::jsonb where id = '1e4e6968-59ce-432b-9849-0e2cba4942f4' and topic_name = 'Writing simple personal messages and emails — Basit Kişisel Mesajlar ve E-postalar Yazma';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir işin <b>nasıl</b>, <b>nerede</b> ve <b>ne zaman</b> yapıldığını anlatmayı öğreneceksin. Bunun için <b>zarflar</b> (adverbs: quickly, well) ve <b>zarf öbekleri</b> (adverbial phrases: in the park, after school) kullanılır.</p><h3>Sıfattan zarf yapmak: -ly</h3><p>Çoğu zarf, sıfatın sonuna <b>-ly</b> eklenerek yapılır. Türkçedeki <b>-ce / -ca</b> ya da <b>... bir şekilde</b> gibidir.</p><table><tr><th>Sıfat</th><th>Zarf</th><th>Anlamı</th></tr><tr><td>quick</td><td><b>quickly</b></td><td>hızlıca</td></tr><tr><td>quiet</td><td><b>quietly</b></td><td>sessizce</td></tr><tr><td>careful</td><td><b>carefully</b></td><td>dikkatlice</td></tr><tr><td>loud</td><td><b>loudly</b></td><td>yüksek sesle</td></tr><tr><td>happy</td><td><b>happily</b></td><td>mutlu bir şekilde (y → i olur)</td></tr><tr><td>beautiful</td><td><b>beautifully</b></td><td>güzel bir şekilde</td></tr></table><h3>Kuralsız zarflar</h3><p>Bazı zarflar -ly almaz. Bunları ezberle:</p><ul><li><b>good → well</b>: <i>Zeynep speaks English very well.</i> (çok iyi)</li><li><b>fast → fast</b>: <i>Mert runs very fast.</i> (çok hızlı)</li><li><b>hard → hard</b>: <i>She works hard.</i> (sıkı, çok)</li><li><b>early → early</b>, <b>late → late</b>: <i>I get up early.</i></li></ul><h3>Sıfat mı, zarf mı? Nereye konur?</h3><ul><li>Sıfat ismi ya da be fiilini anlatır: <i>She is quiet.</i> (O sessiz.)</li><li>Zarf fiili anlatır: <i>She speaks quietly.</i> (Sessizce konuşur.)</li><li>Zarf genelde fiilden ya da nesneden <b>sonra</b> gelir: <i>Ece draws pictures carefully.</i> Fiil ile nesnenin arasına girmez.</li></ul><p><b>Zarf öbekleri</b> birkaç kelimeden oluşur ve yer, zaman ya da nasıl olduğunu anlatır: <i>in the garden</i>, <i>after school</i>, <i>every day</i>, <i>by bus</i>. Sıra genelde <b>nasıl → nerede → ne zaman</b>: <i>Papi sings loudly in the garden every morning.</i> Ama go, come gibi hareket fiillerinde yer önce gelir: <i>We go to school by bus every day.</i></p><h3>Dikkat!</h3><ul><li><i>He runs quick.</i> yanlış → <i>He runs quickly.</i></li><li><i>She speaks English good.</i> yanlış → <i>She speaks English well.</i></li><li>fastly diye bir kelime yok: <i>He drives fastly.</i> yanlış → <i>He drives fast.</i></li><li><i>She reads carefully the book.</i> yanlış → <i>She reads the book carefully.</i></li></ul><h3>Kısaca</h3><p>Fiilin nasıl yapıldığını anlatmak için sıfata çoğunlukla <b>-ly</b> ekle; good kelimesinin zarfı <b>well</b>, fast kelimesininki yine <b>fast</b>. Zarfı fiilden ya da nesneden sonra koy.</p>","ornekler":[{"en":"Mert runs very fast.","tr":"Mert çok hızlı koşar."},{"en":"Please speak quietly in the library.","tr":"Lütfen kütüphanede sessizce konuş."},{"en":"Ece draws pictures carefully.","tr":"Ece resimleri dikkatlice çizer."},{"en":"The children are playing happily in the garden.","tr":"Çocuklar bahçede mutlu mutlu oynuyor."},{"en":"Zeynep speaks English very well.","tr":"Zeynep çok iyi İngilizce konuşur."},{"en":"We go to school by bus every day.","tr":"Her gün okula otobüsle gideriz."},{"en":"Can answered the question correctly.","tr":"Can soruyu doğru cevapladı."},{"en":"Papi sings loudly in the morning.","tr":"Papi sabahları yüksek sesle şarkı söyler."},{"en":"I did my homework quickly after school.","tr":"Okuldan sonra ödevimi hızlıca yaptım."},{"en":"Deniz plays the piano beautifully.","tr":"Deniz çok güzel piyano çalar."}],"test":[{"tip":"secim","soru":"\"careful\" sıfatının zarf hali hangisi?","secenekler":["carefuly","carefully","carefull"],"dogru":1,"aciklama":"careful + ly = carefully; iki l olur."},{"tip":"bosluk","soru":"Zeynep speaks English very ___.","tr":"Zeynep çok iyi İngilizce konuşur.","secenekler":["well","good","goodly"],"dogru":0,"aciklama":"good sıfatının zarf hali well'dir: speaks very well."},{"tip":"bosluk","soru":"Mert runs very ___.","tr":"Mert çok hızlı koşar.","secenekler":["fastly","speedy","fast"],"dogru":2,"aciklama":"fast zarf olarak da fast kalır; fastly diye bir kelime yoktur."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["She reads carefully the book.","She reads the book careful.","She reads the book carefully."],"dogru":2,"aciklama":"Zarf (carefully) nesneden sonra gelir: reads the book carefully."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Zeynep","speaks","English","very","well"],"cevap":"Zeynep speaks English very well.","tr":"Zeynep çok iyi İngilizce konuşur.","aciklama":"very well, fiil ve nesneden (speaks English) sonra gelir."},{"tip":"bosluk","soru":"She is very quiet. She speaks ___.","tr":"O çok sessiz. Sessizce konuşur.","secenekler":["quiet","quietly","quieter"],"dogru":1,"aciklama":"speak bir fiildir; fiili zarf anlatır: speaks quietly."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Mert","runs","very","fast"],"cevap":"Mert runs very fast.","tr":"Mert çok hızlı koşar.","aciklama":"Zarf fiilden sonra gelir: runs very fast."},{"tip":"secim","soru":"\"happy\" sıfatının zarf hali hangisi?","secenekler":["happily","happyly","happy"],"dogru":0,"aciklama":"Sondaki y harfi i olur ve ly eklenir: happily."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Papi","sings","very","loudly"],"cevap":"Papi sings very loudly.","tr":"Papi çok yüksek sesle şarkı söyler.","aciklama":"Zarf (very loudly) fiilden (sings) sonra gelir."},{"tip":"dogruyanlis","soru":"\"He drives fastly.\" Bu cümle doğru mu?","dogru":false,"aciklama":"fast zarf olarak değişmez: He drives fast."}],"kelimeSozlugu":{"quickly":{"tr":"hızlıca","alt":"quick + ly"},"quietly":{"tr":"sessizce","alt":"quiet + ly"},"carefully":{"tr":"dikkatlice","alt":"careful + ly"},"happily":{"tr":"mutlu bir şekilde","alt":"happy: y → i"},"well":{"tr":"iyi (bir şekilde)","alt":"good kelimesinin zarfı"},"fast":{"tr":"hızlı","alt":"zarf hali de fast"},"loudly":{"tr":"yüksek sesle","alt":""},"beautifully":{"tr":"güzel bir şekilde","alt":""}}}$dm$::jsonb where id = '39d7a767-04ef-452d-bec4-9e4fb4605509' and topic_name = 'Adverbs and adverbial phrases — Zarflar ve Zarf Öbekleri';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Önceden karar verdiğin <b>planlarını</b> ve gördüğün bir şeye bakarak yaptığın <b>tahminleri</b> İngilizce söylemeyi öğreneceksin. Bunun için <b>be going to</b> kalıbını kullanacağız. Türkçedeki <b>-acak, -ecek</b> ekinin karşılığıdır.</p><h3>Kalıp: am / is / are + going to + fiil</h3><table><tr><th>Kişi</th><th>Olumlu</th><th>Olumsuz</th><th>Soru</th></tr><tr><td>I</td><td>I <b>am going to</b> play</td><td>I'm <b>not</b> going to play</td><td><b>Am</b> I going to play?</td></tr><tr><td>he / she / it</td><td>she <b>is going to</b> play</td><td>she <b>isn't</b> going to play</td><td><b>Is</b> she going to play?</td></tr><tr><td>you / we / they</td><td>we <b>are going to</b> play</td><td>we <b>aren't</b> going to play</td><td><b>Are</b> we going to play?</td></tr></table><p>Kısa cevaplar: <i>Yes, I am. / No, I'm not.</i> <i>Yes, she is. / No, she isn't.</i></p><p>Soru kelimesiyle: <i>What are you going to do this summer?</i> = Bu yaz ne yapacaksın?</p><h3>1. Planlar ve niyetler</h3><p>Konuşmadan <b>önce</b> karar verdiğin şeyler için kullanılır. Bu kararı vermişsin, şimdi sadece anlatıyorsun.</p><ul><li><i>I am going to visit my grandma tomorrow.</i> = Yarın büyükannemi ziyaret edeceğim.</li><li><i>Zeynep is going to learn the piano.</i> = Zeynep piyano öğrenecek.</li></ul><p>Sık kullanılan zaman ifadeleri: <b>tomorrow</b> (yarın), <b>tonight</b> (bu gece), <b>this weekend</b> (bu hafta sonu), <b>next week</b> (gelecek hafta), <b>next year</b> (seneye).</p><h3>2. Gördüğüne bakarak tahmin</h3><p>Şu an bir işaret görüyorsan ve ne olacağı belliyse be going to kullanırsın.</p><ul><li><i>Look at those dark clouds! It's going to rain.</i> = Şu kara bulutlara bak! Yağmur yağacak.</li><li><i>Be careful! You're going to fall!</i> = Dikkat et! Düşeceksin!</li></ul><p>Konuşurken insanlar <i>going to</i> yerine hızlıca “gonna” der. Bunu duyabilirsin ama yazarken her zaman <b>going to</b> yaz.</p><h3>Dikkat!</h3><ul><li>am / is / are'yi unutma: <i>I going to swim.</i> → <i>I am going to swim.</i></li><li>going to'dan sonra fiil yalın gelir: <i>She is going to visits us.</i> → <i>She is going to visit us.</i></li><li>Fiil -ing almaz: <i>Are you going to playing?</i> → <i>Are you going to play?</i></li><li>to'yu unutma: <i>We are going watch a film.</i> → <i>We are going to watch a film.</i></li></ul><h3>Kısaca</h3><p>Önceden yaptığın planlar ve gördüğün işaretlere bakarak yaptığın tahminler için <b>am / is / are + going to + fiil</b> kullan. Olumsuzda not, soruda am / is / are başa gelir.</p>","ornekler":[{"en":"I am going to visit my grandma tomorrow.","tr":"Yarın büyükannemi ziyaret edeceğim."},{"en":"Zeynep is going to learn the piano.","tr":"Zeynep piyano öğrenecek."},{"en":"We are going to have a picnic on Sunday.","tr":"Pazar günü piknik yapacağız."},{"en":"Look at those dark clouds! It's going to rain.","tr":"Şu kara bulutlara bak! Yağmur yağacak."},{"en":"Be careful! You're going to fall!","tr":"Dikkat et! Düşeceksin!"},{"en":"Mert isn't going to play today. He's ill.","tr":"Mert bugün oynamayacak. Hasta."},{"en":"They aren't going to watch the match tonight.","tr":"Bu gece maçı izlemeyecekler."},{"en":"Are you going to come to my birthday party?","tr":"Doğum günü partime gelecek misin?"},{"en":"What are you going to do this summer?","tr":"Bu yaz ne yapacaksın?"},{"en":"Papi is going to sing a new song for us.","tr":"Papi bize yeni bir şarkı söyleyecek."}],"test":[{"tip":"bosluk","soru":"I ___ going to buy a new ball.","tr":"Yeni bir top alacağım.","secenekler":["is","am","are"],"dogru":1,"aciklama":"I ile am kullanılır: I am going to ..."},{"tip":"bosluk","soru":"They are going to ___ a sandcastle.","tr":"Kumdan kale yapacaklar.","secenekler":["build","building","built"],"dogru":0,"aciklama":"Going to'dan sonra fiil yalın gelir: going to build."},{"tip":"secim","soru":"Gökyüzü kapkaranlık. \"Yağmur yağacak.\" demek için hangisi doğru?","secenekler":["It is going rain.","It is going to rain.","It going to rain."],"dogru":1,"aciklama":"Tam kalıp: is + going to + fiil. Ne is ne de to unutulmamalı."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We're","going","to","have","a","picnic"],"cevap":"We're going to have a picnic.","tr":"Piknik yapacağız.","aciklama":"Plan: We're (We are) + going to + yalın fiil."},{"tip":"secim","soru":"Zeynep'e hafta sonu planını sor. Hangisi doğru?","secenekler":["What are you going to do this weekend?","What you are going to do this weekend?","What are you going do this weekend?"],"dogru":0,"aciklama":"Soruda are, you'dan önce gelir: What are you going to do ...?"},{"tip":"bosluk","soru":"___ your parents going to come to the school show?","tr":"Annen ve baban okul gösterisine gelecek mi?","secenekler":["Is","Do","Are"],"dogru":2,"aciklama":"Your parents = they; they ile Are kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Where","are","you","going","to","stay"],"cevap":"Where are you going to stay?","tr":"Nerede kalacaksın?","aciklama":"Soru kelimesi + are + you + going to + fiil."},{"tip":"secim","soru":"\"Deniz yarın dedesini ziyaret edecek.\" cümlesinin İngilizcesi hangisi?","secenekler":["Deniz going to visit his grandpa tomorrow.","Deniz is going to visits his grandpa tomorrow.","Deniz is going to visit his grandpa tomorrow."],"dogru":2,"aciklama":"Deniz = he; is + going to + yalın fiil: is going to visit."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I'm","not","going","to","tell","anyone"],"cevap":"I'm not going to tell anyone.","tr":"Kimseye söylemeyeceğim.","aciklama":"Olumsuz: I'm not + going to + yalın fiil."},{"tip":"dogruyanlis","soru":"\"She is going to watches a film tonight.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Going to'dan sonra fiil yalın gelir: She is going to watch a film tonight."}],"kelimeSozlugu":{"going to":{"tr":"-acak, -ecek","alt":"plan ve tahmin"},"tomorrow":{"tr":"yarın","alt":""},"tonight":{"tr":"bu gece","alt":""},"next week":{"tr":"gelecek hafta","alt":""},"this weekend":{"tr":"bu hafta sonu","alt":""},"look":{"tr":"bak","alt":"Look! = Bak!"}}}$dm$::jsonb where id = '8e083a7b-b988-4d6e-9fc2-f5196b836ceb' and topic_name = 'Be going to (plans and intentions) — Gelecek Planları ve Niyetler';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Günlük hayatta çok kullanılan <b>deyimsel fiilleri</b> (phrasal verbs) öğreneceksin: <i>wake up, turn on, look for</i> gibi. Sabah kalkmaktan ışığı kapatmaya kadar her gün bunlara ihtiyacın olacak.</p><h3>Deyimsel fiil nedir?</h3><p>Bir fiil ile <b>up, down, on, off, after, for</b> gibi küçük bir kelime yan yana gelir ve <b>yeni bir anlam</b> oluşur.</p><ul><li><b>look</b> = bakmak, <b>look for</b> = aramak, <b>look after</b> = bakmak, ilgilenmek</li><li><b>turn</b> = dönmek, <b>turn on</b> = açmak (ışık, televizyon), <b>turn off</b> = kapatmak</li><li><b>stand</b> = ayakta durmak, <b>stand up</b> = ayağa kalkmak</li><li><b>wake up</b> = uyanmak (gözünü açmak), <b>get up</b> = yataktan kalkmak</li></ul><h3>Her gün kullandığımız deyimsel fiiller</h3><table><tr><th>Deyimsel fiil</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>wake up</b></td><td>uyanmak</td><td><i>I wake up at seven.</i></td></tr><tr><td><b>get up</b></td><td>yataktan kalkmak</td><td><i>Mert gets up early.</i></td></tr><tr><td><b>put on</b></td><td>giymek (üstüne geçirmek)</td><td><i>Put on your coat.</i></td></tr><tr><td><b>take off</b></td><td>çıkarmak (giysi)</td><td><i>Take off your shoes.</i></td></tr><tr><td><b>turn on / turn off</b></td><td>açmak / kapatmak (elektrikli şey)</td><td><i>Turn off the lights.</i></td></tr><tr><td><b>sit down / stand up</b></td><td>oturmak / ayağa kalkmak</td><td><i>Sit down, please.</i></td></tr><tr><td><b>look for</b></td><td>aramak</td><td><i>I'm looking for my pencil.</i></td></tr><tr><td><b>look after</b></td><td>bakmak, ilgilenmek</td><td><i>Can you look after my cat?</i></td></tr><tr><td><b>give back</b></td><td>geri vermek</td><td><i>Please give my ruler back.</i></td></tr></table><h3>Nesne nereye gelir?</h3><p><b>turn on, turn off, put on, take off, give back</b> gibi fiillerde nesne iki yere de gelebilir: <i>Turn on the TV.</i> = <i>Turn the TV on.</i></p><p>Ama nesne <b>it, them</b> gibi bir zamirse <b>ortaya</b> gelmek zorundadır: <i>Turn it on.</i> doğru, <i>Turn on it.</i> yanlış.</p><h3>Dikkat!</h3><ul><li>Türkçede ışığı açarız ama İngilizcede open denmez: <i>Open the light.</i> yanlış → <i>Turn on the light.</i></li><li>Televizyonu kapatırken close değil: <i>Close the TV.</i> yanlış → <i>Turn off the TV.</i></li><li>Zamir ortaya gelir: <i>Turn off it.</i> yanlış → <i>Turn it off.</i></li><li>look for ile look after karışmasın: <i>I'm looking after my keys.</i> yanlış → <i>I'm looking for my keys.</i></li></ul><h3>Kısaca</h3><p>Deyimsel fiiller fiil ile küçük bir kelimenin birleşmesidir ve yeni bir anlam taşır. Elektrikli şeyleri <b>turn on / turn off</b> ile açıp kapat, zamiri her zaman ortaya koy: <b>turn it off</b>.</p>","ornekler":[{"en":"I wake up at seven every morning.","tr":"Her sabah saat yedide uyanırım."},{"en":"Please turn off the lights when you leave.","tr":"Çıkarken lütfen ışıkları kapat."},{"en":"Put on your coat. It's cold outside.","tr":"Montunu giy. Dışarısı soğuk."},{"en":"Can you look after my cat this weekend?","tr":"Bu hafta sonu kedime bakabilir misin?"},{"en":"I'm looking for my red pencil.","tr":"Kırmızı kalemimi arıyorum."},{"en":"Take off your shoes, please.","tr":"Lütfen ayakkabılarını çıkar."},{"en":"Sit down and open your books.","tr":"Oturun ve kitaplarınızı açın."},{"en":"Please give my ruler back.","tr":"Lütfen cetvelimi geri ver."},{"en":"Turn the TV on, please. My favourite show is starting.","tr":"Televizyonu aç lütfen. En sevdiğim program başlıyor."},{"en":"Mert gets up early on school days.","tr":"Mert okul günlerinde erken kalkar."}],"test":[{"tip":"secim","soru":"\"Işığı aç.\" cümlesinin İngilizcesi hangisi?","secenekler":["Turn on the light.","Open the light.","Close the light."],"dogru":0,"aciklama":"Elektrikli şeyleri açmak için turn on kullanılır; open denmez."},{"tip":"bosluk","soru":"Can you look ___ my cat this weekend?","tr":"Bu hafta sonu kedime bakabilir misin?","secenekler":["for","at","after"],"dogru":2,"aciklama":"Birine ya da bir hayvana bakmak, ilgilenmek: look after."},{"tip":"bosluk","soru":"I'm looking ___ my red pencil. Where is it?","tr":"Kırmızı kalemimi arıyorum. Nerede?","secenekler":["after","for","up"],"dogru":1,"aciklama":"Aramak anlamında look for kullanılır."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["Turn off it, please.","Turn it off, please.","Close it off, please."],"dogru":1,"aciklama":"Nesne it gibi bir zamirse ortaya gelir: Turn it off."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I'm","looking","for","my","keys"],"cevap":"I'm looking for my keys.","tr":"Anahtarlarımı arıyorum.","aciklama":"Aramak anlamında look for kullanılır; for, look kelimesinden hemen sonra gelir."},{"tip":"bosluk","soru":"It's cold. Put ___ your coat.","tr":"Hava soğuk. Montunu giy.","secenekler":["off","up","on"],"dogru":2,"aciklama":"Giysi giymek için put on kullanılır; take off çıkarmaktır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Grandma","looks","after","our","cat"],"cevap":"Grandma looks after our cat.","tr":"Kedimize büyükannem bakıyor.","aciklama":"look after bir bütündür; arasına başka kelime girmez."},{"tip":"secim","soru":"Öğretmen \"Ayağa kalkın, lütfen.\" demek istiyor. Ne der?","secenekler":["Stand up, please.","Sit down, please.","Get off, please."],"dogru":0,"aciklama":"Ayağa kalkmak stand up, oturmak sit down demektir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Mert","gets","up","early"],"cevap":"Mert gets up early.","tr":"Mert erken kalkar.","aciklama":"get up = yataktan kalkmak; he, she ile gets up olur."},{"tip":"dogruyanlis","soru":"\"look for\" aramak, \"look after\" ise bakmak, ilgilenmek demektir.","dogru":true,"aciklama":"Doğru! I'm looking for my keys. Can you look after my cat?"}],"kelimeSozlugu":{"wake up":{"tr":"uyanmak","alt":""},"get up":{"tr":"yataktan kalkmak","alt":""},"put on":{"tr":"giymek","alt":""},"take off":{"tr":"çıkarmak (giysi)","alt":""},"turn on":{"tr":"açmak","alt":"ışık, televizyon"},"turn off":{"tr":"kapatmak","alt":"ışık, televizyon"},"look for":{"tr":"aramak","alt":""},"look after":{"tr":"bakmak, ilgilenmek","alt":""},"sit down":{"tr":"oturmak","alt":""},"stand up":{"tr":"ayağa kalkmak","alt":""}}}$dm$::jsonb where id = 'a8680140-201d-4ed1-90e3-8579f91f7eed' and topic_name = 'Common phrasal verbs — Yaygın Deyimsel Fiiller (Phrasal Verbs)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>İki şeyi karşılaştırmayı (<b>daha</b> büyük, <b>daha</b> güzel) ve bir grubun içinde <b>en</b> ... olanı söylemeyi (en hızlı, en iyi) öğreneceksin. Karşılaştırma için <b>comparative</b>, en üstün olan için <b>superlative</b> kullanılır.</p><h3>Kısa sıfatlar: -er ve the -est</h3><p>Tek heceli sıfatlara (ve -y ile bitenlere) ek getiririz. Karşılaştırmada <b>than</b> (-den, -dan) kullanılır: <i>Ali is taller than his brother.</i> = Ali erkek kardeşinden daha uzun.</p><table><tr><th>Kural</th><th>Sıfat</th><th>Daha ...</th><th>En ...</th></tr><tr><td>Çoğu sıfat</td><td>tall</td><td>tall<b>er</b></td><td>the tall<b>est</b></td></tr><tr><td>-e ile biten</td><td>nice</td><td>nice<b>r</b></td><td>the nice<b>st</b></td></tr><tr><td>Sesli + sessiz ile biten</td><td>big</td><td>big<b>ger</b></td><td>the big<b>gest</b></td></tr><tr><td>-y ile biten</td><td>happy</td><td>happ<b>ier</b></td><td>the happ<b>iest</b></td></tr></table><h3>Uzun sıfatlar: more ve the most</h3><p>İki ya da daha fazla heceli sıfatların çoğuna ek getirmeyiz, önüne <b>more</b> (daha) ya da <b>the most</b> (en) koyarız.</p><ul><li>beautiful → <b>more</b> beautiful → <b>the most</b> beautiful</li><li>exciting → <b>more</b> exciting → <b>the most</b> exciting</li><li>expensive → <b>more</b> expensive → <b>the most</b> expensive</li></ul><p><i>This game is more exciting than that one.</i> = Bu oyun ötekinden daha heyecanlı.</p><h3>Düzensizler ve “en” cümleleri</h3><table><tr><th>Sıfat</th><th>Daha ...</th><th>En ...</th></tr><tr><td>good (iyi)</td><td><b>better</b></td><td><b>the best</b></td></tr><tr><td>bad (kötü)</td><td><b>worse</b></td><td><b>the worst</b></td></tr><tr><td>far (uzak)</td><td><b>farther</b></td><td><b>the farthest</b></td></tr></table><p>“En” cümlelerinde sıfattan önce mutlaka <b>the</b> gelir. Yer ve grup için genelde <b>in</b> ya da <b>of</b> kullanılır: <i>Ece is the youngest student in our class.</i> <i>Monday is the worst day of the week!</i></p><h3>Dikkat!</h3><ul><li>more ve -er birlikte kullanılmaz: <i>more taller</i> → <i>taller</i></li><li>Türkçedeki “-den” için from değil than: <i>bigger from a dog</i> → <i>bigger than a dog</i></li><li>good için düzensiz hal: <i>the most good</i> → <i>the best</i>, <i>gooder</i> → <i>better</i>.</li><li>bad de düzensizdir: <i>badder</i> → <i>worse</i>, <i>the baddest</i> → <i>the worst</i></li><li>“En” derken the'yi unutma: <i>She is tallest girl.</i> → <i>She is the tallest girl.</i></li></ul><h3>Kısaca</h3><p>İki şeyi karşılaştırırken kısa sıfatlara <b>-er</b>, uzun sıfatlara <b>more</b> ekle ve <b>than</b> kullan. En üstün olanı söylerken <b>the -est</b> ya da <b>the most</b> kullan; good ve bad düzensizdir.</p>","ornekler":[{"en":"An elephant is bigger than a horse.","tr":"Fil attan daha büyüktür."},{"en":"Ali is taller than his brother.","tr":"Ali erkek kardeşinden daha uzun."},{"en":"My bag is heavier than your bag.","tr":"Benim çantam seninkinden daha ağır."},{"en":"This game is more exciting than that one.","tr":"Bu oyun ötekinden daha heyecanlı."},{"en":"The cheetah is the fastest animal on land.","tr":"Çita karadaki en hızlı hayvandır."},{"en":"Ece is the youngest student in our class.","tr":"Ece sınıfımızdaki en küçük öğrenci."},{"en":"This is the most beautiful beach in Turkey.","tr":"Bu, Türkiye'deki en güzel plaj."},{"en":"Papi is the best parrot in the world!","tr":"Papi dünyanın en iyi papağanı!"},{"en":"Monday is the worst day of the week!","tr":"Pazartesi haftanın en kötü günü!"},{"en":"Is Antalya hotter than Ankara in summer?","tr":"Yazın Antalya, Ankara'dan daha sıcak mı?"}],"test":[{"tip":"secim","soru":"\"big\" sıfatının \"daha büyük\" hali hangisi?","secenekler":["biger","bigger","more big"],"dogru":1,"aciklama":"Big sesli + sessiz ile biter; son harf ikilenir: bigger."},{"tip":"bosluk","soru":"A car is faster ___ a bike.","tr":"Araba bisikletten daha hızlıdır.","secenekler":["than","from","that"],"dogru":0,"aciklama":"Karşılaştırmada -den, -dan karşılığı than'dir."},{"tip":"bosluk","soru":"This is the ___ book in the library.","tr":"Bu, kütüphanedeki en ilginç kitap.","secenekler":["more interesting","interestingest","most interesting"],"dogru":2,"aciklama":"Interesting uzun bir sıfattır; en için the most interesting olur."},{"tip":"secim","soru":"\"good\" sıfatının \"en iyi\" hali hangisi?","secenekler":["the best","the goodest","the most good"],"dogru":0,"aciklama":"Good düzensizdir: good, better, the best."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["She's","two","years","older","than","me"],"cevap":"She's two years older than me.","tr":"O benden iki yaş büyük.","aciklama":"Kalıp: kişi + is ('s) + sıfat-er + than + diğeri."},{"tip":"secim","soru":"\"Zeynep sınıftaki en mutlu kız.\" cümlesinin İngilizcesi hangisi?","secenekler":["Zeynep is happiest girl in the class.","Zeynep is the most happy girl in the class.","Zeynep is the happiest girl in the class."],"dogru":2,"aciklama":"Happy -y ile biter: the happiest. En derken the unutulmaz."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["It's","the","worst","pizza","ever"],"cevap":"It's the worst pizza ever.","tr":"Bu şimdiye kadarki en kötü pizza.","aciklama":"Bad düzensizdir; en kötü = the worst."},{"tip":"bosluk","soru":"My new phone is ___ than my old one.","tr":"Yeni telefonum eskisinden daha pahalı.","secenekler":["expensiver","more expensive","most expensive"],"dogru":1,"aciklama":"Expensive uzun bir sıfattır; daha için more expensive olur."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","swim","faster","than","my","brother"],"cevap":"I swim faster than my brother.","tr":"Erkek kardeşimden daha hızlı yüzerim.","aciklama":"Fiilden sonra karşılaştırma: swim faster than my brother."},{"tip":"dogruyanlis","soru":"\"My dog is more small than your dog.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Small kısa bir sıfattır, -er alır: My dog is smaller than your dog."}],"kelimeSozlugu":{"than":{"tr":"-den, -dan","alt":"karşılaştırmada"},"more":{"tr":"daha","alt":"uzun sıfatlarla"},"the most":{"tr":"en","alt":"uzun sıfatlarla"},"better":{"tr":"daha iyi","alt":"good"},"the best":{"tr":"en iyi","alt":"good"},"worse":{"tr":"daha kötü","alt":"bad"},"fastest":{"tr":"en hızlı","alt":"fast"},"bigger":{"tr":"daha büyük","alt":"big"}}}$dm$::jsonb where id = '3a11104d-5e10-4a6e-9692-1110d80da582' and topic_name = 'Comparatives and superlatives — Karşılaştırma ve Üstünlük Sıfatları';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>İki cümleyi <b>bağlaçlarla</b> (conjunctions) birleştirmeyi öğreneceksin. Böylece bir şeyin <b>sebebini</b>, <b>sonucunu</b> ya da <b>beklenmedik</b> bir durumu tek cümlede anlatabileceksin.</p><h3>Basit bağlaçlar: and, but, or</h3><table><tr><th>Bağlaç</th><th>Anlamı</th><th>Örnek</th></tr><tr><td><b>and</b></td><td>ve</td><td><i>I like cats and dogs.</i></td></tr><tr><td><b>but</b></td><td>ama, fakat</td><td><i>Can is tired, but he wants to play.</i></td></tr><tr><td><b>or</b></td><td>veya, ya da</td><td><i>Do you want juice or milk?</i></td></tr></table><h3>Sebep ve sonuç: because, so</h3><ul><li><b>because</b> = çünkü. Arkasından <b>sebep</b> gelir: <i>I stayed at home <b>because</b> it was raining.</i> (Neden evde kaldım? Yağmur yağıyordu.)</li><li><b>so</b> = bu yüzden, o yüzden. Arkasından <b>sonuç</b> gelir. Önüne genelde virgül konur: <i>I was hungry, <b>so</b> I ate a sandwich.</i></li></ul><p>Aynı olayı iki şekilde anlatabilirsin:</p><ul><li><i>It was raining, so we stayed at home.</i></li><li><i>We stayed at home because it was raining.</i></li></ul><h3>Zıtlık: although</h3><p><b>although</b> = -e rağmen, -dığı halde. Beklenmedik bir durumu anlatır. Cümlenin başında da ortasında da olabilir; başta ise iki parçanın arasına <b>virgül</b> konur.</p><ul><li><i>Although it was cold, we went to the beach.</i> (Hava soğuk olmasına rağmen plaja gittik.)</li><li><i>Ece passed the test although she didn't study much.</i> (Ece çok çalışmadığı halde testi geçti.)</li></ul><h3>Dikkat!</h3><ul><li>although ile but aynı cümlede kullanılmaz: <i>Although it was cold, but we went out.</i> yanlış → <i>Although it was cold, we went out.</i></li><li>because sebep, so sonuç gösterir; karıştırma: <i>I was hungry because I ate a sandwich.</i> yanlış → <i>I was hungry, so I ate a sandwich.</i></li><li>because ile so aynı cümlede birlikte kullanılmaz: <i>Because I was tired, so I slept.</i> yanlış → <i>I was tired, so I slept.</i></li></ul><h3>Kısaca</h3><p><b>because</b> sebebi, <b>so</b> sonucu, <b>although</b> beklenmedik durumu anlatır. although ile but, because ile so aynı cümlede birlikte kullanılmaz.</p>","ornekler":[{"en":"I stayed at home because it was raining.","tr":"Evde kaldım çünkü yağmur yağıyordu."},{"en":"I was hungry, so I ate a sandwich.","tr":"Acıkmıştım, bu yüzden bir sandviç yedim."},{"en":"Although it was cold, we went to the beach.","tr":"Hava soğuk olmasına rağmen plaja gittik."},{"en":"Can is tired, but he wants to play.","tr":"Can yorgun ama oynamak istiyor."},{"en":"Do you want juice or milk?","tr":"Meyve suyu mu yoksa süt mü istersin?"},{"en":"We missed the bus, so we walked to school.","tr":"Otobüsü kaçırdık, bu yüzden okula yürüdük."},{"en":"I went to bed early because I was tired.","tr":"Erken yattım çünkü yorgundum."},{"en":"Ece passed the test although she didn't study much.","tr":"Ece çok çalışmadığı halde testi geçti."},{"en":"Papi is happy because Ali gave him an apple.","tr":"Papi mutlu çünkü Ali ona bir elma verdi."},{"en":"I like cats and dogs.","tr":"Kedileri ve köpekleri severim."}],"test":[{"tip":"secim","soru":"Sebep bildiren bağlaç (çünkü) hangisi?","secenekler":["so","because","although"],"dogru":1,"aciklama":"because = çünkü; sebep bildirir. so sonuç, although zıtlık bildirir."},{"tip":"bosluk","soru":"I was hungry, ___ I ate a sandwich.","tr":"Acıkmıştım, bu yüzden bir sandviç yedim.","secenekler":["because","although","so"],"dogru":2,"aciklama":"Sandviç yemek acıkmanın sonucudur; sonuç için so kullanılır."},{"tip":"bosluk","soru":"I stayed at home ___ it was raining.","tr":"Evde kaldım çünkü yağmur yağıyordu.","secenekler":["because","so","although"],"dogru":0,"aciklama":"Yağmur, evde kalmanın sebebidir; sebep için because kullanılır."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["Although it was cold, but we went out.","Although it was cold, we went out.","Although it was cold, so we went out."],"dogru":1,"aciklama":"although ile but ya da so aynı cümlede kullanılmaz."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["It","was","raining","so","we","stayed","home"],"cevap":"It was raining, so we stayed home.","tr":"Yağmur yağıyordu, bu yüzden evde kaldık.","aciklama":"Önce sebep, sonra so ve sonuç gelir."},{"tip":"bosluk","soru":"Ece passed the test ___ she didn't study much.","tr":"Ece çok çalışmadığı halde testi geçti.","secenekler":["although","because","so"],"dogru":0,"aciklama":"Çalışmadan geçmek beklenmedik bir durumdur; although kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["The","shop","was","closed","so","Mom","went","home"],"cevap":"The shop was closed, so Mom went home.","tr":"Dükkân kapalıydı, bu yüzden annem eve gitti.","aciklama":"Önce sebep gelir; so arkasından sonuç gelir: Mom went home."},{"tip":"secim","soru":"\"Mert is sick. He can't come to school.\" Hangi cümle bunları doğru birleştirir?","secenekler":["Mert is sick because he can't come to school.","Mert is sick, but he can't come to school.","Mert can't come to school because he is sick."],"dogru":2,"aciklama":"Hastalık sebeptir; because arkasına sebep gelir: because he is sick."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Papi","was","hungry","so","he","ate","an","apple"],"cevap":"Papi was hungry, so he ate an apple.","tr":"Papi açtı, bu yüzden bir elma yedi.","aciklama":"so arkasından sonuç gelir: he ate an apple."},{"tip":"dogruyanlis","soru":"\"Because I was tired, so I went to bed.\" Bu cümle doğru mu?","dogru":false,"aciklama":"because ile so birlikte kullanılmaz: I was tired, so I went to bed."}],"kelimeSozlugu":{"because":{"tr":"çünkü","alt":"sebep bildirir"},"so":{"tr":"bu yüzden","alt":"sonuç bildirir"},"although":{"tr":"-e rağmen, -dığı halde","alt":"zıtlık bildirir"},"but":{"tr":"ama, fakat","alt":""},"and":{"tr":"ve","alt":""},"or":{"tr":"veya, ya da","alt":""}}}$dm$::jsonb where id = '2a96219d-5c4b-4269-be7c-06495faa00bc' and topic_name = 'Conjunctions (because, so, although, etc.) — Bağlaçlar (Because, So, Although vb.)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Gelecekte olabilecek bir şeyi ve onun sonucunu anlatmayı öğreneceksin: <i>Hava güneşli olursa parka gideceğiz.</i> Buna <b>birinci koşul cümlesi</b> (first conditional) denir.</p><h3>Formül</h3><p>Cümlenin iki parçası var: <b>koşul</b> (if kısmı) ve <b>sonuç</b> (will kısmı).</p><p><b>If + geniş zaman (present simple), will + fiil</b></p><table><tr><th>Koşul (if ...)</th><th>Sonuç (will ...)</th></tr><tr><td><i>If it is sunny,</i></td><td><i>we will go to the park.</i></td></tr><tr><td><i>If you study hard,</i></td><td><i>you will pass the test.</i></td></tr><tr><td><i>If Ece invites me,</i></td><td><i>I will go to her party.</i></td></tr></table><p>Türkçedeki <b>-rsa / -rse</b> ekinin karşılığı <b>if</b> kelimesidir: <i>If it rains</i> = yağmur yağarsa.</p><h3>If kısmında will yok!</h3><p>En önemli kural: <b>if</b> olan kısımda <b>will kullanılmaz</b>. Gelecekten bahsetsek bile orada geniş zaman kullanırız. He, she, it ile fiile <b>-s</b> eklemeyi unutma: <i>If it rains</i>, <i>If Ece invites me</i>.</p><ul><li><i>If it will rain, ...</i> yanlış</li><li><i>If it rains, we won't play football.</i> doğru</li></ul><h3>Olumsuz, soru ve sıra</h3><ul><li>Olumsuz koşul: <b>If + don't / doesn't</b>: <i>If we don't hurry, we will miss the bus.</i></li><li>Olumsuz sonuç: <b>won't</b> (= will not): <i>If it rains, we won't play football.</i></li><li>Soru: <i>What will you do if you win the match?</i> (Maçı kazanırsan ne yapacaksın?)</li><li>İki parçanın yeri değişebilir. If başta ise araya <b>virgül</b> koyarız; sonda ise virgül gerekmez: <i>I will buy a bike if I save enough money.</i></li></ul><h3>Dikkat!</h3><ul><li><i>If I will see Can, I will tell him.</i> yanlış → <i>If I see Can, I will tell him.</i></li><li>Sonuç kısmında will unutulmaz: <i>If it is sunny, we go to the park.</i> yerine → <i>we will go to the park.</i></li><li>Olumsuzda <i>don't will</i> denmez: <i>we don't will play</i> yanlış → <i>we won't play</i>.</li><li>Soruda sıra: <i>What you will do?</i> yanlış → <i>What will you do?</i></li></ul><h3>Kısaca</h3><p>Olası bir gelecek durumu için <b>If + geniş zaman, will + fiil</b> kullan. If kısmına asla will koyma.</p>","ornekler":[{"en":"If it is sunny, we will go to the park.","tr":"Hava güneşli olursa parka gideceğiz."},{"en":"If you study hard, you will pass the test.","tr":"Sıkı çalışırsan testi geçeceksin."},{"en":"If Ece invites me, I will go to her party.","tr":"Ece beni davet ederse partisine gideceğim."},{"en":"I will buy a new bike if I save enough money.","tr":"Yeterince para biriktirirsem yeni bir bisiklet alacağım."},{"en":"If we don't hurry, we will miss the bus.","tr":"Acele etmezsek otobüsü kaçıracağız."},{"en":"If you feed Papi, he will be happy.","tr":"Papi'yi beslersen mutlu olacak."},{"en":"If it rains, we won't play football.","tr":"Yağmur yağarsa futbol oynamayacağız."},{"en":"What will you do if you win the match?","tr":"Maçı kazanırsan ne yapacaksın?"},{"en":"If I finish my homework, I will watch a cartoon.","tr":"Ödevimi bitirirsem bir çizgi film izleyeceğim."},{"en":"Mom will be angry if you don't clean your room.","tr":"Odanı temizlemezsen annem kızacak."}],"test":[{"tip":"bosluk","soru":"If it ___ sunny, we will go to the park.","tr":"Hava güneşli olursa parka gideceğiz.","secenekler":["will be","is","be"],"dogru":1,"aciklama":"If kısmında will kullanılmaz, geniş zaman gelir: If it is sunny."},{"tip":"bosluk","soru":"If you study hard, you ___ the test.","tr":"Sıkı çalışırsan testi geçeceksin.","secenekler":["will pass","pass will","passed"],"dogru":0,"aciklama":"Sonuç kısmında will + fiil gelir: you will pass."},{"tip":"secim","soru":"\"Yağmur yağarsa futbol oynamayacağız.\" cümlesinin İngilizcesi hangisi?","secenekler":["If it will rain, we won't play football.","If it rains, we don't will play football.","If it rains, we won't play football."],"dogru":2,"aciklama":"If kısmında geniş zaman (rains), sonuçta won't + fiil kullanılır."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["If I will see Can, I will tell him.","If I see Can, I will tell him.","If I see Can, I tell will him."],"dogru":1,"aciklama":"If kısmında will olmaz: If I see Can, I will tell him."},{"tip":"siralama","soru":"\"..., I will go to her party.\" Cümlenin başını kur.","parcalar":["If","Ece","invites","me"],"cevap":"If Ece invites me","tr":"Ece beni davet ederse partisine gideceğim.","aciklama":"If kısmında geniş zaman kullanılır; Ece tekil olduğu için invites olur."},{"tip":"bosluk","soru":"Mom will be angry if you ___ your room.","tr":"Odanı temizlemezsen annem kızacak.","secenekler":["don't clean","won't clean","not clean"],"dogru":0,"aciklama":"If kısmının olumsuzu don't ile yapılır, won't kullanılmaz."},{"tip":"siralama","soru":"\"..., you will pass the test.\" Cümlenin başını kur.","parcalar":["If","you","study","hard"],"cevap":"If you study hard","tr":"Sıkı çalışırsan testi geçeceksin.","aciklama":"If kısmında will olmaz, geniş zaman gelir: If you study hard."},{"tip":"secim","soru":"\"Maçı kazanırsan ne yapacaksın?\" sorusunun İngilizcesi hangisi?","secenekler":["What you will do if you win the match?","What will you do if you will win the match?","What will you do if you win the match?"],"dogru":2,"aciklama":"Soruda will özneden önce gelir; if kısmında will olmaz."},{"tip":"siralama","soru":"\"..., we will miss the bus.\" Cümlenin başını kur.","parcalar":["If","we","don't","hurry"],"cevap":"If we don't hurry","tr":"Acele etmezsek otobüsü kaçıracağız.","aciklama":"Olumsuz koşul: If + don't + fiil."},{"tip":"dogruyanlis","soru":"\"If you feed Papi, he will be happy.\" Bu cümle doğru mu?","dogru":true,"aciklama":"Doğru! If kısmında geniş zaman (feed), sonuçta will + fiil var."}],"kelimeSozlugu":{"if":{"tr":"eğer, -rsa / -rse","alt":"if kısmında will olmaz"},"will":{"tr":"-ecek, -acak","alt":"sonuç kısmında"},"won't":{"tr":"-meyecek, -mayacak","alt":"will not"},"hurry":{"tr":"acele etmek","alt":""},"miss":{"tr":"kaçırmak","alt":"miss the bus"},"invites":{"tr":"davet eder","alt":"invite: davet etmek"}}}$dm$::jsonb where id = '175948d7-ebb3-4647-b977-121c1954d457' and topic_name = 'First conditional (if ... will) — Birinci Koşul Cümlesi (First Conditional)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Kimin, neyin ya da nerenin tam belli olmadığı durumlarda <b>somebody, anything, nowhere, everybody</b> gibi kelimeleri kullanmayı öğreneceksin. Bunlara <b>belgisiz zamirler</b> (indefinite pronouns) denir.</p><h3>Kelimeler nasıl kurulur?</h3><p>Dört başlangıç (<b>some, any, no, every</b>) ile üç son (<b>-body, -thing, -where</b>) birleşir. <b>-body</b> yerine <b>-one</b> da kullanılabilir: <i>somebody = someone</i>.</p><table><tr><th></th><th>kişi (-body)</th><th>şey (-thing)</th><th>yer (-where)</th></tr><tr><td><b>some-</b></td><td>somebody = biri</td><td>something = bir şey</td><td>somewhere = bir yer</td></tr><tr><td><b>any-</b></td><td>anybody = kimse, biri</td><td>anything = hiçbir şey, bir şey</td><td>anywhere = hiçbir yer, bir yer</td></tr><tr><td><b>no-</b></td><td>nobody = hiç kimse</td><td>nothing = hiçbir şey</td><td>nowhere = hiçbir yer</td></tr><tr><td><b>every-</b></td><td>everybody = herkes</td><td>everything = her şey</td><td>everywhere = her yer</td></tr></table><h3>Hangisini ne zaman kullanırız?</h3><ul><li><b>some-</b> olumlu cümlede: <i>There is somebody at the door.</i> (Kapıda biri var.) Bir şey teklif ederken de: <i>Do you want something to drink?</i></li><li><b>any-</b> olumsuz cümlede ve soruda: <i>I didn't eat anything.</i> (Hiçbir şey yemedim.) <i>Is there anybody in the classroom?</i> (Sınıfta kimse var mı?)</li><li><b>no-</b> olumlu fiille kullanılır, kendisi olumsuz anlam verir: <i>Nobody knows the answer.</i> (Kimse cevabı bilmiyor.) <i>There is nothing in the fridge.</i></li><li><b>every-</b> herkes, her şey, her yer: <i>Everybody loves Papi.</i></li></ul><h3>Tekil fiil kuralı</h3><p>Bu kelimelerin hepsi <b>tekil</b> sayılır. Fiil de tekil olur: <i>Everybody <b>is</b> here.</i> <i>Nobody <b>knows</b>.</i> <i>Everything <b>is</b> ready.</i></p><h3>Dikkat!</h3><ul><li>Türkçede “Kimseyi görmedim” deriz, iki olumsuz yan yana gelir. İngilizcede gelmez: <i>I didn't see nobody.</i> yanlış → <i>I didn't see anybody.</i> ya da <i>I saw nobody.</i></li><li>everybody tekildir: <i>Everybody are happy.</i> yanlış → <i>Everybody is happy.</i></li><li>Olumlu cümlede any- değil some-: <i>I have got anything in my bag.</i> yanlış → <i>I have got something in my bag.</i></li></ul><h3>Kısaca</h3><p>Olumlu cümlede <b>some-</b>, olumsuz ve soruda <b>any-</b>, olumlu fiille olumsuz anlam için <b>no-</b>, hepsi için <b>every-</b> kullan. Bu kelimelerden sonra fiil hep tekildir.</p>","ornekler":[{"en":"There is somebody at the door.","tr":"Kapıda biri var."},{"en":"I didn't eat anything for breakfast.","tr":"Kahvaltıda hiçbir şey yemedim."},{"en":"Is there anybody in the classroom?","tr":"Sınıfta kimse var mı?"},{"en":"Everybody loves Papi the parrot.","tr":"Herkes papağan Papi'yi çok sever."},{"en":"There is nothing in the fridge.","tr":"Buzdolabında hiçbir şey yok."},{"en":"I can't find my phone anywhere.","tr":"Telefonumu hiçbir yerde bulamıyorum."},{"en":"Let's go somewhere quiet.","tr":"Sessiz bir yere gidelim."},{"en":"Nobody knows the answer.","tr":"Kimse cevabı bilmiyor."},{"en":"Everything is ready for the party.","tr":"Parti için her şey hazır."},{"en":"Do you want something to drink?","tr":"İçecek bir şey ister misin?"}],"test":[{"tip":"secim","soru":"\"Kapıda biri var.\" cümlesinin İngilizcesi hangisi?","secenekler":["There is anybody at the door.","There is somebody at the door.","There is nobody at the door."],"dogru":1,"aciklama":"Olumlu cümlede some- kullanılır: somebody = biri."},{"tip":"bosluk","soru":"I didn't eat ___ for breakfast.","tr":"Kahvaltıda hiçbir şey yemedim.","secenekler":["nothing","something","anything"],"dogru":2,"aciklama":"Fiil zaten olumsuz (didn't), bu yüzden anything kullanılır."},{"tip":"bosluk","soru":"Is there ___ in the classroom?","tr":"Sınıfta kimse var mı?","secenekler":["anybody","anywhere","everybody"],"dogru":0,"aciklama":"Soruda kişi için anybody kullanılır."},{"tip":"secim","soru":"\"Herkes burada.\" cümlesinin İngilizcesi hangisi?","secenekler":["Everybody are here.","Everybody is here.","Every people is here."],"dogru":1,"aciklama":"everybody tekil sayılır, fiil de tekil olur: Everybody is here."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Nobody","knows","the","answer"],"cevap":"Nobody knows the answer.","tr":"Kimse cevabı bilmiyor.","aciklama":"nobody olumlu fiille kullanılır ve tekildir: Nobody knows."},{"tip":"bosluk","soru":"I can't find my phone ___.","tr":"Telefonumu hiçbir yerde bulamıyorum.","secenekler":["anywhere","nowhere","everywhere"],"dogru":0,"aciklama":"Fiil olumsuz (can't), bu yüzden anywhere kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","can't","find","my","keys","anywhere"],"cevap":"I can't find my keys anywhere.","tr":"Anahtarlarımı hiçbir yerde bulamıyorum.","aciklama":"Fiil olumsuz (can't), bu yüzden anywhere kullanılır ve cümlenin sonuna gelir."},{"tip":"secim","soru":"\"Hiç kimseyi görmedim.\" cümlesinin İngilizcesi hangisi?","secenekler":["I didn't see nobody.","I saw anybody.","I didn't see anybody."],"dogru":2,"aciklama":"İngilizcede iki olumsuz yan yana gelmez: didn't see anybody."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Everybody","wants","to","play","football"],"cevap":"Everybody wants to play football.","tr":"Herkes futbol oynamak istiyor.","aciklama":"everybody tekildir, fiil de tekil olur: wants."},{"tip":"dogruyanlis","soru":"\"I have got anything in my bag.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Olumlu cümlede some- kullanılır: I have got something in my bag."}],"kelimeSozlugu":{"somebody":{"tr":"biri","alt":"someone ile aynı"},"anything":{"tr":"hiçbir şey, bir şey","alt":"olumsuz cümle ve soruda"},"anybody":{"tr":"kimse, biri","alt":"olumsuz cümle ve soruda"},"nobody":{"tr":"hiç kimse","alt":"olumlu fiille kullanılır"},"nothing":{"tr":"hiçbir şey","alt":""},"everybody":{"tr":"herkes","alt":"fiil tekil olur"},"everything":{"tr":"her şey","alt":""},"somewhere":{"tr":"bir yer","alt":""},"anywhere":{"tr":"hiçbir yer, bir yer","alt":""}}}$dm$::jsonb where id = 'd72ecdb7-ccc5-401a-ab95-696570c22dfb' and topic_name = 'Indefinite pronouns (somebody, anything, etc.) — Belgisiz Zamirler';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>İki fiil yan yana geldiğinde ikinci fiilin nasıl yazılacağını öğreneceksin. Bazen <b>to + fiil</b> (to play), bazen <b>fiil + ing</b> (playing) kullanılır. Hangisinin geleceğine birinci fiil karar verir.</p><h3>Fiil + ing (gerund)</h3><p>Bazı fiillerden sonra ikinci fiil <b>-ing</b> takısı alır. Buna <b>gerund</b> denir. Türkçedeki <b>-mek / -mayı / -maktan</b> gibi düşünebilirsin.</p><p><b>enjoy / finish / don't mind + fiil-ing</b></p><table><tr><th>Fiil</th><th>Anlamı</th><th>Örnek</th></tr><tr><td><b>enjoy</b></td><td>-den hoşlanmak</td><td><i>I enjoy playing football.</i></td></tr><tr><td><b>finish</b></td><td>bitirmek</td><td><i>Have you finished cleaning your room?</i></td></tr><tr><td><b>don't mind</b></td><td>sakıncası olmamak</td><td><i>I don't mind waiting.</i></td></tr><tr><td><b>like / love</b></td><td>sevmek</td><td><i>Papi loves singing.</i></td></tr><tr><td><b>hate</b></td><td>nefret etmek</td><td><i>Mert hates getting up early.</i></td></tr></table><p>Yazarken dikkat: <i>swim → swimming</i>, <i>run → running</i> (son harf ikilenir), <i>ride → riding</i>, <i>dance → dancing</i> (sondaki e düşer).</p><h3>Fiil + to + fiil (infinitive)</h3><p>Bazı fiillerden sonra ise <b>to + fiilin yalın hali</b> gelir. Buna <b>infinitive</b> denir.</p><p><b>want / decide / hope / need / learn / would like + to + fiil</b></p><table><tr><th>Fiil</th><th>Anlamı</th><th>Örnek</th></tr><tr><td><b>want</b></td><td>istemek</td><td><i>Ece wants to learn the guitar.</i></td></tr><tr><td><b>decide</b></td><td>karar vermek</td><td><i>We decided to have a picnic.</i></td></tr><tr><td><b>hope</b></td><td>ummak</td><td><i>Zeynep hopes to win.</i></td></tr><tr><td><b>need</b></td><td>ihtiyacı olmak</td><td><i>I need to study.</i></td></tr><tr><td><b>would like</b></td><td>istemek (kibar)</td><td><i>Would you like to come?</i></td></tr></table><p>Not: <b>like, love</b> ve <b>hate</b> fiillerinden sonra iki yapı da olur: <i>I like swimming</i> ya da <i>I like to swim</i>. Ama <b>would like</b> her zaman <b>to</b> alır.</p><h3>Dikkat!</h3><ul><li>want sonrasında to unutulmaz: <i>I want go home.</i> yanlış → <i>I want to go home.</i></li><li>enjoy sonrasında to gelmez: <i>I enjoy to read.</i> yanlış → <i>I enjoy reading.</i></li><li>like sonrasında fiil yalın kalmaz: <i>I like swim.</i> yanlış → <i>I like swimming.</i></li><li>Yazım: <i>swiming</i> yanlış → <i>swimming</i>.</li></ul><h3>Kısaca</h3><p>enjoy, finish, don't mind gibi fiillerden sonra <b>-ing</b>; want, decide, hope, need, would like gibi fiillerden sonra <b>to + fiil</b> gelir. like, love ve hate ikisini de kabul eder.</p>","ornekler":[{"en":"I enjoy playing football with my friends.","tr":"Arkadaşlarımla futbol oynamaktan hoşlanırım."},{"en":"Ece wants to learn the guitar.","tr":"Ece gitar çalmayı öğrenmek istiyor."},{"en":"Do you like reading comics?","tr":"Çizgi roman okumayı sever misin?"},{"en":"Mert hates getting up early on Mondays.","tr":"Mert pazartesileri erken kalkmaktan nefret eder."},{"en":"We decided to have a picnic on Sunday.","tr":"Pazar günü piknik yapmaya karar verdik."},{"en":"I don't want to do my homework now.","tr":"Ödevimi şimdi yapmak istemiyorum."},{"en":"Papi loves singing in the morning.","tr":"Papi sabahları şarkı söylemeyi çok sever."},{"en":"Have you finished cleaning your room?","tr":"Odanı temizlemeyi bitirdin mi?"},{"en":"Zeynep hopes to win the chess game.","tr":"Zeynep satranç oyununu kazanmayı umuyor."},{"en":"Would you like to come to my birthday party?","tr":"Doğum günü partime gelmek ister misin?"}],"test":[{"tip":"secim","soru":"Hangi fiilden sonra ikinci fiil -ing alır?","secenekler":["want","enjoy","decide"],"dogru":1,"aciklama":"enjoy fiilinden sonra -ing gelir: I enjoy playing. want ve decide ise to alır."},{"tip":"bosluk","soru":"Ece wants ___ the guitar.","tr":"Ece gitar çalmayı öğrenmek istiyor.","secenekler":["to learn","learning","learn"],"dogru":0,"aciklama":"want fiilinden sonra to + fiil gelir: wants to learn."},{"tip":"bosluk","soru":"Mert enjoys ___ football.","tr":"Mert futbol oynamaktan hoşlanır.","secenekler":["to play","play","playing"],"dogru":2,"aciklama":"enjoy fiilinden sonra -ing gelir: enjoys playing."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["I hope seeing you soon.","I hope to see you soon.","I hope see you soon."],"dogru":1,"aciklama":"hope fiilinden sonra to + fiil gelir: I hope to see you soon."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We","decided","to","have","a","picnic"],"cevap":"We decided to have a picnic.","tr":"Piknik yapmaya karar verdik.","aciklama":"decide fiilinden sonra to + fiil gelir: decided to have."},{"tip":"bosluk","soru":"Have you finished ___ your room?","tr":"Odanı temizlemeyi bitirdin mi?","secenekler":["cleaning","to clean","clean"],"dogru":0,"aciklama":"finish fiilinden sonra -ing gelir: finished cleaning."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","don't","like","getting","up","early"],"cevap":"I don't like getting up early.","tr":"Erken kalkmayı sevmem.","aciklama":"like fiilinden sonra -ing kullanabiliriz: like getting up."},{"tip":"secim","soru":"\"Yüzmeyi severim.\" cümlesinin İngilizcesi hangisi?","secenekler":["I like swim.","I like swiming.","I like swimming."],"dogru":2,"aciklama":"like + fiil-ing: swim kelimesinde m ikilenir, swimming olur."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Do","you","enjoy","reading","comics"],"cevap":"Do you enjoy reading comics?","tr":"Çizgi roman okumaktan hoşlanır mısın?","aciklama":"Soru Do you ile başlar; enjoy fiilinden sonra reading gelir."},{"tip":"dogruyanlis","soru":"\"I want going to the cinema.\" Bu cümle doğru mu?","dogru":false,"aciklama":"want fiilinden sonra to + fiil gelir: I want to go to the cinema."}],"kelimeSozlugu":{"enjoy":{"tr":"-den hoşlanmak","alt":"sonra fiil-ing gelir"},"finish":{"tr":"bitirmek","alt":"sonra fiil-ing gelir"},"hate":{"tr":"nefret etmek","alt":""},"want":{"tr":"istemek","alt":"sonra to + fiil gelir"},"decide":{"tr":"karar vermek","alt":"sonra to + fiil gelir"},"hope":{"tr":"ummak","alt":"sonra to + fiil gelir"},"would like":{"tr":"istemek (kibar)","alt":"Would you like to ...?"}}}$dm$::jsonb where id = 'f9432917-1e41-4641-815f-3aa1241d86df' and topic_name = 'Infinitive and gerund (basic) — İsim-Fiil Yapıları (Infinitive ve Gerund)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Kibarca <b>izin istemeyi</b> (Can I ...? May I ...?), kuralları ve yasakları anlatmayı (must, mustn't, be allowed to) ve birine <b>tavsiye vermeyi</b> (should) öğreneceksin. Okulda, evde ve arkadaşlarınla her gün bu kalıpları kullanırsın.</p><h3>İzin istemek: Can I, Could I, May I</h3><table><tr><th>Kalıp</th><th>Ne zaman?</th><th>Örnek</th></tr><tr><td><b>Can I ...?</b></td><td>Arkadaşlarla, ailede (günlük)</td><td><i>Can I watch TV now?</i></td></tr><tr><td><b>Could I ...?</b></td><td>Daha kibar</td><td><i>Could I use your pencil?</i></td></tr><tr><td><b>May I ...?</b></td><td>En kibar; öğretmene, büyüklere</td><td><i>May I come in, please?</i></td></tr></table><p>Cevap verirken: <i>Yes, of course.</i> / <i>Sure, here you are.</i> (Tabii, buyur.) / <i>Sorry, you can't.</i> Dikkat: Could I ...? sorusuna <i>Yes, you can.</i> diye cevap verilir, “Yes, you could” denmez.</p><h3>İzin var mı, yok mu? be allowed to</h3><p><b>be allowed to + fiil</b> = -mesine izin verilmek.</p><ul><li><i>Are we allowed to use calculators?</i> = Hesap makinesi kullanmamıza izin var mı?</li><li><i>We aren't allowed to eat in the classroom.</i> = Sınıfta yemek yememize izin yok.</li></ul><h3>Kurallar ve zorunluluk: must, mustn't, needn't</h3><ul><li><b>must / have to</b> = zorunda: <i>Students must listen to the teacher.</i></li><li><b>mustn't</b> = yasak: <i>You mustn't run in the corridors.</i> = Koridorlarda koşmak yasak.</li><li><b>needn't / don't have to</b> = gerek yok: <i>You needn't bring your lunch.</i> = Öğle yemeğini getirmene gerek yok.</li></ul><h3>Tavsiye: should / shouldn't</h3><p>Birine iyi bir fikir önerirken <b>should</b>, iyi olmayan bir şey için <b>shouldn't</b> kullanırız. Tavsiye istemek için: <b>Should I ...?</b> ya da <b>What should I ...?</b></p><ul><li><i>You look tired. You should go to bed early.</i></li><li><i>What should I give Ayşe for her birthday?</i></li></ul><h3>Dikkat!</h3><ul><li>Modaldan sonra to gelmez: <i>May I to go out?</i> → <i>May I go out?</i></li><li>allow değil allowed: <i>Are we allow to play?</i> → <i>Are we allowed to play?</i></li><li>needn't'ten sonra to gelmez: <i>You needn't to come.</i> → <i>You needn't come.</i></li><li>mustn't (yasak) ile needn't (gerek yok) farklıdır: <i>You mustn't bring a pen.</i> = Kalem getirmek yasak. <i>You needn't bring a pen.</i> = Kalem getirmene gerek yok.</li></ul><h3>Kısaca</h3><p>İzin isterken Can I, Could I ya da en kibar haliyle <b>May I</b> kullan; izin olup olmadığını <b>be allowed to</b> ile sor. Yasak için <b>mustn't</b>, gerek yok için <b>needn't</b>, tavsiye için <b>should</b> kullan.</p>","ornekler":[{"en":"May I come in, please?","tr":"Girebilir miyim lütfen?"},{"en":"Could I use your pencil? Sure, here you are.","tr":"Kalemini kullanabilir miyim? Tabii, buyur."},{"en":"Can I watch TV now? No, you can't.","tr":"Şimdi televizyon izleyebilir miyim? Hayır, izleyemezsin."},{"en":"You mustn't run in the corridors.","tr":"Koridorlarda koşmak yasak."},{"en":"Students must listen to the teacher.","tr":"Öğrenciler öğretmeni dinlemek zorunda."},{"en":"Are we allowed to use calculators in the test?","tr":"Sınavda hesap makinesi kullanmamıza izin var mı?"},{"en":"We aren't allowed to eat in the classroom.","tr":"Sınıfta yemek yememize izin yok."},{"en":"You needn't bring your lunch. There's a picnic.","tr":"Öğle yemeğini getirmene gerek yok. Piknik var."},{"en":"You look tired. You should go to bed early.","tr":"Yorgun görünüyorsun. Erken yatmalısın."},{"en":"What should I give Ayşe for her birthday?","tr":"Ayşe'ye doğum gününde ne hediye etmeliyim?"}],"test":[{"tip":"secim","soru":"Öğretmeninden sınıfa girmek için kibarca izin iste.","secenekler":["May I come in, please?","I come in, please?","May I to come in, please?"],"dogru":0,"aciklama":"En kibar izin: May I + yalın fiil. May'den sonra to gelmez."},{"tip":"bosluk","soru":"You ___ run in the corridors. It's dangerous.","tr":"Koridorlarda koşmamalısın. Tehlikeli.","secenekler":["needn't","mustn't","don't have to"],"dogru":1,"aciklama":"Yasak için mustn't kullanılır. Needn't ve don't have to gerek yok demektir."},{"tip":"secim","soru":"Arkadaşın \"Can I borrow your ruler?\" dedi. Kabul etmek için ne dersin?","secenekler":["Yes, I can.","Yes, you must.","Sure, here you are."],"dogru":2,"aciklama":"İzin verip eşyayı uzatırken Sure, here you are. denir."},{"tip":"bosluk","soru":"Are we ___ to use our phones?","tr":"Telefonlarımızı kullanmamıza izin var mı?","secenekler":["allow","allowed","allowing"],"dogru":1,"aciklama":"Kalıp: be allowed to + fiil. Are we allowed to ...?"},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Where","can","I","put","my","bag"],"cevap":"Where can I put my bag?","tr":"Çantamı nereye koyabilirim?","aciklama":"İzin sorusu: soru kelimesi + can + I + yalın fiil?"},{"tip":"secim","soru":"Hangisi \"Kalem getirmene gerek yok.\" demektir?","secenekler":["You mustn't bring a pen.","You shouldn't bring a pen.","You needn't bring a pen."],"dogru":2,"aciklama":"Needn't = gerek yok. Mustn't yasak, shouldn't ise yapmasan iyi olur demektir."},{"tip":"bosluk","soru":"You have a toothache. You ___ see a dentist.","tr":"Dişin ağrıyor. Dişçiye gitmelisin.","secenekler":["should","shouldn't","needn't"],"dogru":0,"aciklama":"İyi bir öneri için should kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We're","not","allowed","to","eat","sweets"],"cevap":"We're not allowed to eat sweets.","tr":"Şekerleme yememize izin yok.","aciklama":"Olumsuz: We're (We are) not allowed to + yalın fiil."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","should","I","wear","to","the","party"],"cevap":"What should I wear to the party?","tr":"Partiye ne giymeliyim?","aciklama":"Tavsiye istemek: What should I + yalın fiil ...?"},{"tip":"dogruyanlis","soru":"\"May I ...?\" ile izin istemek, \"Can I ...?\" ile istemekten daha kibardır.","dogru":true,"aciklama":"Doğru! May I en kibar kalıptır; öğretmenlere ve büyüklere uygundur."}],"kelimeSozlugu":{"may":{"tr":"-ebilir miyim (izin)","alt":"en kibar"},"could":{"tr":"-ebilir miyim","alt":"kibar izin"},"allowed":{"tr":"izinli","alt":"be allowed to = izin verilmek"},"mustn't":{"tr":"yasak","alt":"must not"},"needn't":{"tr":"gerek yok","alt":"need not"},"should":{"tr":"-meli","alt":"tavsiye"},"sure":{"tr":"tabii","alt":"Sure, here you are. = Tabii, buyur."}}}$dm$::jsonb where id = '6dd0866d-2739-4bca-b2a5-bdd9d47ba114' and topic_name = 'Modals for advice, obligation and permission — Tavsiye, Zorunluluk ve İzin Kipleri';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Ne yapabildiğini (<b>can, could</b>), ne yapmak zorunda olduğunu (<b>must, have to</b>) ve birine ne yapması gerektiğini (<b>should</b>) söylemeyi öğreneceksin. Bu küçük kelimelere <b>modal</b> (kip) denir.</p><h3>Altın kural</h3><p>Modal + <b>fiilin yalın hali</b>. Modallar -s almaz ve kendilerinden sonra to gelmez.</p><ul><li><i>She can swim.</i> (She cans swim değil.)</li><li><i>You must listen.</i> (You must to listen değil.)</li><li>Tek istisna <b>have to</b>: içinde zaten to var ve he / she / it ile <b>has to</b> olur.</li></ul><h3>Hangisi ne demek?</h3><table><tr><th>Modal</th><th>Anlamı</th><th>Örnek</th></tr><tr><td><b>can</b></td><td>-ebilmek (yetenek, izin)</td><td><i>I can ride a bike.</i> = Bisiklet sürebilirim.</td></tr><tr><td><b>could</b></td><td>geçmişte -ebiliyordu; kibar rica</td><td><i>Ece could read when she was five.</i> <i>Could you help me?</i></td></tr><tr><td><b>must</b></td><td>-meli, zorunda (kural, kendi kararın)</td><td><i>We must wear our uniforms.</i></td></tr><tr><td><b>have to / has to</b></td><td>zorunda olmak (başkası ya da durum zorunlu kılıyor)</td><td><i>Deniz has to feed the cat.</i></td></tr><tr><td><b>should</b></td><td>-meli (tavsiye, öneri)</td><td><i>You should drink more water.</i></td></tr></table><h3>Olumsuz ve soru</h3><table><tr><th>Olumsuz</th><th>Anlamı</th></tr><tr><td><b>can't</b></td><td>-emez, yapamaz</td></tr><tr><td><b>couldn't</b></td><td>geçmişte yapamıyordu</td></tr><tr><td><b>mustn't</b></td><td>yasak, yapmamalısın</td></tr><tr><td><b>don't / doesn't have to</b></td><td>zorunda değil, gerek yok</td></tr><tr><td><b>shouldn't</b></td><td>yapmasan iyi olur</td></tr></table><p>Sorularda modal başa gelir: <i>Can you swim?</i> <i>Should I call Ali?</i> have to ise do / does ile soru yapar: <i>Do you have to wear glasses?</i></p><h3>Dikkat!</h3><ul><li>Modala -s eklenmez: <i>He cans play chess.</i> → <i>He can play chess.</i></li><li>Modaldan sonra to gelmez: <i>You should to sleep.</i> → <i>You should sleep.</i></li><li>he / she / it ile has to: <i>Ali have to study.</i> → <i>Ali has to study.</i></li><li><b>mustn't</b> ile <b>don't have to</b> aynı değil: <i>You mustn't come.</i> = Gelmen yasak. <i>You don't have to come.</i> = Gelmen gerekmiyor.</li></ul><h3>Kısaca</h3><p>Yetenek için can / could, zorunluluk için must / have to, tavsiye için should kullan ve hepsinden sonra fiili yalın bırak. mustn't “yasak”, don't have to ise “gerek yok” demektir.</p>","ornekler":[{"en":"I can ride a bike, but I can't swim.","tr":"Bisiklet sürebilirim ama yüzemem."},{"en":"Papi can say twenty words!","tr":"Papi yirmi kelime söyleyebiliyor!"},{"en":"Ece could read when she was five.","tr":"Ece beş yaşındayken okuyabiliyordu."},{"en":"Could you pass me the salt, please?","tr":"Tuzu uzatabilir misin lütfen?"},{"en":"We must wear our uniforms at school.","tr":"Okulda üniformamızı giymek zorundayız."},{"en":"Deniz has to feed the cat every morning.","tr":"Deniz her sabah kediyi beslemek zorunda."},{"en":"You don't have to come early tomorrow.","tr":"Yarın erken gelmek zorunda değilsin."},{"en":"You should drink more water.","tr":"Daha fazla su içmelisin."},{"en":"You shouldn't eat too many sweets.","tr":"Çok fazla şekerleme yememelisin."},{"en":"Do you have to wear glasses?","tr":"Gözlük takmak zorunda mısın?"}],"test":[{"tip":"bosluk","soru":"My little brother ___ count to ten.","tr":"Küçük erkek kardeşim ona kadar sayabilir.","secenekler":["cans","can","can to"],"dogru":1,"aciklama":"Can -s almaz ve ardından to gelmez: He can count."},{"tip":"secim","soru":"Arkadaşın hasta. Ona doktora gitmesini tavsiye et.","secenekler":["You should see a doctor.","You must to see a doctor.","You should to see a doctor."],"dogru":0,"aciklama":"Tavsiye için should + yalın fiil: You should see a doctor."},{"tip":"bosluk","soru":"Ali ___ to do his homework now.","tr":"Ali şimdi ödevini yapmak zorunda.","secenekler":["have","must","has"],"dogru":2,"aciklama":"He / she / it ile has to kullanılır: Ali has to ..."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Why","shouldn't","I","stay","up","late"],"cevap":"Why shouldn't I stay up late?","tr":"Neden geç saate kadar oturmamalıyım?","aciklama":"Soru: Why + shouldn't + kişi + yalın fiil?"},{"tip":"secim","soru":"\"Beş yaşındayken yüzebiliyordum.\" cümlesinin İngilizcesi hangisi?","secenekler":["I can swim when I was five.","I could swim when I was five.","I must swim when I was five."],"dogru":1,"aciklama":"Geçmişteki yetenek için could kullanılır."},{"tip":"secim","soru":"\"You don't have to wear a coat.\" ne demek?","secenekler":["Mont giymemelisin.","Mont giymek yasak.","Mont giymek zorunda değilsin."],"dogru":2,"aciklama":"Don't have to = gerek yok, zorunda değilsin. Yasak anlamı mustn't'tur."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Could","you","pass","me","the","salt"],"cevap":"Could you pass me the salt?","tr":"Tuzu uzatabilir misin?","aciklama":"Kibar rica: Could you + yalın fiil ...?"},{"tip":"bosluk","soru":"We ___ talk in the library. It's a rule.","tr":"Kütüphanede konuşmamalıyız. Bu bir kural.","secenekler":["mustn't","don't have to","can"],"dogru":0,"aciklama":"Kural ve yasak için mustn't kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Does","Elif","have","to","wear","glasses"],"cevap":"Does Elif have to wear glasses?","tr":"Elif gözlük takmak zorunda mı?","aciklama":"Have to sorusu does ile kurulur: Does + kişi + have to ...?"},{"tip":"dogruyanlis","soru":"\"You mustn't come.\" ile \"You don't have to come.\" aynı anlama gelir.","dogru":false,"aciklama":"Yanlış. Mustn't = yasak; don't have to = gerek yok."}],"kelimeSozlugu":{"can":{"tr":"-ebilmek","alt":"yetenek, izin"},"could":{"tr":"-ebiliyordu; -ebilir misin","alt":"geçmiş yetenek, kibar rica"},"must":{"tr":"-meli, zorunda","alt":"kural"},"have to":{"tr":"zorunda olmak","alt":"he / she / it ile has to"},"should":{"tr":"-meli","alt":"tavsiye"},"mustn't":{"tr":"yasak","alt":"must not"},"don't have to":{"tr":"gerek yok","alt":""}}}$dm$::jsonb where id = 'ce3349d4-a325-4784-a95d-7ec65c802d8c' and topic_name = 'Modals: can, could, must, have to, should — Yetenek, Zorunluluk ve Tavsiye Kipleri';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Geçmişte belli bir anda <b>devam etmekte olan</b> şeyleri anlatmayı öğreneceksin. Türkçedeki <b>-yordu</b> ekinin karşılığıdır: uyuyordum, oynuyorduk. Ayrıca <b>when</b> ve <b>while</b> ile iki olayı birlikte anlatabileceksin.</p><h3>Nasıl kurulur? was / were + fiil-ing</h3><table><tr><th>Kişi</th><th>Olumlu</th><th>Olumsuz</th><th>Soru</th></tr><tr><td>I / he / she / it</td><td>I <b>was</b> playing</td><td>I <b>wasn't</b> playing</td><td><b>Was</b> he playing?</td></tr><tr><td>you / we / they</td><td>we <b>were</b> playing</td><td>we <b>weren't</b> playing</td><td><b>Were</b> you playing?</td></tr></table><p>Kısa cevaplar: <i>Yes, I was. / No, I wasn't.</i> <i>Yes, they were. / No, they weren't.</i></p><p>-ing eklerken: <i>read → reading</i>, <i>write → writing</i> (sondaki e düşer), <i>swim → swimming</i>, <i>run → running</i> (son harf ikilenir).</p><h3>Ne zaman kullanırız?</h3><ul><li>Geçmişte belli bir saatte ne yaptığını anlatırken: <i>At seven o'clock, we were having dinner.</i> = Saat yedide akşam yemeği yiyorduk.</li><li>Bir olayın arka planını anlatırken: <i>It was raining and the birds were singing.</i> = Yağmur yağıyordu ve kuşlar ötüyordu.</li><li>Sorularda: <i>What were you doing at nine last night?</i> = Dün gece saat dokuzda ne yapıyordun?</li></ul><h3>when ve while: uzun olay ve kısa olay</h3><p>Uzun süren olay <b>past continuous</b>, onu bölen kısa olay <b>past simple</b> olur.</p><ul><li><b>when</b> + kısa olay: <i>I was sleeping when you called.</i> = Sen aradığında uyuyordum.</li><li><b>while</b> + uzun olay: <i>While I was walking home, I saw Deniz.</i> = Eve yürürken Deniz'i gördüm.</li></ul><p>Aramak bir anlık bir olaydır, uyumak ise uzun sürer. Bu yüzden <i>you called</i> past simple, <i>I was sleeping</i> past continuous olur.</p><h3>Dikkat!</h3><ul><li>-ing'i unutma: <i>I was play.</i> → <i>I was playing.</i></li><li>Çoğul öznelerle were: <i>They was watching TV.</i> → <i>They were watching TV.</i></li><li>I ile was: <i>I were reading.</i> → <i>I was reading.</i></li><li>Kısa olay past simple olur: <i>When I was eating, the phone was ringing.</i> → <i>When I was eating, the phone rang.</i></li></ul><h3>Kısaca</h3><p>Geçmişte devam eden olaylar için <b>was / were + fiil-ing</b> kullan. Uzun olayı bölen kısa olay için past simple kullanılır: <i>I was reading when Papi started to sing.</i></p>","ornekler":[{"en":"I was sleeping when you called.","tr":"Sen aradığında uyuyordum."},{"en":"At seven o'clock, we were having dinner.","tr":"Saat yedide akşam yemeği yiyorduk."},{"en":"Ece was reading a book in her room.","tr":"Ece odasında kitap okuyordu."},{"en":"The boys were playing football in the park.","tr":"Çocuklar parkta futbol oynuyordu."},{"en":"It was raining when we left school.","tr":"Okuldan çıktığımızda yağmur yağıyordu."},{"en":"Mert wasn't listening to the teacher.","tr":"Mert öğretmeni dinlemiyordu."},{"en":"We weren't watching TV, we were doing homework.","tr":"Televizyon izlemiyorduk, ödev yapıyorduk."},{"en":"What were you doing at nine last night?","tr":"Dün gece saat dokuzda ne yapıyordun?"},{"en":"Was Papi singing in his cage? Yes, he was.","tr":"Papi kafesinde şarkı mı söylüyordu? Evet, söylüyordu."},{"en":"While I was walking home, I saw Deniz.","tr":"Eve yürürken Deniz'i gördüm."}],"test":[{"tip":"bosluk","soru":"They ___ playing in the garden.","tr":"Bahçede oynuyorlardı.","secenekler":["was","were","are"],"dogru":1,"aciklama":"They ile geçmişte were kullanılır: They were playing."},{"tip":"bosluk","soru":"I was ___ a sandwich at noon.","tr":"Öğlen bir sandviç yiyordum.","secenekler":["eat","ate","eating"],"dogru":2,"aciklama":"Was / were'den sonra fiil -ing alır: was eating."},{"tip":"secim","soru":"\"Ali ödevini yapıyordu.\" cümlesinin İngilizcesi hangisi?","secenekler":["Ali was doing his homework.","Ali was do his homework.","Ali were doing his homework."],"dogru":0,"aciklama":"Ali = he; he ile was + fiil-ing gelir: was doing."},{"tip":"secim","soru":"\"swim\" fiiline -ing eklenince nasıl yazılır?","secenekler":["swiming","swimming","swimmming"],"dogru":1,"aciklama":"Swim kısa bir fiildir, son harf ikilenir: swimming."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Why","weren't","you","listening"],"cevap":"Why weren't you listening?","tr":"Neden dinlemiyordun?","aciklama":"Olumsuz soru: soru kelimesi + weren't + kişi + fiil-ing."},{"tip":"bosluk","soru":"I was walking to school when it ___ to rain.","tr":"Okula yürürken yağmur yağmaya başladı.","secenekler":["started","was starting","starts"],"dogru":0,"aciklama":"Uzun olayı bölen kısa olay past simple olur: it started."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","was","Can","doing","in","the","kitchen"],"cevap":"What was Can doing in the kitchen?","tr":"Can mutfakta ne yapıyordu?","aciklama":"Soru kelimesi + was + kişi + fiil-ing."},{"tip":"secim","soru":"\"Were you sleeping at ten?\" sorusuna doğru olumsuz cevap hangisi?","secenekler":["No, I weren't.","No, I didn't.","No, I wasn't."],"dogru":2,"aciklama":"Cevapta I ile was kullanılır: No, I wasn't."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Who","was","she","talking","to"],"cevap":"Who was she talking to?","tr":"O kiminle konuşuyordu?","aciklama":"Soru: soru kelimesi + was + kişi + fiil-ing; to sonda kalır."},{"tip":"dogruyanlis","soru":"\"When the teacher came in, we were talking.\" Bu cümle doğru mu?","dogru":true,"aciklama":"Doğru! Uzun olay (were talking) past continuous, kısa olay (came) past simple."}],"kelimeSozlugu":{"was":{"tr":"idi","alt":"I / he / she / it ile"},"were":{"tr":"idi","alt":"you / we / they ile"},"wasn't":{"tr":"değildi","alt":"was not"},"weren't":{"tr":"değildi","alt":"were not"},"when":{"tr":"-dığında, -dığı zaman","alt":""},"while":{"tr":"-ken, -dığı sırada","alt":""}}}$dm$::jsonb where id = '0f75432f-87d5-4db4-84c9-38b2b40c85fa' and topic_name = 'Past continuous — Sürekli Geçmiş Zaman';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Dün, geçen hafta ya da geçen yaz yaptığın şeyleri İngilizce anlatmayı öğreneceksin. Bunun için fiillerin <b>geçmiş halini (past simple)</b> kullanacağız: düzenli fiiller <b>-ed</b> alır, düzensiz fiiller ise tamamen değişir.</p><h3>Ne zaman kullanırız?</h3><p>Geçmişte olmuş ve <b>bitmiş</b> olaylar için. Türkçedeki <b>-dı, -di</b> ekinin karşılığıdır. Genellikle şu zaman ifadeleriyle gelir: <b>yesterday</b> (dün), <b>last week</b> (geçen hafta), <b>last summer</b> (geçen yaz), <b>two days ago</b> (iki gün önce), <b>in 2020</b> (2020'de).</p><p>Güzel bir haber: geçmiş zamanda fiil <b>bütün kişilerde aynıdır</b>. I played, she played, they played. Geniş zamandaki gibi -s eklemek yok!</p><h3>Düzenli fiiller: -ed ekle</h3><table><tr><th>Kural</th><th>Örnek</th></tr><tr><td>Çoğu fiile <b>-ed</b></td><td>play → played, watch → watched</td></tr><tr><td><b>-e</b> ile bitiyorsa sadece <b>-d</b></td><td>like → liked, dance → danced</td></tr><tr><td>Sessiz harf + <b>y</b> ise <b>-ied</b></td><td>study → studied, cry → cried</td></tr><tr><td>Kısa fiil, sesli + sessiz ile bitiyorsa son harf ikilenir</td><td>stop → stopped, plan → planned</td></tr></table><p>Okunuşa dikkat: <i>played</i> “pleyd”, <i>watched</i> “uoçt” diye okunur. Fiil t ya da d ile bitiyorsa -ed ayrı hece olur: <i>wanted</i> “uantıd”.</p><h3>Düzensiz fiiller: ezberle</h3><table><tr><th>Fiil</th><th>Geçmiş hali</th><th>Türkçe</th></tr><tr><td>go</td><td><b>went</b></td><td>gitti</td></tr><tr><td>eat</td><td><b>ate</b></td><td>yedi</td></tr><tr><td>see</td><td><b>saw</b></td><td>gördü</td></tr><tr><td>buy</td><td><b>bought</b></td><td>satın aldı</td></tr><tr><td>make</td><td><b>made</b></td><td>yaptı</td></tr><tr><td>have</td><td><b>had</b></td><td>sahipti, yedi</td></tr><tr><td>come</td><td><b>came</b></td><td>geldi</td></tr><tr><td>write</td><td><b>wrote</b></td><td>yazdı</td></tr></table><h3>Olumsuz ve soru: did yardım eder</h3><ul><li>Olumsuz: <b>didn't + fiilin yalın hali</b>. <i>I didn't finish my homework.</i></li><li>Soru: <b>Did + kişi + fiilin yalın hali</b>? <i>Did you buy a present?</i> — <i>Yes, I did. / No, I didn't.</i></li><li>Soru kelimesiyle: <i>What did you do at the weekend?</i></li></ul><p><b>did</b> zaten geçmişi gösterdiği için fiil bir daha geçmiş hale girmez.</p><h3>Dikkat!</h3><ul><li><i>I didn't went to school.</i> → <i>I didn't go to school.</i></li><li><i>Did you saw the film?</i> → <i>Did you see the film?</i></li><li>Düzensiz fiile -ed eklenmez: <i>goed</i> → <i>went</i>, <i>eated</i> → <i>ate</i></li><li>Geçmişi anlatırken fiili değiştirmeyi unutma: <i>I go to the park yesterday.</i> → <i>I went to the park yesterday.</i></li></ul><h3>Kısaca</h3><p>Geçmişte bitmiş olaylar için düzenli fiillere <b>-ed</b> ekle, düzensiz fiillerin geçmiş halini ezberle. Olumsuz ve soru cümlelerinde <b>didn't</b> ya da <b>Did</b> kullan ve fiili yalın bırak.</p>","ornekler":[{"en":"I played football with Can yesterday.","tr":"Dün Can'la futbol oynadım."},{"en":"We watched a funny cartoon last night.","tr":"Dün akşam komik bir çizgi film izledik."},{"en":"Elif studied for her English test.","tr":"Elif İngilizce sınavı için ders çalıştı."},{"en":"My family went to Antalya last summer.","tr":"Ailem geçen yaz Antalya'ya gitti."},{"en":"Deniz ate three slices of pizza.","tr":"Deniz üç dilim pizza yedi."},{"en":"Papi saw a big cat in the garden.","tr":"Papi bahçede büyük bir kedi gördü."},{"en":"I didn't finish my homework.","tr":"Ödevimi bitirmedim."},{"en":"Ayşe didn't go to school on Monday.","tr":"Ayşe pazartesi okula gitmedi."},{"en":"Did you buy a present for Mert? Yes, I did.","tr":"Mert'e hediye aldın mı? Evet, aldım."},{"en":"What did you do at the weekend?","tr":"Hafta sonu ne yaptın?"}],"test":[{"tip":"secim","soru":"\"go\" fiilinin geçmiş hali hangisi?","secenekler":["goed","went","gone"],"dogru":1,"aciklama":"Go düzensiz bir fiildir, geçmiş hali went olur."},{"tip":"bosluk","soru":"Yesterday I ___ my grandma.","tr":"Dün büyükannemi ziyaret ettim.","secenekler":["visit","visits","visited"],"dogru":2,"aciklama":"Yesterday geçmişi gösterir. Visit düzenlidir: visited."},{"tip":"secim","soru":"\"study\" fiilinin geçmiş hali hangisi?","secenekler":["studied","studyed","studed"],"dogru":0,"aciklama":"Sessiz harf + y ile biten fiillerde y düşer, -ied gelir: studied."},{"tip":"bosluk","soru":"We ___ a cake for Mom's birthday.","tr":"Annemin doğum günü için pasta yaptık.","secenekler":["made","maked","make"],"dogru":0,"aciklama":"Make düzensizdir; geçmiş hali made olur."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Elif","didn't","watch","the","film"],"cevap":"Elif didn't watch the film.","tr":"Elif filmi izlemedi.","aciklama":"Olumsuz: kişi + didn't + fiilin yalın hali."},{"tip":"secim","soru":"Hangi olumsuz cümle doğru?","secenekler":["I didn't went to the park.","I didn't go to the park.","I not went to the park."],"dogru":1,"aciklama":"Didn't'ten sonra fiil yalın gelir: didn't go."},{"tip":"bosluk","soru":"Did you ___ the new Papi video?","tr":"Papi'nin yeni videosunu gördün mü?","secenekler":["saw","seen","see"],"dogru":2,"aciklama":"Did ile kurulan soruda fiil yalın kalır: Did you see ...?"},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Did","you","eat","breakfast"],"cevap":"Did you eat breakfast?","tr":"Kahvaltı yaptın mı?","aciklama":"Soru: Did + kişi + yalın fiil."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","did","Can","buy","for","her"],"cevap":"What did Can buy for her?","tr":"Can ona ne aldı?","aciklama":"Soru kelimesi + did + kişi + yalın fiil."},{"tip":"dogruyanlis","soru":"\"She goed to school by bus.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Go düzensizdir, -ed almaz: She went to school by bus."}],"kelimeSozlugu":{"yesterday":{"tr":"dün","alt":""},"last":{"tr":"geçen","alt":"last week = geçen hafta"},"ago":{"tr":"önce","alt":"two days ago = iki gün önce"},"went":{"tr":"gitti","alt":"go fiilinin geçmiş hali"},"ate":{"tr":"yedi","alt":"eat fiilinin geçmiş hali"},"saw":{"tr":"gördü","alt":"see fiilinin geçmiş hali"},"didn't":{"tr":"-madı, -medi","alt":"did not"},"did":{"tr":"geçmiş zaman yardımcısı","alt":"soru ve kısa cevapta"}}}$dm$::jsonb where id = 'ee9d9b54-d9f1-4650-8581-91bd65a75355' and topic_name = 'Past simple (regular and irregular verbs) — Geçmiş Zaman (Düzenli ve Düzensiz Fiiller)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir şeyin <b>ne zaman</b> olduğunu <b>at, on, in</b> ile, bir şeyin <b>nereye doğru hareket ettiğini</b> ise <b>into, onto, across, through</b> gibi edatlarla anlatmayı öğreneceksin.</p><h3>Zaman edatları: at, on, in</h3><p>Türkçede hepsine <b>-de / -da</b> deriz. İngilizcede zamanın türüne göre üç farklı kelime var.</p><table><tr><th>Edat</th><th>Ne için?</th><th>Örnek</th></tr><tr><td><b>at</b></td><td>saatler, gece, hafta sonu</td><td><i>at nine o'clock, at night, at the weekend</i></td></tr><tr><td><b>on</b></td><td>günler, tarihler, özel günler</td><td><i>on Monday, on the fifth of May, on my birthday</i></td></tr><tr><td><b>in</b></td><td>aylar, mevsimler, yıllar, günün bölümleri</td><td><i>in January, in summer, in the morning</i></td></tr></table><p>Kolay hatırla: <b>at</b> en küçük zaman (saat), <b>on</b> gün, <b>in</b> daha uzun zaman (ay, mevsim, yıl). Ama gece için <b>at night</b> denir.</p><h3>Hareket edatları</h3><table><tr><th>Edat</th><th>Anlamı</th><th>Örnek</th></tr><tr><td><b>to</b></td><td>-e, -a doğru</td><td><i>Ece walks to school.</i></td></tr><tr><td><b>into</b></td><td>içine</td><td><i>Papi flew into the garden.</i></td></tr><tr><td><b>out of</b></td><td>içinden dışarı</td><td><i>Ali ran out of the classroom.</i></td></tr><tr><td><b>onto</b></td><td>üstüne</td><td><i>The cat jumped onto the table.</i></td></tr><tr><td><b>across</b></td><td>bir yandan öbür yana, karşıya</td><td><i>We walked across the bridge.</i></td></tr><tr><td><b>through</b></td><td>içinden geçerek</td><td><i>Papi flew through the window.</i></td></tr><tr><td><b>up / down</b></td><td>yukarı / aşağı</td><td><i>The ball rolled down the hill.</i></td></tr></table><h3>Dikkat!</h3><ul><li>Günlerle on kullanılır: <i>in Monday</i> yanlış → <i>on Monday</i>.</li><li>Sabah, öğleden sonra ve akşam için in the: <i>at the morning</i> yanlış → <i>in the morning</i>.</li><li>home ile to kullanılmaz: <i>I go to home.</i> yanlış → <i>I go home.</i></li><li>Bir şeyin içine girerken into: <i>The cat jumped in the box.</i> yerine hareket için → <i>The cat jumped into the box.</i></li></ul><h3>Kısaca</h3><p>Saatler için <b>at</b>, günler ve tarihler için <b>on</b>, aylar, yıllar ve mevsimler için <b>in</b> kullan. Hareketi anlatırken yönü gösteren edatı seç: <b>into</b> içine, <b>onto</b> üstüne, <b>across</b> karşıya.</p>","ornekler":[{"en":"My birthday is on the fifth of May.","tr":"Doğum günüm beş mayısta."},{"en":"We have English at nine o'clock.","tr":"Saat dokuzda İngilizce dersimiz var."},{"en":"It often snows in January.","tr":"Ocak ayında sık sık kar yağar."},{"en":"I play football on Saturday mornings.","tr":"Cumartesi sabahları futbol oynarım."},{"en":"The cat jumped onto the table.","tr":"Kedi masanın üstüne atladı."},{"en":"We walked across the bridge.","tr":"Köprüden karşıya yürüdük."},{"en":"Ali ran out of the classroom.","tr":"Ali sınıftan dışarı koştu."},{"en":"The ball rolled down the hill.","tr":"Top tepeden aşağı yuvarlandı."},{"en":"Papi flew through the window into the garden.","tr":"Papi pencereden geçip bahçeye uçtu."},{"en":"Ece walks to school every morning.","tr":"Ece her sabah okula yürüyerek gider."}],"test":[{"tip":"secim","soru":"\"Pazartesi günü\" İngilizcede nasıl söylenir?","secenekler":["in Monday","on Monday","at Monday"],"dogru":1,"aciklama":"Günlerle on kullanılır: on Monday."},{"tip":"bosluk","soru":"We have English ___ nine o'clock.","tr":"Saat dokuzda İngilizce dersimiz var.","secenekler":["at","in","on"],"dogru":0,"aciklama":"Saatlerle at kullanılır: at nine o'clock."},{"tip":"bosluk","soru":"It often snows ___ January.","tr":"Ocak ayında sık sık kar yağar.","secenekler":["on","at","in"],"dogru":2,"aciklama":"Aylarla in kullanılır: in January."},{"tip":"secim","soru":"\"Kedi masanın üstüne atladı.\" cümlesinin İngilizcesi hangisi?","secenekler":["The cat jumped into the table.","The cat jumped out of the table.","The cat jumped onto the table."],"dogru":2,"aciklama":"Bir şeyin üstüne hareket için onto kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We","walked","across","the","bridge"],"cevap":"We walked across the bridge.","tr":"Köprüden karşıya yürüdük.","aciklama":"Bir yandan öbür yana geçmek için across kullanılır."},{"tip":"bosluk","soru":"Ali ran ___ of the classroom.","tr":"Ali sınıftan dışarı koştu.","secenekler":["into","out","across"],"dogru":1,"aciklama":"İçeriden dışarı hareket için out of kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["My","cat","jumped","into","the","box"],"cevap":"My cat jumped into the box.","tr":"Kedim kutunun içine atladı.","aciklama":"Bir şeyin içine doğru hareket için into kullanılır."},{"tip":"secim","soru":"\"Sabahları erken kalkarım.\" cümlesinin İngilizcesi hangisi?","secenekler":["I get up early in the morning.","I get up early at the morning.","I get up early on the morning."],"dogru":0,"aciklama":"Sabah için in the morning denir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Papi","flew","through","the","window"],"cevap":"Papi flew through the window.","tr":"Papi pencereden geçerek uçtu.","aciklama":"Bir şeyin içinden geçmek için through kullanılır."},{"tip":"dogruyanlis","soru":"\"I go to home after school.\" Bu cümle doğru mu?","dogru":false,"aciklama":"home kelimesiyle to kullanılmaz: I go home after school."}],"kelimeSozlugu":{"at":{"tr":"-de, -da (saat)","alt":"at nine o'clock"},"on":{"tr":"-de, -da (gün, tarih)","alt":"on Monday"},"in":{"tr":"-de, -da (ay, yıl, mevsim)","alt":"in January"},"into":{"tr":"içine","alt":""},"onto":{"tr":"üstüne","alt":""},"out of":{"tr":"içinden dışarı","alt":""},"across":{"tr":"karşıya, bir yandan öbür yana","alt":""},"through":{"tr":"içinden geçerek","alt":""},"down":{"tr":"aşağı","alt":""}}}$dm$::jsonb where id = 'bb61be7f-062a-430c-868c-1b7b2f6810f9' and topic_name = 'Prepositions of time and movement — Zaman ve Hareket Edatları';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Geçmişte olan ama <b>ne zaman olduğunu söylemediğimiz</b> ya da sonucu şu an önemli olan olayları anlatmayı öğreneceksin. Hayatında yaptığın şeyleri (deneyimlerini) de bu zamanla anlatırsın: <i>I have seen a dolphin.</i> = Bir yunus gördüm.</p><h3>Kalıp: have / has + fiilin 3. hali (V3)</h3><table><tr><th>Kişi</th><th>Olumlu</th><th>Olumsuz</th><th>Soru</th></tr><tr><td>I / you / we / they</td><td>I <b>have</b> ('ve) finished</td><td>I <b>haven't</b> finished</td><td><b>Have</b> you finished?</td></tr><tr><td>he / she / it</td><td>she <b>has</b> ('s) finished</td><td>she <b>hasn't</b> finished</td><td><b>Has</b> she finished?</td></tr></table><p>Kısa cevaplar: <i>Yes, I have. / No, I haven't.</i> <i>Yes, he has. / No, he hasn't.</i></p><p>Düzenli fiillerde V3, geçmiş hal ile aynıdır: <i>play → played → played</i>. Düzensiz fiilleri ezberlemen gerekir:</p><table><tr><th>Fiil</th><th>Geçmiş (V2)</th><th>V3</th><th>Türkçe</th></tr><tr><td>see</td><td>saw</td><td><b>seen</b></td><td>görmek</td></tr><tr><td>eat</td><td>ate</td><td><b>eaten</b></td><td>yemek</td></tr><tr><td>do</td><td>did</td><td><b>done</b></td><td>yapmak</td></tr><tr><td>lose</td><td>lost</td><td><b>lost</b></td><td>kaybetmek</td></tr><tr><td>buy</td><td>bought</td><td><b>bought</b></td><td>satın almak</td></tr><tr><td>break</td><td>broke</td><td><b>broken</b></td><td>kırmak</td></tr><tr><td>go</td><td>went</td><td><b>gone / been</b></td><td>gitmek</td></tr></table><h3>Ne zaman kullanırız?</h3><ul><li><b>Sonuç şimdi önemli:</b> <i>Ali has lost his keys.</i> = Ali anahtarlarını kaybetti. (Şu an anahtarları yok.)</li><li><b>Deneyim:</b> <b>ever</b> (hiç, soruda) ve <b>never</b> (hiç ... -madım) ile. <i>Have you ever been to Cappadocia?</i> = Hiç Kapadokya'ya gittin mi? <i>I have never seen a real penguin.</i></li><li><b>just</b> (az önce): <i>We have just eaten lunch.</i></li><li><b>already</b> (çoktan, zaten): <i>Zeynep has already read this book.</i></li><li><b>yet</b> (henüz, daha): olumsuz ve soru cümlelerinin <b>sonunda</b>. <i>Mert hasn't cleaned his room yet.</i></li></ul><p><b>been to</b> = gidip gelmiş olmak: <i>I have been to Ankara.</i> (Gittim, döndüm.)</p><h3>Dikkat!</h3><ul><li>he / she / it ile has: <i>She have finished.</i> → <i>She has finished.</i></li><li>V2 değil V3: <i>I have went.</i> → <i>I have been.</i> <i>I have saw it.</i> → <i>I have seen it.</i></li><li>Belli bir zaman söylüyorsan present perfect kullanılmaz: <i>I have seen it yesterday.</i> → <i>I saw it yesterday.</i></li><li>yet cümlenin sonuna gelir: <i>I haven't yet finished.</i> → <i>I haven't finished yet.</i></li></ul><h3>Kısaca</h3><p>Present perfect <b>have / has + V3</b> ile kurulur ve zamanı belli olmayan geçmiş olayları, deneyimleri ve şimdiki sonuçları anlatır. <b>ever, never, just, already, yet</b> bu zamanın en iyi arkadaşlarıdır.</p>","ornekler":[{"en":"I have finished my homework. Can I go out?","tr":"Ödevimi bitirdim. Dışarı çıkabilir miyim?"},{"en":"Oh no! Ali has lost his keys.","tr":"Eyvah! Ali anahtarlarını kaybetti."},{"en":"We have just eaten lunch.","tr":"Az önce öğle yemeği yedik."},{"en":"Zeynep has already read this book.","tr":"Zeynep bu kitabı çoktan okudu."},{"en":"I have never seen a real penguin.","tr":"Hiç gerçek bir penguen görmedim."},{"en":"Have you ever been to Cappadocia?","tr":"Hiç Kapadokya'ya gittin mi?"},{"en":"Mert hasn't cleaned his room yet.","tr":"Mert henüz odasını toplamadı."},{"en":"Has Papi learned a new word? Yes, he has!","tr":"Papi yeni bir kelime öğrendi mi? Evet, öğrendi!"},{"en":"They have bought a new puppy.","tr":"Yeni bir köpek yavrusu aldılar."},{"en":"Have you done your homework yet?","tr":"Ödevini yaptın mı?"}],"test":[{"tip":"bosluk","soru":"She ___ finished her lunch.","tr":"Öğle yemeğini bitirdi.","secenekler":["have","has","is"],"dogru":1,"aciklama":"He / she / it ile has kullanılır: She has finished."},{"tip":"secim","soru":"\"eat\" fiilinin 3. hali (V3) hangisi?","secenekler":["ate","eated","eaten"],"dogru":2,"aciklama":"Eat düzensizdir: eat, ate, eaten. Ate geçmiş hal (V2)'dir."},{"tip":"bosluk","soru":"I have ___ a new game.","tr":"Yeni bir oyun aldım.","secenekler":["bought","buyed","buy"],"dogru":0,"aciklama":"Buy düzensizdir; V3 hali bought olur."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We've","never","seen","snow"],"cevap":"We've never seen snow.","tr":"Hiç kar görmedik.","aciklama":"Never, have ('ve) ile V3 arasına gelir: We've never seen."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["I have seen this film yesterday.","I saw this film yesterday.","I have saw this film."],"dogru":1,"aciklama":"Yesterday belli bir zamandır, past simple gerekir: I saw ..."},{"tip":"bosluk","soru":"I haven't finished my project ___.","tr":"Projemi henüz bitirmedim.","secenekler":["already","just","yet"],"dogru":2,"aciklama":"Olumsuz cümlenin sonunda henüz anlamında yet kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Have","you","ever","been","to","Ankara"],"cevap":"Have you ever been to Ankara?","tr":"Hiç Ankara'ya gittin mi?","aciklama":"Deneyim sorusu: Have + you + ever + V3 ...?"},{"tip":"secim","soru":"\"Has Can called you?\" sorusuna doğru olumsuz cevap hangisi?","secenekler":["No, he hasn't.","No, he haven't.","No, he didn't."],"dogru":0,"aciklama":"Has ile sorulan soruya hasn't ile cevap verilir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["She's","just","broken","her","glasses"],"cevap":"She's just broken her glasses.","tr":"Az önce gözlüğünü kırdı.","aciklama":"Just, has ('s) ile V3 arasına gelir: She's just broken."},{"tip":"dogruyanlis","soru":"\"I have lost my key.\" cümlesi, anahtarın şu an hâlâ kayıp olduğunu gösterir.","dogru":true,"aciklama":"Doğru! Present perfect, geçmişteki olayın şimdiki sonucunu gösterir: anahtar hâlâ yok."}],"kelimeSozlugu":{"have":{"tr":"yardımcı fiil","alt":"I / you / we / they ile"},"has":{"tr":"yardımcı fiil","alt":"he / she / it ile"},"ever":{"tr":"hiç (soruda)","alt":"Have you ever ...?"},"never":{"tr":"hiç (olumsuz)","alt":"I have never ..."},"just":{"tr":"az önce","alt":""},"already":{"tr":"çoktan, zaten","alt":""},"yet":{"tr":"henüz, daha","alt":"cümle sonunda"},"been":{"tr":"bulunmuş, gidip gelmiş","alt":"be fiilinin V3 hali"}}}$dm$::jsonb where id = 'e673da85-f661-44e8-a607-8419ab955c3f' and topic_name = 'Present perfect (basic) — Yakın Geçmiş Zaman (Present Perfect)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Türkçede <i>kalemimi kaybettim</i> deriz ve tek bir zaman kullanırız. İngilizcede ise iki seçenek var: <b>past simple</b> (I lost) ve <b>present perfect</b> (I have lost). Bu konuda hangisini ne zaman seçeceğini öğreneceksin.</p><h3>En önemli soru: Zaman belli mi?</h3><table><tr><th>Past simple</th><th>Present perfect</th></tr><tr><td>Olayın <b>ne zaman</b> olduğu belli.</td><td>Ne zaman olduğu belli değil ya da önemli değil.</td></tr><tr><td>fiil + <b>-ed</b> / V2</td><td><b>have / has + V3</b></td></tr><tr><td><b>yesterday</b>, <b>last</b> week, two days <b>ago</b>, in 2022, <b>when</b> I was five</td><td><b>ever</b>, <b>never</b>, <b>just</b>, <b>already</b>, <b>yet</b></td></tr><tr><td><i>I lost my pen yesterday.</i></td><td><i>I have lost my pen.</i> (Şu an kalemim yok.)</td></tr><tr><td><i>We ate pizza two days ago.</i></td><td><i>We have never eaten sushi.</i></td></tr></table><h3>Sohbette ikisi birlikte</h3><p>Bir konuşmaya çoğu zaman <b>present perfect</b> ile başlarız (genel bir soru, zaman yok). Ayrıntılara geçince, yani <b>ne zaman, nerede, nasıl</b> diye sorunca <b>past simple</b>'a geçeriz.</p><ul><li><i>— Have you ever been to Antalya?</i> = Hiç Antalya'ya gittin mi?</li><li><i>— Yes, I have.</i> = Evet, gittim.</li><li><i>— When did you go there?</i> = Ne zaman gittin?</li><li><i>— I went last summer. It was great!</i> = Geçen yaz gittim. Harikaydı!</li></ul><h3>When ile hangisi?</h3><p><b>When</b> (ne zaman) sorusu belli bir zaman ister. Bu yüzden when ile her zaman <b>past simple</b> kullanılır: <i>When did you see Papi?</i> Doğru. <i>When have you seen Papi?</i> Yanlış.</p><p>İpucu: Cümlede yesterday, last, ago gibi bir zaman kelimesi görürsen past simple'ı seç. ever, never, just, already, yet görürsen present perfect'i seç.</p><h3>Dikkat!</h3><ul><li>Belli zamanla present perfect olmaz: <i>I have visited Rome last year.</i> → <i>I visited Rome last year.</i></li><li>When ile past simple: <i>When have you bought it?</i> → <i>When did you buy it?</i></li><li>ago ile past simple: <i>He has broken his arm two weeks ago.</i> → <i>He broke his arm two weeks ago.</i></li></ul><h3>Kısaca</h3><p>Zaman belliyse (yesterday, last, ago, when) <b>past simple</b>, zaman belli değilse ya da sonuç şimdi önemliyse <b>present perfect</b> kullan. Sohbete present perfect ile başla, ayrıntıları past simple ile anlat.</p>","ornekler":[{"en":"I have lost my pen. Can I borrow yours?","tr":"Kalemimi kaybettim. Seninkini ödünç alabilir miyim?"},{"en":"I lost my pen yesterday.","tr":"Dün kalemimi kaybettim."},{"en":"Have you ever been to Antalya? Yes, I have.","tr":"Hiç Antalya'ya gittin mi? Evet, gittim."},{"en":"When did you go there? I went last summer.","tr":"Oraya ne zaman gittin? Geçen yaz gittim."},{"en":"Can has already met the new teacher.","tr":"Can yeni öğretmenle çoktan tanıştı."},{"en":"He met her on Monday.","tr":"Onunla pazartesi tanıştı."},{"en":"We have never eaten sushi.","tr":"Hiç suşi yemedik."},{"en":"We ate pizza two days ago.","tr":"İki gün önce pizza yedik."},{"en":"Ece has just arrived home.","tr":"Ece az önce eve geldi."},{"en":"Papi learned three new words last week.","tr":"Papi geçen hafta üç yeni kelime öğrendi."}],"test":[{"tip":"bosluk","soru":"I ___ to the zoo last Sunday.","tr":"Geçen pazar hayvanat bahçesine gittim.","secenekler":["have gone","went","have been"],"dogru":1,"aciklama":"Last Sunday belli bir zamandır, past simple gerekir: went."},{"tip":"bosluk","soru":"Have you ever ___ a horse?","tr":"Hiç ata bindin mi?","secenekler":["ridden","rode","ride"],"dogru":0,"aciklama":"Have you ever ...? present perfect'tir; V3 gerekir: ride, rode, ridden."},{"tip":"secim","soru":"Hangi kelime past simple ile kullanılır?","secenekler":["ever","yet","yesterday"],"dogru":2,"aciklama":"Yesterday belli bir zamandır. Ever ve yet present perfect ile gelir."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["She has visited her aunt last week.","She visited her aunt last week.","She have visited her aunt last week."],"dogru":1,"aciklama":"Last week zamanı belli eder, bu yüzden past simple: She visited ..."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["When","did","you","buy","that","bike"],"cevap":"When did you buy that bike?","tr":"O bisikleti ne zaman aldın?","aciklama":"When ile past simple kullanılır: When did you ...?"},{"tip":"bosluk","soru":"Mert ___ his leg two weeks ago.","tr":"Mert iki hafta önce bacağını kırdı.","secenekler":["broke","has broken","have broken"],"dogru":0,"aciklama":"Ago ile past simple kullanılır: broke."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I've","never","tried","Chinese","food"],"cevap":"I've never tried Chinese food.","tr":"Hiç Çin yemeği denemedim.","aciklama":"Deneyim, zaman yok: I've (I have) + never + V3."},{"tip":"secim","soru":"Arkadaşın \"I have been to a concert.\" dedi. Ne zaman gittiğini nasıl sorarsın?","secenekler":["When have you gone?","When you went?","When did you go?"],"dogru":2,"aciklama":"Ayrıntı sorulurken past simple'a geçilir: When did you go?"},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["How","did","you","break","your","leg"],"cevap":"How did you break your leg?","tr":"Bacağını nasıl kırdın?","aciklama":"Ayrıntı sorarken (nasıl, ne zaman) past simple kullanılır: How did you ...?"},{"tip":"dogruyanlis","soru":"\"When have you seen Papi?\" Bu cümle doğru mu?","dogru":false,"aciklama":"When ile past simple kullanılır: When did you see Papi?"}],"kelimeSozlugu":{"yesterday":{"tr":"dün","alt":"past simple"},"ago":{"tr":"önce","alt":"past simple"},"last":{"tr":"geçen","alt":"past simple"},"ever":{"tr":"hiç (soruda)","alt":"present perfect"},"never":{"tr":"hiç (olumsuz)","alt":"present perfect"},"already":{"tr":"çoktan","alt":"present perfect"},"just":{"tr":"az önce","alt":"present perfect"},"when":{"tr":"ne zaman","alt":"past simple ile"}}}$dm$::jsonb where id = '725f428a-e348-45e7-8438-3ebe6645ea79' and topic_name = 'Present perfect vs past simple (basic) — Present Perfect ve Past Simple Farkı';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir şeyin ne kadar ya da kaç tane olduğunu <b>much, many, a lot of, a few</b> ve <b>a little</b> ile anlatmayı öğreneceksin. Ayrıca <b>How much?</b> ve <b>How many?</b> sorularını soracaksın.</p><h3>Önce isme bak: sayılabilir mi?</h3><ul><li><b>Sayılabilen isimler</b> (countable): Tek tek sayabilirsin; çoğul olur. <i>apples, friends, students, cars</i></li><li><b>Sayılamayan isimler</b> (uncountable): Tek tek sayamazsın; çoğul olmaz. <i>water, milk, sugar, money, time, homework</i></li></ul><p>Türkçede <i>çok elma</i> da <i>çok su</i> da deriz. İngilizcede ise kelime isme göre değişir.</p><h3>Hangisini ne zaman kullanırız?</h3><table><tr><th></th><th>Sayılabilen (apples)</th><th>Sayılamayan (water)</th></tr><tr><td><b>çok</b></td><td><b>many</b> apples</td><td><b>much</b> water</td></tr><tr><td><b>çok</b> (her ikisi)</td><td><b>a lot of</b> apples</td><td><b>a lot of</b> water</td></tr><tr><td><b>birkaç / biraz</b></td><td><b>a few</b> apples</td><td><b>a little</b> water</td></tr><tr><td><b>kaç / ne kadar?</b></td><td><b>How many</b> apples?</td><td><b>How much</b> water?</td></tr></table><ul><li><b>much</b> ve <b>many</b> en çok olumsuz cümlelerde ve sorularda kullanılır: <i>There aren't many apples.</i> <i>Is there much juice?</i></li><li>Olumlu cümlede genelde <b>a lot of</b> deriz: <i>I have a lot of friends.</i> <i>We have a lot of homework.</i></li></ul><h3>Soru sormak</h3><ul><li><b>How many + çoğul isim</b> = Kaç tane? <i>How many students are there in your class?</i></li><li><b>How much + sayılamayan isim</b> = Ne kadar? <i>How much water do you drink?</i></li></ul><h3>Dikkat!</h3><ul><li>homework sayılamaz: <i>many homeworks</i> yanlış → <i>a lot of homework</i>.</li><li>a lot of kalıbında of unutulmaz: <i>a lot friends</i> yanlış → <i>a lot of friends</i>.</li><li>Sayılamayanla many olmaz: <i>How many money?</i> yanlış → <i>How much money?</i></li><li>Çoğul isimle much olmaz: <i>There aren't much apples.</i> yanlış → <i>There aren't many apples.</i></li></ul><h3>Kısaca</h3><p>Sayılabilen isimlerle <b>many</b> ve <b>a few</b>, sayılamayanlarla <b>much</b> ve <b>a little</b> kullan. <b>a lot of</b> ise ikisiyle de olur.</p>","ornekler":[{"en":"How many students are there in your class?","tr":"Sınıfınızda kaç öğrenci var?"},{"en":"How much water do you drink every day?","tr":"Her gün ne kadar su içersin?"},{"en":"I have a lot of friends at school.","tr":"Okulda bir sürü arkadaşım var."},{"en":"There aren't many apples in the basket.","tr":"Sepette çok elma yok."},{"en":"Ali doesn't eat much sugar.","tr":"Ali çok şeker yemez."},{"en":"We have a lot of homework today.","tr":"Bugün çok ödevimiz var."},{"en":"I've got a few comics in my bag.","tr":"Çantamda birkaç çizgi roman var."},{"en":"Can I have a little milk, please?","tr":"Biraz süt alabilir miyim lütfen?"},{"en":"Papi eats a lot of seeds every day.","tr":"Papi her gün bir sürü tohum yer."},{"en":"Is there much juice in the bottle?","tr":"Şişede çok meyve suyu var mı?"}],"test":[{"tip":"secim","soru":"Hangisi sayılamayan bir isimdir?","secenekler":["water","apple","book"],"dogru":0,"aciklama":"Su tek tek sayılamaz; water sayılamayan bir isimdir."},{"tip":"bosluk","soru":"How ___ students are there in your class?","tr":"Sınıfınızda kaç öğrenci var?","secenekler":["much","lot","many"],"dogru":2,"aciklama":"students sayılabilen çoğul bir isimdir: How many."},{"tip":"bosluk","soru":"Ali doesn't eat ___ sugar.","tr":"Ali çok şeker yemez.","secenekler":["many","much","a few"],"dogru":1,"aciklama":"sugar sayılamaz; olumsuz cümlede much kullanılır."},{"tip":"secim","soru":"\"Bugün çok ödevimiz var.\" cümlesinin İngilizcesi hangisi?","secenekler":["We have many homeworks today.","We have a lot of homework today.","We have a lot homework today."],"dogru":1,"aciklama":"homework sayılamaz ve çoğul olmaz; a lot of homework denir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","have","a","lot","of","friends"],"cevap":"I have a lot of friends.","tr":"Bir sürü arkadaşım var.","aciklama":"Olumlu cümlede a lot of kullanılır; of unutulmaz."},{"tip":"bosluk","soru":"Can I have a ___ milk, please?","tr":"Biraz süt alabilir miyim lütfen?","secenekler":["few","little","many"],"dogru":1,"aciklama":"milk sayılamaz; biraz demek için a little kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["How","much","water","do","you","drink"],"cevap":"How much water do you drink?","tr":"Ne kadar su içersin?","aciklama":"water sayılamaz, bu yüzden How much ile sorulur."},{"tip":"secim","soru":"\"Sepette çok elma yok.\" cümlesinin İngilizcesi hangisi?","secenekler":["There isn't much apples in the basket.","There aren't much apples in the basket.","There aren't many apples in the basket."],"dogru":2,"aciklama":"apples sayılabilen çoğul isimdir: aren't many apples."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I've","got","a","few","comics"],"cevap":"I've got a few comics.","tr":"Birkaç çizgi romanım var.","aciklama":"comics sayılabilir; birkaç demek için a few kullanılır."},{"tip":"dogruyanlis","soru":"\"a lot of\" hem sayılabilen hem de sayılamayan isimlerle kullanılır.","dogru":true,"aciklama":"Doğru! a lot of friends da a lot of water da denir."}],"kelimeSozlugu":{"much":{"tr":"çok","alt":"sayılamayan isimlerle"},"many":{"tr":"çok","alt":"sayılabilen isimlerle"},"a lot of":{"tr":"çok, bir sürü","alt":"her ikisiyle de"},"a few":{"tr":"birkaç","alt":"sayılabilen isimlerle"},"a little":{"tr":"biraz","alt":"sayılamayan isimlerle"},"how many":{"tr":"kaç tane","alt":""},"how much":{"tr":"ne kadar","alt":""}}}$dm$::jsonb where id = 'b3382c94-ac21-4451-89a9-a9ebe4e1d2de' and topic_name = 'Quantifiers (much, many, a lot of, etc.) — Miktar Belirteçleri';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Cümlenin sonuna eklenen kısa sorularla <b>“değil mi?”</b> demeyi öğreneceksin: <i>It's a nice day, isn't it?</i> Bunlara <b>question tags</b> (onay soruları) denir.</p><h3>Olumluya olumsuz, olumsuza olumlu</h3><p>Türkçede her zaman <b>değil mi?</b> deriz. İngilizcede ise kısa soru cümleye göre değişir.</p><ul><li>Cümle <b>olumlu</b> ise soru <b>olumsuz</b> olur: <i>You are tired, <b>aren't you</b>?</i></li><li>Cümle <b>olumsuz</b> ise soru <b>olumlu</b> olur: <i>You aren't tired, <b>are you</b>?</i></li></ul><h3>Hangi yardımcı fiil?</h3><p>Cümlede hangi yardımcı fiil varsa kısa soruda da o kullanılır. Yardımcı fiil yoksa geniş zamanda <b>do / does</b>, geçmiş zamanda <b>did</b> gelir. İsim yerine <b>zamir</b> kullanılır: Zeynep → she, Ali → he, the cat → it.</p><table><tr><th>Cümle</th><th>Kısa soru</th></tr><tr><td><i>It's a nice day,</i></td><td><b>isn't it?</b></td></tr><tr><td><i>Zeynep can swim,</i></td><td><b>can't she?</b></td></tr><tr><td><i>Ali will help us,</i></td><td><b>won't he?</b></td></tr><tr><td><i>You like chocolate,</i></td><td><b>don't you?</b></td></tr><tr><td><i>Your cat doesn't eat fish,</i></td><td><b>does it?</b></td></tr><tr><td><i>They went to the zoo,</i></td><td><b>didn't they?</b></td></tr><tr><td><i>I'm late,</i></td><td><b>aren't I?</b> (özel durum)</td></tr></table><h3>Ses tonu</h3><p>Cevaptan eminsen ve sadece onay istiyorsan sesin sonda <b>alçalır</b>. Gerçekten bilmiyorsan ve soruyorsan sesin sonda <b>yükselir</b>.</p><h3>Dikkat!</h3><ul><li>Her cümleye isn't it eklenmez: <i>You like chocolate, isn't it?</i> yanlış → <i>You like chocolate, don't you?</i></li><li>Olumsuz cümleye olumsuz soru eklenmez: <i>You aren't tired, aren't you?</i> yanlış → <i>You aren't tired, are you?</i></li><li>Kısa soruda isim değil zamir: <i>Zeynep can swim, can't Zeynep?</i> yanlış → <i>can't she?</i></li><li>I am için: <i>I'm late, amn't I?</i> değil → <i>I'm late, aren't I?</i></li></ul><h3>Kısaca</h3><p>Olumlu cümleye olumsuz, olumsuz cümleye olumlu kısa soru ekle. Cümledeki yardımcı fiili (yoksa do, does, did) ve bir zamiri kullan.</p>","ornekler":[{"en":"You like chocolate, don't you?","tr":"Çikolatayı seversin, değil mi?"},{"en":"It's a nice day, isn't it?","tr":"Güzel bir gün, değil mi?"},{"en":"Zeynep can swim, can't she?","tr":"Zeynep yüzebilir, değil mi?"},{"en":"They went to the zoo, didn't they?","tr":"Hayvanat bahçesine gittiler, değil mi?"},{"en":"You aren't tired, are you?","tr":"Yorgun değilsin, değil mi?"},{"en":"Ali will help us, won't he?","tr":"Ali bize yardım edecek, değil mi?"},{"en":"Your cat doesn't eat fish, does it?","tr":"Kedin balık yemiyor, değil mi?"},{"en":"We have a test today, don't we?","tr":"Bugün sınavımız var, değil mi?"},{"en":"Papi is very clever, isn't he?","tr":"Papi çok akıllı, değil mi?"},{"en":"I'm late, aren't I?","tr":"Geç kaldım, değil mi?"}],"test":[{"tip":"bosluk","soru":"It's a nice day, ___ it?","tr":"Güzel bir gün, değil mi?","secenekler":["is","isn't","doesn't"],"dogru":1,"aciklama":"Cümle olumlu ve is ile kurulmuş, kısa soru isn't it olur."},{"tip":"bosluk","soru":"You like chocolate, ___ you?","tr":"Çikolatayı seversin, değil mi?","secenekler":["don't","aren't","isn't"],"dogru":0,"aciklama":"Geniş zamanda yardımcı fiil yoksa do kullanılır: don't you?"},{"tip":"bosluk","soru":"Zeynep can swim, ___?","tr":"Zeynep yüzebilir, değil mi?","secenekler":["isn't she","can she","can't she"],"dogru":2,"aciklama":"Cümlede can var ve olumlu, kısa soru can't she olur."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["You aren't tired, aren't you?","You aren't tired, are you?","You aren't tired, do you?"],"dogru":1,"aciklama":"Olumsuz cümleye olumlu kısa soru eklenir: are you?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Ali","will","help","us","won't","he"],"cevap":"Ali will help us, won't he?","tr":"Ali bize yardım edecek, değil mi?","aciklama":"will olan olumlu cümleye won't + zamir eklenir."},{"tip":"secim","soru":"\"They went to the zoo, ___?\" Boşluğa hangisi gelir?","secenekler":["didn't they","don't they","weren't they"],"dogru":0,"aciklama":"went geçmiş zamandır, kısa soruda did kullanılır: didn't they?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Elif","plays","the","piano","doesn't","she"],"cevap":"Elif plays the piano, doesn't she?","tr":"Elif piyano çalar, değil mi?","aciklama":"Geniş zamanda olumlu cümleye doesn't + zamir eklenir; Elif yerine she."},{"tip":"secim","soru":"\"I'm late, ___?\" Boşluğa hangisi gelir?","secenekler":["don't I","isn't I","aren't I"],"dogru":2,"aciklama":"I am için özel kısa soru aren't I kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Mert","doesn't","like","fish","does","he"],"cevap":"Mert doesn't like fish, does he?","tr":"Mert balık sevmez, değil mi?","aciklama":"Olumsuz cümleye olumlu kısa soru eklenir: does he?"},{"tip":"dogruyanlis","soru":"\"Your cat doesn't eat fish, doesn't it?\" Bu cümle doğru mu?","dogru":false,"aciklama":"Cümle olumsuz, kısa soru olumlu olmalı: doesn't eat fish, does it?"}],"kelimeSozlugu":{"isn't it":{"tr":"değil mi?","alt":"is olan olumlu cümlede"},"don't you":{"tr":"değil mi?","alt":"geniş zaman, you ile"},"didn't they":{"tr":"değil mi?","alt":"geçmiş zaman, they ile"},"aren't i":{"tr":"değil mi?","alt":"I am için özel kalıp"},"won't he":{"tr":"değil mi?","alt":"will olan cümlede"},"can't she":{"tr":"değil mi?","alt":"can olan cümlede"}}}$dm$::jsonb where id = '37f9cb0f-f0e1-4def-b480-614660ea7f7c' and topic_name = 'Question tags (isn''t it?, don''t you?, etc.) — Onay Soruları (Question Tags)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir kişiyi ya da bir şeyi daha ayrıntılı anlatmak için <b>who, which</b> ve <b>that</b> kullanmayı öğreneceksin. Böylece iki kısa cümleyi tek cümlede birleştirebileceksin.</p><h3>Who, which, that</h3><table><tr><th>Kelime</th><th>Ne için?</th><th>Örnek</th></tr><tr><td><b>who</b></td><td>insanlar</td><td><i>the girl who won the race</i> = yarışı kazanan kız</td></tr><tr><td><b>which</b></td><td>eşyalar, hayvanlar</td><td><i>the ball which I bought</i> = aldığım top</td></tr><tr><td><b>that</b></td><td>hem insanlar hem eşyalar</td><td><i>books that have happy endings</i> = mutlu biten kitaplar</td></tr></table><h3>İki cümleyi birleştirmek</h3><p>Formül: <b>isim + who / which / that + cümlenin geri kalanı</b></p><ul><li><i>I have a friend. She lives in Izmir.</i> → <i>I have a friend <b>who</b> lives in Izmir.</i> (İzmir'de yaşayan bir arkadaşım var.)</li><li><i>This is the cake. My mother made it.</i> → <i>This is the cake <b>which</b> my mother made.</i> (Bu, annemin yaptığı kek.)</li></ul><p>İkinci cümledeki <i>she</i> ya da <i>it</i> kelimesi gider; yerine who ya da which gelir.</p><h3>Türkçeyle farkı: sıra ters!</h3><p>Türkçede anlatan kısım isimden <b>önce</b> gelir: <i>yarışı kazanan</i> kız. İngilizcede ise isimden <b>sonra</b> gelir: <i>the girl who won the race</i>. Önce kişiyi ya da şeyi söyle, sonra onu anlat.</p><ul><li><i>The boy who sits next to me is Can.</i> = Yanımda oturan çocuk Can.</li></ul><h3>Dikkat!</h3><ul><li>İnsanlar için which kullanma: <i>the girl which won</i> yanlış → <i>the girl who won</i>.</li><li>what kullanılmaz: <i>the book what I read</i> yanlış → <i>the book which I read</i>.</li><li>Zamiri tekrar etme: <i>the ball which I bought it</i> yanlış → <i>the ball which I bought</i>.</li><li>Türkçe sırayla kurma: <i>the won the race girl</i> yanlış → <i>the girl who won the race</i>.</li></ul><h3>Kısaca</h3><p>İnsanlar için <b>who</b>, eşya ve hayvanlar için <b>which</b>, ikisi için de <b>that</b> kullan. Bu kelimeler anlattığın ismin hemen arkasından gelir.</p>","ornekler":[{"en":"This is the teacher who helps me with English.","tr":"Bu, bana İngilizcede yardım eden öğretmen."},{"en":"I have a friend who lives in Izmir.","tr":"İzmir'de yaşayan bir arkadaşım var."},{"en":"The cake which my mother made is delicious.","tr":"Annemin yaptığı kek çok lezzetli."},{"en":"I like books that have happy endings.","tr":"Mutlu sonla biten kitapları severim."},{"en":"Zeynep is the girl who won the race.","tr":"Yarışı kazanan kız Zeynep."},{"en":"Papi is a parrot that can talk.","tr":"Papi konuşabilen bir papağan."},{"en":"Where is the ball which I bought yesterday?","tr":"Dün aldığım top nerede?"},{"en":"The boy who sits next to me is Can.","tr":"Yanımda oturan çocuk Can."},{"en":"Do you know the girl who plays the piano?","tr":"Piyano çalan kızı tanıyor musun?"},{"en":"This is the game that everybody loves.","tr":"Bu, herkesin sevdiği oyun."}],"test":[{"tip":"secim","soru":"İnsanlardan bahsederken hangisi kullanılır?","secenekler":["which","who","what"],"dogru":1,"aciklama":"İnsanlar için who kullanılır; which eşya ve hayvanlar içindir."},{"tip":"bosluk","soru":"I have a bike ___ is red.","tr":"Kırmızı olan bir bisikletim var.","secenekler":["who","what","which"],"dogru":2,"aciklama":"Bisiklet bir eşyadır, bu yüzden which kullanılır."},{"tip":"bosluk","soru":"Zeynep is the girl ___ won the race.","tr":"Yarışı kazanan kız Zeynep.","secenekler":["who","which","what"],"dogru":0,"aciklama":"Kız bir insandır, bu yüzden who kullanılır."},{"tip":"secim","soru":"\"Ödülü kazanan çocuk Ali.\" cümlesinin İngilizcesi hangisi?","secenekler":["The boy which won the prize is Ali.","The won the prize boy is Ali.","The boy who won the prize is Ali."],"dogru":2,"aciklama":"İnsan için who kullanılır ve anlatan kısım isimden sonra gelir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","have","a","friend","who","lives","in","Izmir"],"cevap":"I have a friend who lives in Izmir.","tr":"İzmir'de yaşayan bir arkadaşım var.","aciklama":"who, anlattığı ismin (friend) hemen arkasından gelir."},{"tip":"bosluk","soru":"I like books ___ have happy endings.","tr":"Mutlu sonla biten kitapları severim.","secenekler":["that","who","where"],"dogru":0,"aciklama":"Kitaplar eşyadır; that ya da which kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","have","a","cat","which","sleeps","all","day"],"cevap":"I have a cat which sleeps all day.","tr":"Bütün gün uyuyan bir kedim var.","aciklama":"Kedi bir hayvandır, bu yüzden which kullanılır; which, cat kelimesinin hemen arkasından gelir."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["Here is the ball which I bought it.","Here is the ball which I bought.","Here is the ball who I bought."],"dogru":1,"aciklama":"which zaten topu anlatır, it tekrar yazılmaz; top için who kullanılmaz."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Do","you","know","the","boy","who","plays","chess"],"cevap":"Do you know the boy who plays chess?","tr":"Satranç oynayan çocuğu tanıyor musun?","aciklama":"who, boy kelimesinden hemen sonra gelir."},{"tip":"dogruyanlis","soru":"\"that\" hem insanlar hem de eşyalar için kullanılabilir.","dogru":true,"aciklama":"Doğru! that hem who hem de which yerine kullanılabilir."}],"kelimeSozlugu":{"who":{"tr":"-en, -an (insanlar için)","alt":"the girl who won"},"which":{"tr":"-en, -an, -dığı (eşyalar için)","alt":"the ball which I bought"},"that":{"tr":"-en, -an, -dığı","alt":"insan ve eşya için"},"friend":{"tr":"arkadaş","alt":""},"race":{"tr":"yarış","alt":""},"parrot":{"tr":"papağan","alt":""}}}$dm$::jsonb where id = 'eaca3bdb-85a8-4fb8-bc68-6916c5743ba9' and topic_name = 'Relative clauses (who, which, that) — İlgi Cümlecikleri';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>A1 seviyesinde öğrendiğin üç temel yapıyı tekrar edeceksin: <b>am / is / are</b>, <b>have got / has got</b> ve <b>geniş zaman (present simple)</b>. Bu konunun sonunda kendini, aileni ve günlük hayatını rahatça anlatabilecek ve basit sorular sorabileceksin.</p><h3>1. am / is / are (olmak)</h3><p>Birinin ne olduğunu, nerede olduğunu ya da nasıl olduğunu söylerken kullanırız. Türkçedeki <b>-im, -sin, -dir</b> eklerinin karşılığıdır.</p><table><tr><th>Kişi</th><th>Olumlu</th><th>Olumsuz</th><th>Soru</th></tr><tr><td>I</td><td>I <b>am</b> (I'm)</td><td>I'm not</td><td><b>Am</b> I ...?</td></tr><tr><td>he / she / it</td><td>she <b>is</b> (she's)</td><td>she isn't</td><td><b>Is</b> she ...?</td></tr><tr><td>you / we / they</td><td>we <b>are</b> (we're)</td><td>we aren't</td><td><b>Are</b> we ...?</td></tr></table><p><i>I am eleven years old.</i> = On bir yaşındayım. <i>Is Papi hungry?</i> = Papi aç mı?</p><h3>2. have got / has got (sahip olmak)</h3><p>Bir şeyimiz <b>var</b> demek için kullanırız. <b>he / she / it</b> ile <b>has got</b>, diğerleriyle <b>have got</b> gelir.</p><ul><li>Olumlu: <i>Ali has got a black cat.</i> = Ali'nin siyah bir kedisi var.</li><li>Olumsuz: <i>We haven't got a car.</i> = Arabamız yok.</li><li>Soru: <i>Have you got a pet?</i> — <i>Yes, I have. / No, I haven't.</i></li></ul><h3>3. Geniş zaman (present simple)</h3><p>Her zaman, her gün ya da genellikle yaptığımız şeyleri anlatır. <b>he / she / it</b> ile fiile <b>-s</b> eklenir: <i>Ece plays the guitar every day.</i></p><table><tr><th></th><th>I / you / we / they</th><th>he / she / it</th></tr><tr><td>Olumlu</td><td>I <b>play</b></td><td>she <b>plays</b></td></tr><tr><td>Olumsuz</td><td>I <b>don't</b> play</td><td>she <b>doesn't</b> play</td></tr><tr><td>Soru</td><td><b>Do</b> you play?</td><td><b>Does</b> she play?</td></tr></table><p>Soru kelimeleri de bu kalıpla gelir: <b>Where</b> do you live? (Nerede yaşıyorsun?) <b>What</b> does he eat? (O ne yer?) Cevapta fiil tekrar normal haline döner: <i>I live in Izmir.</i></p><h3>Dikkat!</h3><ul><li>Geniş zamanda fiille <b>am / is / are</b> kullanılmaz: <i>He is play football.</i> → <i>He plays football.</i></li><li><b>he / she / it</b> ile <b>has got</b>: <i>She have got a dog.</i> → <i>She has got a dog.</i></li><li><b>does / doesn't</b> varsa fiil -s almaz: <i>Does she likes pizza?</i> → <i>Does she like pizza?</i></li><li><b>agree</b> (katılmak) bir fiildir: <i>I am agree.</i> → <i>I agree.</i></li></ul><h3>Kısaca</h3><p>Bir şeyin ne ya da nasıl olduğunu <b>am / is / are</b>, sahip olduklarını <b>have got / has got</b> ile söylersin. Her gün yaptığın şeyler için geniş zamanı kullan ve he / she / it ile fiile <b>-s</b> eklemeyi unutma.</p>","ornekler":[{"en":"I am eleven years old.","tr":"On bir yaşındayım."},{"en":"My sister isn't at home now.","tr":"Kız kardeşim şu an evde değil."},{"en":"Are you Zeynep's brother?","tr":"Sen Zeynep'in erkek kardeşi misin?"},{"en":"Ali has got a black cat.","tr":"Ali'nin siyah bir kedisi var."},{"en":"We haven't got a car.","tr":"Arabamız yok."},{"en":"Have you got a pet? Yes, I have.","tr":"Evcil hayvanın var mı? Evet, var."},{"en":"Ece plays the guitar every day.","tr":"Ece her gün gitar çalar."},{"en":"My dad doesn't drink coffee.","tr":"Babam kahve içmez."},{"en":"Does Papi talk? Yes, he does!","tr":"Papi konuşur mu? Evet, konuşur!"},{"en":"Where do you live? I live in Izmir.","tr":"Nerede yaşıyorsun? İzmir'de yaşıyorum."}],"test":[{"tip":"bosluk","soru":"My friends ___ in the garden.","tr":"Arkadaşlarım bahçede.","secenekler":["is","are","am"],"dogru":1,"aciklama":"My friends (onlar) çoğuldur, bu yüzden are kullanılır."},{"tip":"secim","soru":"Hangisi doğru?","secenekler":["She has got a dog.","She have got a dog.","She is got a dog."],"dogru":0,"aciklama":"He / she / it ile has got kullanılır: She has got a dog."},{"tip":"bosluk","soru":"Ali ___ football every Saturday.","tr":"Ali her cumartesi futbol oynar.","secenekler":["play","playing","plays"],"dogru":2,"aciklama":"Geniş zamanda he / she / it ile fiile -s eklenir: Ali plays."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I've","got","two","brothers"],"cevap":"I've got two brothers.","tr":"İki erkek kardeşim var.","aciklama":"Kalıp: I've (I have) got + sahip olunan şey."},{"tip":"secim","soru":"\"Kedim süt sevmez.\" cümlesinin İngilizcesi hangisi?","secenekler":["My cat isn't like milk.","My cat doesn't like milk.","My cat don't like milk."],"dogru":1,"aciklama":"It (kedi) ile olumsuz geniş zamanda doesn't + fiil kullanılır."},{"tip":"bosluk","soru":"___ your brother play tennis?","tr":"Erkek kardeşin tenis oynar mı?","secenekler":["Is","Do","Does"],"dogru":2,"aciklama":"Your brother = he. He ile geniş zaman sorusu Does ile başlar."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Where","do","you","live"],"cevap":"Where do you live?","tr":"Nerede yaşıyorsun?","aciklama":"Soru kelimesi + do + you + fiil."},{"tip":"secim","soru":"\"Have you got a bike?\" sorusuna doğru kısa cevap hangisi?","secenekler":["Yes, I am.","Yes, I have.","Yes, I do."],"dogru":1,"aciklama":"Have you got ...? sorusu Yes, I have. ya da No, I haven't. ile cevaplanır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Does","Mert","like","pizza"],"cevap":"Does Mert like pizza?","tr":"Mert pizza sever mi?","aciklama":"Does + kişi + yalın fiil: Does Mert like ...?"},{"tip":"dogruyanlis","soru":"\"I am agree with you.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Agree bir fiildir, am gerekmez: I agree with you."}],"kelimeSozlugu":{"have got":{"tr":"sahip olmak, -si var","alt":"he / she / it ile has got"},"has got":{"tr":"-si var","alt":"he / she / it ile"},"don't":{"tr":"-maz, -mez (olumsuz)","alt":"do not"},"doesn't":{"tr":"-maz, -mez (olumsuz)","alt":"does not; he / she / it ile"},"every day":{"tr":"her gün","alt":""},"where":{"tr":"nerede","alt":"soru kelimesi"}}}$dm$::jsonb where id = 'b7c18f1d-12df-48ea-b2e6-2600d6fbc40b' and topic_name = 'Review of A1 structures — A1 Dil Bilgisi Yapılarının Tekrarı';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir şeyin <b>gereğinden fazla</b> olduğunu <b>too</b> ile, <b>yeterli</b> olduğunu ya da olmadığını <b>enough</b> ile söylemeyi öğreneceksin.</p><h3>Too: gereğinden fazla</h3><p><b>too + sıfat</b> = fazla ..., gereğinden çok ... Genelde bir sorun olduğunu anlatır.</p><ul><li><i>This tea is too hot.</i> = Bu çay fazla sıcak. (İçemiyorum.)</li><li><i>The box is too heavy for me.</i> = Kutu benim için fazla ağır.</li></ul><p><b>too + sıfat + to + fiil</b> = ... yapamayacak kadar ...</p><ul><li><i>This tea is too hot to drink.</i> = Bu çay içilemeyecek kadar sıcak.</li><li><i>Elif is too tired to play.</i> = Elif oynayamayacak kadar yorgun.</li></ul><h3>Enough: yeterince</h3><p>enough kelimesinin yeri değişir. Sıfattan <b>sonra</b>, isimden <b>önce</b> gelir.</p><table><tr><th>Kalıp</th><th>Örnek</th><th>Anlamı</th></tr><tr><td><b>sıfat + enough</b></td><td><i>Can is tall enough.</i></td><td>Can yeterince uzun.</td></tr><tr><td><b>not + sıfat + enough</b></td><td><i>Ali isn't old enough.</i></td><td>Ali yeterince büyük değil.</td></tr><tr><td><b>enough + isim</b></td><td><i>We have enough chairs.</i></td><td>Yeterli sandalyemiz var.</td></tr><tr><td><b>sıfat + enough + to + fiil</b></td><td><i>Can is tall enough to play basketball.</i></td><td>Can basketbol oynayacak kadar uzun.</td></tr></table><h3>Very ile too farkı</h3><p>Türkçede ikisine de çoğu zaman <b>çok</b> deriz ama anlamları farklıdır.</p><ul><li><i>The tea is very hot.</i> = Çay çok sıcak. (Ama belki içebilirim.)</li><li><i>The tea is too hot.</i> = Çay fazla sıcak. (İçemem, sorun var!)</li></ul><h3>Dikkat!</h3><ul><li>enough sıfattan sonra gelir: <i>She is enough tall.</i> yanlış → <i>She is tall enough.</i></li><li>enough isimden önce gelir: <i>I don't enough have money.</i> yanlış → <i>I don't have enough money.</i></li><li>Sorun yoksa too kullanma: <i>I'm too happy today!</i> yerine → <i>I'm very happy today!</i></li><li>too kalıbında to unutulmaz: <i>too hot drink</i> yanlış → <i>too hot to drink</i>.</li></ul><h3>Kısaca</h3><p><b>too</b> sıfattan önce gelir ve gereğinden fazla demektir. <b>enough</b> sıfattan sonra, isimden önce gelir ve yeterince demektir.</p>","ornekler":[{"en":"This tea is too hot to drink.","tr":"Bu çay içilemeyecek kadar sıcak."},{"en":"The box is too heavy for me.","tr":"Kutu benim için fazla ağır."},{"en":"Can is tall enough to play basketball.","tr":"Can basketbol oynayacak kadar uzun."},{"en":"Ali isn't old enough to watch this film.","tr":"Ali bu filmi izleyecek kadar büyük değil."},{"en":"Do we have enough chairs for everyone?","tr":"Herkes için yeterince sandalyemiz var mı?"},{"en":"The music is too loud. Please turn it down.","tr":"Müzik fazla yüksek. Lütfen sesini kıs."},{"en":"I don't have enough money for a new game.","tr":"Yeni bir oyun için yeterince param yok."},{"en":"Is the water warm enough for swimming?","tr":"Su yüzmek için yeterince ılık mı?"},{"en":"Elif is too tired to play today.","tr":"Elif bugün oynayamayacak kadar yorgun."},{"en":"We have enough time for one more game.","tr":"Bir oyun daha oynamaya yetecek kadar vaktimiz var."}],"test":[{"tip":"secim","soru":"\"Kutu benim için fazla ağır.\" cümlesinin İngilizcesi hangisi?","secenekler":["The box is too heavy for me.","The box is heavy too for me.","The box is enough heavy for me."],"dogru":0,"aciklama":"too sıfattan önce gelir: too heavy."},{"tip":"bosluk","soru":"Can is tall ___ to play basketball.","tr":"Can basketbol oynayacak kadar uzun.","secenekler":["too","enough","very"],"dogru":1,"aciklama":"Yeterince anlamı için sıfattan sonra enough gelir: tall enough."},{"tip":"bosluk","soru":"This tea is ___ hot to drink.","tr":"Bu çay içilemeyecek kadar sıcak.","secenekler":["enough","very","too"],"dogru":2,"aciklama":"Yapamayacak kadar demek için too + sıfat + to kullanılır: too hot to drink."},{"tip":"secim","soru":"\"Yeterince param yok.\" cümlesinin İngilizcesi hangisi?","secenekler":["I don't enough have money.","I don't have enough money.","I don't have too money."],"dogru":1,"aciklama":"enough isimden önce gelir: enough money."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Can","looks","tall","enough","to","play","basketball"],"cevap":"Can looks tall enough to play basketball.","tr":"Can basketbol oynayacak kadar uzun görünüyor.","aciklama":"Kalıp: sıfat + enough + to + fiil: tall enough to play."},{"tip":"bosluk","soru":"Elif is too tired ___ play today.","tr":"Elif bugün oynayamayacak kadar yorgun.","secenekler":["to","for","enough"],"dogru":0,"aciklama":"too + sıfat sonrasında fiil to ile gelir: too tired to play."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Mom","bought","enough","apples"],"cevap":"Mom bought enough apples.","tr":"Annem yeterince elma aldı.","aciklama":"enough isimden önce gelir: enough apples."},{"tip":"secim","soru":"\"Hava yüzmek için yeterince sıcak değil.\" cümlesinin İngilizcesi hangisi?","secenekler":["It isn't enough warm to swim.","It isn't warm too to swim.","It isn't warm enough to swim."],"dogru":2,"aciklama":"not + sıfat + enough: isn't warm enough."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","feel","too","tired","to","play"],"cevap":"I feel too tired to play.","tr":"Kendimi oynayamayacak kadar yorgun hissediyorum.","aciklama":"Kalıp: too + sıfat + to + fiil."},{"tip":"dogruyanlis","soru":"\"Mert is enough strong to lift the box.\" Bu cümle doğru mu?","dogru":false,"aciklama":"enough sıfattan sonra gelir: Mert is strong enough to lift the box."}],"kelimeSozlugu":{"too":{"tr":"fazla, gereğinden çok","alt":"sıfattan önce gelir"},"enough":{"tr":"yeterince, yeterli","alt":"sıfattan sonra, isimden önce"},"very":{"tr":"çok","alt":"sorun anlatmaz"},"heavy":{"tr":"ağır","alt":""},"tall":{"tr":"uzun boylu","alt":""},"tired":{"tr":"yorgun","alt":""}}}$dm$::jsonb where id = '000c7515-43eb-4101-b863-e29fe7c75185' and topic_name = 'Too and enough — Aşırılık ve Yeterlilik (Too ve Enough)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Eskiden yaptığın ama <b>artık yapmadığın</b> şeyleri anlatmayı öğreneceksin. Türkçedeki <b>eskiden ...-ardım / -erdim</b> kalıbının karşılığı <b>used to</b>'dur: <i>I used to play with toy cars.</i> = Eskiden oyuncak arabalarla oynardım.</p><h3>Kalıp: used to + fiilin yalın hali</h3><p>Güzel haber: <b>used to</b> bütün kişilerde aynıdır. -s eklemek yok!</p><table><tr><th></th><th>Kalıp</th><th>Örnek</th></tr><tr><td>Olumlu</td><td>kişi + <b>used to</b> + fiil</td><td><i>We used to walk to school.</i> = Okula yürürdük.</td></tr><tr><td>Olumsuz</td><td>kişi + <b>didn't use to</b> + fiil</td><td><i>I didn't use to like fish.</i> = Eskiden balık sevmezdim.</td></tr><tr><td>Soru</td><td><b>Did</b> + kişi + <b>use to</b> + fiil?</td><td><i>Did you use to watch cartoons?</i> = Çizgi film izler miydin?</td></tr></table><p>Kısa cevaplar: <i>Yes, I did. / No, I didn't.</i></p><p>Okunuş: <i>used to</i> “yustı” diye okunur, s sesiyle.</p><h3>Ne zaman kullanırız?</h3><ul><li><b>Eski alışkanlıklar (habit):</b> Eskiden sık sık yaptığın şeyler. <i>My grandpa used to go fishing every Sunday.</i></li><li><b>Eski durumlar:</b> Eskiden doğru olan ama artık doğru olmayan şeyler. <i>Ece used to have long hair.</i> (Şimdi saçları kısa.) <i>There used to be a park here.</i> (Artık yok.)</li></ul><p>Çoğu zaman şimdiyle karşılaştırırız: <i>I used to play with toys, but I don't play with them anymore.</i> = Eskiden oyuncaklarla oynardım ama artık oynamıyorum. <b>anymore</b> = artık.</p><h3>Dikkat!</h3><ul><li>Olumlu cümlede <b>used</b> yazılır: <i>I use to play.</i> → <i>I used to play.</i></li><li>Did / didn't varsa <b>use</b> yazılır, d düşer: <i>I didn't used to eat fish.</i> → <i>I didn't use to eat fish.</i></li><li>used to'dan sonra fiil yalın gelir, -ing almaz: <i>She used to living here.</i> → <i>She used to live here.</i></li><li>Bugünkü alışkanlıklar için used to kullanılmaz: <i>I used to get up at seven now.</i> → <i>I usually get up at seven.</i></li></ul><h3>Kısaca</h3><p>Eskiden olan ama artık olmayan alışkanlık ve durumlar için <b>used to + fiil</b> kullan. Olumsuz ve soruda <b>did</b> geldiği için <b>use to</b> yazılır.</p>","ornekler":[{"en":"I used to play with toy cars when I was five.","tr":"Beş yaşındayken oyuncak arabalarla oynardım."},{"en":"My grandpa used to live in a village.","tr":"Dedem eskiden bir köyde yaşardı."},{"en":"We used to walk to school with Ayşe.","tr":"Eskiden Ayşe ile okula yürürdük."},{"en":"Can used to be afraid of dogs.","tr":"Can eskiden köpeklerden korkardı."},{"en":"Ece used to have long hair.","tr":"Ece'nin eskiden uzun saçları vardı."},{"en":"I didn't use to like vegetables, but now I do.","tr":"Eskiden sebze sevmezdim ama şimdi seviyorum."},{"en":"Papi didn't use to talk, but now he never stops!","tr":"Papi eskiden konuşmazdı ama şimdi hiç susmuyor!"},{"en":"Did you use to watch cartoons in the morning?","tr":"Eskiden sabahları çizgi film izler miydin?"},{"en":"Did your dad use to play football? Yes, he did.","tr":"Baban eskiden futbol oynar mıydı? Evet, oynardı."},{"en":"There used to be a park near our school.","tr":"Eskiden okulumuzun yakınında bir park vardı."}],"test":[{"tip":"bosluk","soru":"When I was little, I used to ___ milk every night.","tr":"Küçükken her gece süt içerdim.","secenekler":["drinking","drink","drank"],"dogru":1,"aciklama":"Used to'dan sonra fiil yalın gelir: used to drink."},{"tip":"secim","soru":"\"I used to play the piano.\" cümlesi ne anlatır?","secenekler":["Eskiden piyano çalardım, artık çalmıyorum.","Şu an piyano çalıyorum.","Yarın piyano çalacağım."],"dogru":0,"aciklama":"Used to, eskiden olan ama artık olmayan alışkanlıkları anlatır."},{"tip":"bosluk","soru":"My brother ___ to have a bike.","tr":"Erkek kardeşimin eskiden bir bisikleti vardı.","secenekler":["use","uses","used"],"dogru":2,"aciklama":"Olumlu cümlede her kişiyle used to yazılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We","used","to","live","in","Bursa"],"cevap":"We used to live in Bursa.","tr":"Eskiden Bursa'da yaşardık.","aciklama":"Kalıp: kişi + used to + yalın fiil."},{"tip":"secim","soru":"Hangi olumsuz cümle doğru?","secenekler":["I didn't used to eat fish.","I didn't use to eat fish.","I not used to eat fish."],"dogru":1,"aciklama":"Didn't'ten sonra used'ın d'si düşer: didn't use to."},{"tip":"bosluk","soru":"___ you use to play games with your dad?","tr":"Eskiden babanla oyun oynar mıydın?","secenekler":["Did","Do","Were"],"dogru":0,"aciklama":"Used to ile soru Did ile kurulur: Did you use to ...?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["My","grandpa","used","to","go","fishing"],"cevap":"My grandpa used to go fishing.","tr":"Dedem eskiden balığa giderdi.","aciklama":"Eski alışkanlık: kişi + used to + yalın fiil."},{"tip":"secim","soru":"\"Eskiden gözlük takardım.\" cümlesinin İngilizcesi hangisi?","secenekler":["I use to wear glasses.","I was used to wear glasses.","I used to wear glasses."],"dogru":2,"aciklama":"Eski alışkanlık için used to + yalın fiil: I used to wear glasses."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Did","Zeynep","use","to","have","a","cat"],"cevap":"Did Zeynep use to have a cat?","tr":"Zeynep'in eskiden bir kedisi var mıydı?","aciklama":"Soru: Did + kişi + use to + yalın fiil?"},{"tip":"dogruyanlis","soru":"\"Used to\" bugünkü alışkanlıklarımızı anlatmak için kullanılır.","dogru":false,"aciklama":"Yanlış. Used to eskiden olan ama artık olmayan şeyleri anlatır."}],"kelimeSozlugu":{"used to":{"tr":"eskiden ...-ardı, -erdi","alt":"artık olmayan alışkanlık"},"use to":{"tr":"eskiden ...-ardı","alt":"did / didn't ile"},"habit":{"tr":"alışkanlık","alt":""},"anymore":{"tr":"artık","alt":"olumsuz cümlelerde"},"now":{"tr":"şimdi","alt":""}}}$dm$::jsonb where id = 'ab3beb10-5edd-4b8b-abf0-32916d750144' and topic_name = 'Used to — Geçmişteki Alışkanlıklar';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p><b>will</b> ve <b>won't</b> ile o an verdiğin kararları, yardım tekliflerini, verdiğin sözleri ve gelecekle ilgili tahminlerini söylemeyi öğreneceksin.</p><h3>Kalıp: will + fiilin yalın hali</h3><p><b>will</b> bütün kişilerde aynıdır, -s almaz ve kendinden sonra <b>to</b> gelmez.</p><table><tr><th></th><th>Kalıp</th><th>Örnek</th></tr><tr><td>Olumlu</td><td>kişi + <b>will</b> ('ll) + fiil</td><td><i>I'll help you.</i> = Sana yardım edeceğim.</td></tr><tr><td>Olumsuz</td><td>kişi + <b>won't</b> (will not) + fiil</td><td><i>I won't tell anyone.</i> = Kimseye söylemeyeceğim.</td></tr><tr><td>Soru</td><td><b>Will</b> + kişi + fiil?</td><td><i>Will you help me?</i> = Bana yardım eder misin?</td></tr></table><p>Kısa cevaplar: <i>Yes, I will. / No, I won't.</i> Konuşmada genelde kısa hali kullanılır: I'll, you'll, she'll, we'll.</p><h3>will'i ne zaman kullanırız?</h3><ul><li><b>Anlık karar:</b> Kararı konuşurken veriyorsun. <i>It's cold in here. I'll close the window.</i> = Burası soğuk. Pencereyi kapatayım.</li><li><b>Teklif:</b> Birine yardım etmeyi önerirken. <i>Your bag looks heavy. I'll carry it for you.</i></li><li><b>Söz (promise):</b> <i>I promise I'll clean my room.</i> = Söz veriyorum, odamı toplayacağım.</li><li><b>Rica:</b> <i>Will you open the door, please?</i></li><li><b>Tahmin:</b> Düşündüğün, inandığın şeyler. Genelde <b>I think</b> (bence), <b>probably</b> (muhtemelen) ile gelir. <i>I think it will be sunny tomorrow.</i> Olumsuz tahmin için çoğunlukla <i>I don't think ... will</i> deriz: <i>I don't think Can will come.</i></li></ul><h3>will mi, going to mı?</h3><table><tr><th>will</th><th>going to</th></tr><tr><td>Karar <b>şimdi</b>, konuşurken verildi.</td><td>Karar <b>önceden</b> verildi, bu bir plan.</td></tr><tr><td><i>— We haven't got any milk. — I'll buy some.</i></td><td><i>I'm going to buy milk after school.</i></td></tr><tr><td>Fikre dayalı tahmin: <i>I think robots will help us.</i></td><td>Gördüğüne dayalı tahmin: <i>Look! It's going to rain.</i></td></tr></table><h3>Dikkat!</h3><ul><li>will'den sonra to gelmez: <i>I will to help you.</i> → <i>I will help you.</i></li><li>will ve fiil -s almaz: <i>She wills go.</i> / <i>She will goes.</i> → <i>She will go.</i></li><li>Olumsuz won't'tur, don't değil: <i>I don't will come.</i> → <i>I won't come.</i></li><li>Anlık kararda going to değil will: telefon çalıyor → <i>I'll answer it!</i></li></ul><h3>Kısaca</h3><p>O an verdiğin kararlar, teklifler, sözler ve tahminler için <b>will + fiil</b>, olumsuzu için <b>won't + fiil</b> kullan. Önceden yaptığın planlar için ise going to daha doğrudur.</p>","ornekler":[{"en":"It's cold in here. I'll close the window.","tr":"Burası soğuk. Pencereyi kapatayım."},{"en":"Your bag looks heavy. I'll carry it for you.","tr":"Çantan ağır görünüyor. Senin için taşıyayım."},{"en":"Don't worry, I won't tell anyone your secret.","tr":"Merak etme, sırrını kimseye söylemeyeceğim."},{"en":"I think it will be sunny tomorrow.","tr":"Bence yarın hava güneşli olacak."},{"en":"Robots will help us at home in the future.","tr":"Gelecekte robotlar evde bize yardım edecek."},{"en":"Elif will probably win the race.","tr":"Elif muhtemelen yarışı kazanacak."},{"en":"I promise I'll clean my room after lunch.","tr":"Söz veriyorum, öğle yemeğinden sonra odamı toplayacağım."},{"en":"Will you help me with my homework?","tr":"Ödevime yardım eder misin?"},{"en":"Which bag do you want? I'll take the blue one.","tr":"Hangi çantayı istiyorsun? Mavi olanı alayım."},{"en":"I don't think Can will come to the party.","tr":"Can'ın partiye geleceğini sanmıyorum."}],"test":[{"tip":"bosluk","soru":"I ___ help you with your bag.","tr":"Çantana yardım edeceğim.","secenekler":["will","am","going"],"dogru":0,"aciklama":"Teklif için will + yalın fiil kullanılır: I will help you."},{"tip":"secim","soru":"\"won't\" neyin kısa halidir?","secenekler":["want not","will not","would not"],"dogru":1,"aciklama":"Won't = will not. Want (istemek) ile karıştırma."},{"tip":"bosluk","soru":"I think it ___ snow tomorrow.","tr":"Bence yarın kar yağacak.","secenekler":["is","wills","will"],"dogru":2,"aciklama":"I think ile yapılan tahminlerde will + yalın fiil kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I'll","carry","it","for","you"],"cevap":"I'll carry it for you.","tr":"Senin için taşıyayım.","aciklama":"Teklif: I'll (I will) + yalın fiil."},{"tip":"secim","soru":"Telefon çalıyor ve sen o an karar veriyorsun. Ne dersin?","secenekler":["I answer it.","I'll answer it.","I'm going answer it."],"dogru":1,"aciklama":"Konuşurken verilen anlık kararlar için will kullanılır: I'll answer it."},{"tip":"bosluk","soru":"Ece ___ come to the cinema. She is ill.","tr":"Ece sinemaya gelmeyecek. Hasta.","secenekler":["doesn't will","will not to","won't"],"dogru":2,"aciklama":"Will'in olumsuzu won't'tur ve ardından fiil yalın gelir."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Who","will","help","me","with","my","homework"],"cevap":"Who will help me with my homework?","tr":"Ödevime kim yardım edecek?","aciklama":"Who özne olduğu için: Who + will + yalın fiil ...?"},{"tip":"secim","soru":"\"Will Mert come to the party?\" sorusuna doğru olumsuz cevap hangisi?","secenekler":["No, he won't.","No, he doesn't.","No, he willn't."],"dogru":0,"aciklama":"Will ile sorulan soruya won't ile cevap verilir: No, he won't."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","don't","think","our","team","will","win"],"cevap":"I don't think our team will win.","tr":"Takımımızın kazanacağını sanmıyorum.","aciklama":"Olumsuz tahmin: I don't think + kişi + will + yalın fiil."},{"tip":"dogruyanlis","soru":"\"She will goes to the park.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Will'den sonra fiil yalın gelir: She will go to the park."}],"kelimeSozlugu":{"will":{"tr":"-acak, -ecek","alt":"karar, teklif, söz, tahmin"},"won't":{"tr":"-mayacak, -meyecek","alt":"will not"},"probably":{"tr":"muhtemelen","alt":""},"promise":{"tr":"söz vermek","alt":"I promise = söz veriyorum"},"future":{"tr":"gelecek","alt":"in the future = gelecekte"},"think":{"tr":"düşünmek","alt":"I think = bence"}}}$dm$::jsonb where id = '7310ea21-d8c4-400f-9742-6911837a9c80' and topic_name = 'Will / won''t (predictions, offers, decisions) — Anlık Kararlar, Tahminler ve Teklifler';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>İngilizler ve Amerikalılar hızlı konuşurken bazı kelimeleri birleştirir. Filmlerde, şarkılarda ve oyunlarda duyduğun <b>gonna, wanna, gotta</b> gibi kelimelerin ne demek olduğunu anlayacak ve kelimelerin nasıl birbirine bağlandığını öğreneceksin.</p><h3>Birleşen kelimeler</h3><table><tr><th>Uzun hali</th><th>Konuşmada</th><th>Okunuşu</th><th>Anlamı</th></tr><tr><td><b>going to</b></td><td>gonna</td><td>ganı</td><td>-ecek, -acak</td></tr><tr><td><b>want to</b></td><td>wanna</td><td>uanı</td><td>-mek istemek</td></tr><tr><td><b>have got to</b></td><td>gotta</td><td>gatı</td><td>-meli, zorunda olmak</td></tr><tr><td><b>let me</b></td><td>lemme</td><td>lemi</td><td>izin ver, ben ...eyim</td></tr><tr><td><b>give me</b></td><td>gimme</td><td>gimi</td><td>bana ver</td></tr><tr><td><b>kind of</b></td><td>kinda</td><td>kaındı</td><td>biraz, bir tür</td></tr></table><p>Örnek: <i>I'm gonna play.</i> = <i>I'm going to play.</i> (Oynayacağım.) <i>Do you wanna come?</i> = <i>Do you want to come?</i> (Gelmek ister misin?)</p><h3>Ne zaman kullanılır?</h3><ul><li>Bunlar <b>konuşma dilidir</b>. Arkadaşlarınla konuşurken duyarsın ve kullanabilirsin.</li><li>Okul ödevinde, sınavda ve e-postada <b>uzun halini</b> yaz: <i>I want to be a vet.</i></li><li><b>gonna</b> sadece bir fiilden önce gelir: <i>I'm gonna eat.</i> Ama bir yere gitmek için kullanılmaz: <i>I'm going to school.</i></li></ul><h3>Kelimeler birbirine yapışır</h3><p>Bir kelime sessiz harfle bitip sonraki kelime sesli harfle başlıyorsa, ikisi tek kelime gibi söylenir:</p><ul><li><i>pick it up</i> → “pikitap” (yerden al)</li><li><i>turn it off</i> → “törnitof” (kapat)</li><li><i>an apple</i> → “ınepıl” (bir elma)</li></ul><p>Dinlerken bu birleşmeleri tanırsan, hızlı konuşmayı da çok daha kolay anlarsın.</p><h3>Dikkat!</h3><ul><li>Bir yere gitmekte gonna olmaz: <i>I'm gonna school.</i> → <i>I'm going to school.</i></li><li>wanna sadece want to demektir: <i>He wanna play.</i> → <i>He wants to play.</i></li><li>wanna'dan sonra ayrıca to gelmez: <i>I wanna to eat.</i> → <i>I wanna eat.</i></li><li>Yazılı ödevde kısa hali kullanma: <i>I'm gonna study.</i> → <i>I'm going to study.</i></li></ul><h3>Kısaca</h3><p>Hızlı konuşmada going to “gonna”, want to “wanna”, have got to “gotta” olur ve kelimeler birbirine bağlanır. Bunları konuşmada kullanabilirsin ama yazarken her zaman uzun halini yaz.</p>","ornekler":[{"en":"I'm gonna visit my grandma on Sunday.","tr":"Pazar günü anneanneme gideceğim. (gonna = going to)"},{"en":"Do you wanna play a game?","tr":"Bir oyun oynamak ister misin? (wanna = want to)"},{"en":"I gotta go home now.","tr":"Şimdi eve gitmem lazım. (gotta = have got to)"},{"en":"What are you gonna do tomorrow?","tr":"Yarın ne yapacaksın?"},{"en":"Lemme help you with that bag.","tr":"Şu çantayı taşımana yardım edeyim. (lemme = let me)"},{"en":"Gimme a minute, please.","tr":"Bana bir dakika ver lütfen. (gimme = give me)"},{"en":"I wanna eat a hamburger.","tr":"Bir hamburger yemek istiyorum."},{"en":"It's kinda cold today.","tr":"Bugün hava biraz soğuk. (kinda = kind of)"},{"en":"Pick it up, Ali!","tr":"Onu yerden al, Ali! (Birleşik okunur: pikitap)"},{"en":"Turn it off, please.","tr":"Onu kapat lütfen. (Birleşik okunur: törnitof)"}],"test":[{"tip":"secim","soru":"\"gonna\" hangi ifadenin konuşmadaki kısa halidir?","secenekler":["going to","go now","got to"],"dogru":0,"aciklama":"gonna = going to. I'm gonna play = I'm going to play."},{"tip":"secim","soru":"\"wanna\" neyin kısa halidir?","secenekler":["going to","want to","what do"],"dogru":1,"aciklama":"wanna = want to. Do you wanna come? = Do you want to come?"},{"tip":"bosluk","soru":"I'm ___ watch a film tonight.","tr":"Bu akşam film izleyeceğim.","secenekler":["wanna","gotta","gonna"],"dogru":2,"aciklama":"-ecek, -acak anlamı going to'dur; konuşmada gonna olur: I'm gonna watch."},{"tip":"bosluk","soru":"Do you ___ come to my party?","tr":"Partime gelmek ister misin?","secenekler":["gonna","wanna","gimme"],"dogru":1,"aciklama":"İstemek anlamı want to'dur; konuşmada wanna olur."},{"tip":"dogruyanlis","soru":"\"I'm gonna school.\" doğru bir cümledir.","dogru":false,"aciklama":"gonna sadece fiilden önce gelir. Doğrusu: I'm going to school."},{"tip":"secim","soru":"\"Lemme help you.\" cümlesinin uzun hali hangisi?","secenekler":["Let me help you.","Lend me help you.","Leave me help you."],"dogru":0,"aciklama":"lemme = let me. Let me help you = Sana yardım edeyim."},{"tip":"secim","soru":"\"He wanna play.\" yanlış. Doğrusu hangisi?","secenekler":["He wannas play.","He wants to play.","He want to play."],"dogru":1,"aciklama":"wanna sadece want to yerine geçer. He ile wants to kullanılır."},{"tip":"bosluk","soru":"It's late. I ___ go home now.","tr":"Geç oldu. Şimdi eve gitmem lazım.","secenekler":["gonna","gotta","lemme"],"dogru":1,"aciklama":"Zorunda olmak have got to'dur; konuşmada gotta olur."},{"tip":"secim","soru":"Okul ödevine yazarken hangisi doğrudur?","secenekler":["I wanna be a doctor.","I wanna to be a doctor.","I want to be a doctor."],"dogru":2,"aciklama":"Yazarken uzun hali kullanılır: I want to be a doctor."},{"tip":"secim","soru":"\"Pick it up\" hızlı konuşmada nasıl duyulur?","secenekler":["pik - it - ap, ayrı ayrı","pi - ap","pikitap"],"dogru":2,"aciklama":"Sessiz harfle biten kelime sonraki sesli harfe yapışır: pikitap."}],"kelimeSozlugu":{"gonna":{"tr":"-ecek, -acak","alt":"going to"},"wanna":{"tr":"-mek istemek","alt":"want to"},"gotta":{"tr":"-meli, zorunda olmak","alt":"have got to"},"lemme":{"tr":"izin ver, ben ...eyim","alt":"let me"},"gimme":{"tr":"bana ver","alt":"give me"},"kinda":{"tr":"biraz","alt":"kind of"},"pick it up":{"tr":"onu yerden al","alt":"pikitap"}}}$dm$::jsonb where id = '3514425f-3438-4ef4-bb24-450c97355f1c' and topic_name = 'Connected speech (e.g. going to → gonna) — Bağlantılı Konuşma (Gonna, Wanna vb.)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Cümlenin sonunda sesinin ne zaman <b>düştüğünü</b> (↘) ve ne zaman <b>yükseldiğini</b> (↗) öğreneceksin. Sesin bu inip çıkmasına İngilizcede <b>intonation</b> denir. Doğru tonlama yaparsan dinleyen, soru mu sorduğunu yoksa bir şey mi anlattığını hemen anlar.</p><h3>Ses düşer ↘</h3><p>Cümlenin son vurgulu kelimesinde ses aşağı iner:</p><ul><li><b>Düz cümleler</b> (statement): <i>My name is Elif. ↘</i></li><li><b>Wh soruları</b> (what, where, who, when, why, how ile başlayan sorular): <i>Where do you live? ↘</i> <i>What time is it? ↘</i></li><li><b>Emir ve istek cümleleri</b>: <i>Close the door, please. ↘</i></li></ul><h3>Ses yükselir ↗</h3><p>Cevabı evet ya da hayır olan sorularda (yes/no question) ses sonda yukarı çıkar. Bu sorular <b>Are, Is, Do, Does, Can</b> gibi kelimelerle başlar:</p><ul><li><i>Are you ready? ↗</i> (Hazır mısın?)</li><li><i>Do you like chocolate? ↗</i> (Çikolata sever misin?)</li><li><i>Can you help me? ↗</i> (Bana yardım eder misin?)</li></ul><p>Şaşırınca ya da duymadığın bir şeyi tekrar isterken de ses yükselir: <i>Really? ↗</i> <i>Sorry? ↗</i></p><h3>Liste söylerken</h3><p>Birkaç şeyi sayarken her birinde ses biraz yükselir, sonuncusunda düşer. Böylece dinleyen listenin bittiğini anlar:</p><p><i>I like apples ↗, bananas ↗ and grapes. ↘</i></p><table><tr><th>Cümle türü</th><th>Örnek</th><th>Ses</th></tr><tr><td>Düz cümle</td><td><i>It is raining.</i></td><td>düşer ↘</td></tr><tr><td>Wh sorusu</td><td><i>Who is your teacher?</i></td><td>düşer ↘</td></tr><tr><td>Evet/hayır sorusu</td><td><i>Is she your teacher?</i></td><td>yükselir ↗</td></tr><tr><td>Şaşırma</td><td><i>Really?</i></td><td>yükselir ↗</td></tr></table><h3>Dikkat!</h3><ul><li>Her soruda sesi yükseltme: <i>Where do you live? ↗</i> → <i>Where do you live? ↘</i></li><li>Türkçede soruyu mı, mi ekinden anlarız; İngilizcede evet/hayır sorusunda ses mutlaka yükselir: <i>Are you hungry? ↗</i></li><li>Düz cümlenin sonunu yükseltirsen soru gibi duyulur: <i>You're coming. ↗</i> “Geliyor musun?” anlamına gelir.</li></ul><h3>Kısaca</h3><p>Düz cümlelerde ve wh sorularında ses sonda düşer, evet/hayır sorularında yükselir. Liste sayarken her öğede ses yükselir, en sonda düşer.</p>","ornekler":[{"en":"My name is Elif.","tr":"Benim adım Elif. (Ses sonda düşer.)"},{"en":"Are you ready?","tr":"Hazır mısın? (Ses sonda yükselir.)"},{"en":"Where do you live?","tr":"Nerede yaşıyorsun? (Wh sorusu: ses düşer.)"},{"en":"Do you like chocolate?","tr":"Çikolata sever misin? (Ses yükselir.)"},{"en":"What time is it?","tr":"Saat kaç? (Ses düşer.)"},{"en":"Can you help me, please?","tr":"Bana yardım eder misin lütfen? (Ses yükselir.)"},{"en":"I like apples, bananas and grapes.","tr":"Elma, muz ve üzüm severim. (Her meyvede yükselir, sonda düşer.)"},{"en":"Close the door, please.","tr":"Kapıyı kapat lütfen. (Ses düşer.)"},{"en":"— I've got a new puppy. — Really?","tr":"— Yeni bir yavru köpeğim var. — Gerçekten mi? (Really sonda yükselir.)"},{"en":"Is Papi hungry?","tr":"Papi aç mı? (Ses yükselir.)"}],"test":[{"tip":"secim","soru":"\"Are you ten?\" sorusunun sonunda ses ne yapar?","secenekler":["Yükselir","Düşer","Hiç değişmez"],"dogru":0,"aciklama":"Cevabı evet ya da hayır olan sorularda ses sonda yükselir."},{"tip":"secim","soru":"\"Where is my bag?\" sorusunun sonunda ses ne yapar?","secenekler":["Yükselir","Düşer","Önce düşer, sonra yükselir"],"dogru":1,"aciklama":"Where gibi wh kelimeleriyle başlayan sorularda ses sonda düşer."},{"tip":"dogruyanlis","soru":"İngilizcede bütün soruların sonunda ses yükselir.","dogru":false,"aciklama":"Hayır! Wh sorularında (Where, What, Who...) ses düşer."},{"tip":"secim","soru":"Hangi soruda ses sonda düşer?","secenekler":["Do you like cats?","Can you swim?","What is your name?"],"dogru":2,"aciklama":"What is your name? bir wh sorusudur; ses düşer. Diğerleri evet/hayır sorusudur."},{"tip":"secim","soru":"Hangi soruda ses sonda yükselir?","secenekler":["Who is your teacher?","Is she your teacher?","Where is your teacher?"],"dogru":1,"aciklama":"Is she...? evet/hayır sorusudur; ses yükselir."},{"tip":"bosluk","soru":"___ you like pizza?","tr":"Pizza sever misin? (Ses sonda yükselir.)","secenekler":["Do","What","Where"],"dogru":0,"aciklama":"Ses yükseliyorsa evet/hayır sorusudur: Do you like pizza?"},{"tip":"bosluk","soru":"___ do you go to school?","tr":"Okula nasıl gidersin? (Ses sonda düşer.)","secenekler":["Do","Are","How"],"dogru":2,"aciklama":"Ses düşüyorsa wh sorusudur: How do you go to school?"},{"tip":"secim","soru":"Arkadaşın bir şey söyledi ama duymadın. \"Sorry?\" derken sesin ne yapar?","secenekler":["Düşer, çünkü özür diliyorsun","Yükselir, çünkü tekrar söylemesini istiyorsun","Düz kalır, çünkü tek kelime"],"dogru":1,"aciklama":"Tekrar isterken Sorry? sonda yükselir. Özür dilerken Sorry. düşer."},{"tip":"dogruyanlis","soru":"\"I like apples, bananas and grapes.\" cümlesinde ses en sonda düşer.","dogru":true,"aciklama":"Doğru! Listede her öğede ses yükselir, son öğede düşer."},{"tip":"secim","soru":"\"You're coming.\" cümlesini sonu yükselerek söylersen ne olur?","secenekler":["Soru gibi duyulur: Geliyor musun?","Emir cümlesi olur: Gel!","Hiçbir şey değişmez"],"dogru":0,"aciklama":"Yükselen ton cümleyi soruya çevirir: You're coming? = Geliyor musun?"}],"kelimeSozlugu":{"intonation":{"tr":"tonlama","alt":"sesin inip çıkması"},"statement":{"tr":"düz cümle","alt":""},"question":{"tr":"soru","alt":""},"really":{"tr":"gerçekten mi","alt":"şaşırınca, ses yükselir"},"ready":{"tr":"hazır","alt":""}}}$dm$::jsonb where id = 'c371eee9-eab4-4831-a54b-19c5d70f4f0a' and topic_name = 'Intonation in statements and questions — Düz Cümle ve Sorularda Tonlama';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Geçmiş zamanda fiillere eklenen <b>-ed</b> ekinin üç farklı okunuşunu öğreneceksin: <b>t</b>, <b>d</b> ve <b>ıd</b>. Böylece <i>walked, played, wanted</i> gibi kelimeleri doğru söyleyebileceksin.</p><h3>Üç okunuş</h3><table><tr><th>Okunuş</th><th>Ne zaman?</th><th>Örnekler</th></tr><tr><td><b>t</b></td><td>Fiil p, k, s, ş, ç, f sesiyle bitiyorsa</td><td>walked (uokt), stopped (stopt), watched (uoçt), washed (uoşt), laughed (laft)</td></tr><tr><td><b>d</b></td><td>Fiil sesli harfle ya da b, g, l, m, n, v, z gibi seslerle bitiyorsa</td><td>played (pleyd), cleaned (klind), lived (livd), called (kold), opened (oupınd)</td></tr><tr><td><b>ıd</b></td><td>Fiil t ya da d sesiyle bitiyorsa</td><td>wanted (uontıd), needed (nidıd), visited (vizitıd), painted (peyntıd)</td></tr></table><h3>Harfe değil, sese bak</h3><p>Kurala bakarken fiilin son <b>harfine</b> değil, son <b>sesine</b> bak. Örneğin <i>laugh</i> gh ile yazılır ama f sesiyle biter, bu yüzden <i>laughed</i> “laft” okunur. <i>dance</i> e ile yazılır ama s sesiyle biter, bu yüzden <i>danced</i> “danst” okunur.</p><p>Küçük bir deney: elini boğazına koy ve uzun bir “sss” söyle. Titreşim yok, değil mi? Şimdi “zzz” söyle. Boğazın titriyor! Titreşimsiz seslerden (p, k, s, ş, ç, f) sonra -ed <b>t</b>, titreşimli seslerden sonra <b>d</b> gibi okunur.</p><h3>Hece sayısı</h3><p>Sadece <b>ıd</b> okunuşu kelimeye yeni bir hece ekler: <i>want</i> (1 hece) → <i>wan-ted</i> (2 hece). Diğerlerinde hece sayısı değişmez: <i>walk</i> → <i>walked</i>, ikisi de tek hecedir.</p><h3>Dikkat!</h3><ul><li>-ed'i her zaman “ed” diye okuma: <i>uok-ked</i> → <i>uokt</i></li><li>played iki hece değildir: <i>pley-ed</i> → <i>pleyd</i></li><li>t ve d ile biten fiillerde “ıd” sesini unutma: <i>uont</i> → <i>uontıd</i> (wanted)</li><li>Son harfe aldanma: <i>danced</i> “dansıd” değil, “danst” okunur.</li></ul><h3>Kısaca</h3><p>-ed eki t, d ya da ıd diye okunur; fiilin son sesine bak. Sadece t ve d ile biten fiillerde -ed yeni bir hece olur.</p>","ornekler":[{"en":"Ali walked to school yesterday.","tr":"Ali dün okula yürüdü. (walked: uokt)"},{"en":"We played football after school.","tr":"Okuldan sonra futbol oynadık. (played: pleyd)"},{"en":"Zeynep wanted a glass of water.","tr":"Zeynep bir bardak su istedi. (wanted: uontıd)"},{"en":"They watched a funny film last night.","tr":"Dün gece komik bir film izlediler. (watched: uoçt)"},{"en":"I cleaned my room this morning.","tr":"Bu sabah odamı temizledim. (cleaned: klind)"},{"en":"Mert needed some help with his homework.","tr":"Mert'in ödevi için biraz yardıma ihtiyacı vardı. (needed: nidıd)"},{"en":"The dog jumped over the fence.","tr":"Köpek çitin üzerinden atladı. (jumped: campt)"},{"en":"We visited our grandparents last summer.","tr":"Geçen yaz büyükannemle büyükbabamı ziyaret ettik. (visited: vizitıd)"},{"en":"Papi opened his wings.","tr":"Papi kanatlarını açtı. (opened: oupınd)"},{"en":"Elif laughed at my joke.","tr":"Elif şakama güldü. (laughed: laft)"}],"test":[{"tip":"secim","soru":"\"played\" kelimesinin sonu nasıl okunur?","secenekler":["t sesi","d sesi","ıd sesi"],"dogru":1,"aciklama":"play sesli bir sesle biter, bu yüzden -ed d okunur: pleyd."},{"tip":"secim","soru":"\"walked\" kelimesi nasıl okunur?","secenekler":["uokt","uok-ked","uok-ıd"],"dogru":0,"aciklama":"walk k sesiyle biter; -ed t okunur ve hece eklenmez: uokt."},{"tip":"secim","soru":"\"wanted\" kaç hecedir?","secenekler":["Bir hece","İki hece","Üç hece"],"dogru":1,"aciklama":"want t ile biter; -ed ıd okunur ve yeni hece olur: wan-ted."},{"tip":"dogruyanlis","soru":"-ed eki her zaman ayrı bir hece olarak \"ed\" diye okunur.","dogru":false,"aciklama":"Hayır! Sadece t ve d ile biten fiillerde ıd diye ayrı hece olur."},{"tip":"secim","soru":"Hangi kelimenin sonu \"ıd\" diye okunur?","secenekler":["cleaned","watched","needed"],"dogru":2,"aciklama":"need d ile biter, bu yüzden needed: nidıd."},{"tip":"bosluk","soru":"The word watched ends with a ___ sound.","tr":"Watched kelimesinin sonundaki sesi seç.","secenekler":["d","ıd","t"],"dogru":2,"aciklama":"watch ç sesiyle biter; ç titreşimsizdir, -ed t okunur: uoçt."},{"tip":"bosluk","soru":"The word lived ends with a ___ sound.","tr":"Lived kelimesinin sonundaki sesi seç.","secenekler":["t","d","ıd"],"dogru":1,"aciklama":"live v sesiyle biter; v titreşimlidir, -ed d okunur: livd."},{"tip":"dogruyanlis","soru":"\"danced\" kelimesinde -ed'den önceki ses s olduğu için sonu t diye okunur.","dogru":true,"aciklama":"Doğru! dance e ile yazılır ama s sesiyle biter: danst."},{"tip":"secim","soru":"Hangi grupta bütün kelimelerin sonu t diye okunur?","secenekler":["walked, stopped, laughed","played, opened, lived","wanted, needed, painted"],"dogru":0,"aciklama":"k, p ve f titreşimsiz seslerdir; bu fiillerde -ed t okunur."},{"tip":"secim","soru":"\"visited\" kelimesi nasıl okunur?","secenekler":["vizitt","vizitıd","vizit"],"dogru":1,"aciklama":"visit t ile biter, bu yüzden -ed ıd okunur: vizitıd."}],"kelimeSozlugu":{"walked":{"tr":"yürüdü","alt":"uokt"},"played":{"tr":"oynadı","alt":"pleyd"},"wanted":{"tr":"istedi","alt":"uontıd"},"watched":{"tr":"izledi","alt":"uoçt"},"cleaned":{"tr":"temizledi","alt":"klind"},"needed":{"tr":"ihtiyacı vardı","alt":"nidıd"},"laughed":{"tr":"güldü","alt":"laft"}}}$dm$::jsonb where id = 'dd4cd20b-0449-4058-9e76-c1c9f1d06529' and topic_name = 'Pronunciation of -ed endings — -Ed Takısının Telaffuzu';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>İngilizce kelimelerde hangi hecenin daha güçlü söylendiğini ve bir cümlede hangi kelimelerin öne çıktığını öğreneceksin. Bu vurguya İngilizcede <b>stress</b> denir. Doğru vurgu yaparsan seni çok daha kolay anlarlar.</p><h3>Kelime vurgusu: bir hece daha güçlü</h3><p>Birden fazla heceli (syllable) kelimelerde bir hece daha <b>yüksek, uzun ve güçlü</b> söylenir. Aşağıda vurgulu heceyi BÜYÜK harfle yazdık. Türkçede vurgu çoğu kelimede sondadır ama İngilizcede her kelimenin kendi vurgusu vardır, onu kelimeyle birlikte öğrenmelisin.</p><table><tr><th>Kelime</th><th>Vurgu</th><th>Okunuşu</th></tr><tr><td>teacher</td><td>TEA-cher</td><td>Tİ-çır</td></tr><tr><td>pencil</td><td>PEN-cil</td><td>PEN-sıl</td></tr><tr><td>banana</td><td>ba-NA-na</td><td>bı-NA-nı</td></tr><tr><td>computer</td><td>com-PU-ter</td><td>kım-PYU-tır</td></tr><tr><td>hotel</td><td>ho-TEL</td><td>hou-TEL</td></tr><tr><td>elephant</td><td>EL-e-phant</td><td>E-lı-fınt</td></tr></table><p>Küçük bir ipucu: iki heceli isim ve sıfatların çoğunda vurgu <b>ilk hecede</b>dir (<i>HAPpy, MONkey, TAble</i>). İki heceli fiillerin çoğunda ise <b>ikinci hecede</b>dir (<i>beGIN, forGET, reLAX</i>). Vurgusuz heceler kısa ve hafif söylenir, çoğu zaman “ı” gibi duyulur.</p><h3>Kelime ailesi, vurgu yer değiştirir</h3><p>Aynı aileden kelimelerde vurgu kayabilir:</p><ul><li><b>PHO</b>tograph (FOU-tı-graf) = fotoğraf</li><li>pho<b>TO</b>grapher (fı-TO-grı-fır) = fotoğrafçı</li><li>pho<b>TO</b>graphy (fı-TO-grı-fi) = fotoğrafçılık</li></ul><h3>Cümle vurgusu: önemli kelimeler güçlü</h3><p>Cümlede anlamı taşıyan kelimeler <b>güçlü</b> söylenir: isimler, fiiller, sıfatlar, soru kelimeleri ve olumsuz kelimeler (<i>not, don't, can't</i>). <b>a, the, to, of, and, is, are</b> gibi küçük kelimeler ise hızlı ve hafif söylenir.</p><ul><li><i>I WANT to BUY a NEW BIKE.</i></li><li><i>WHERE do you LIVE?</i></li><li><i>I can SWIM.</i> Burada can hafif söylenir: “ay kın SUİM”.</li><li><i>I CAN'T swim.</i> Olumsuz can't güçlü ve uzun söylenir. Böylece dinleyen farkı anlar.</li></ul><p>Bir kelimeyi özellikle güçlü söylersen “başkası değil, bu” demiş olursun: <i>I want a BLUE pen, not a red one.</i> (Kırmızı değil, mavi.)</p><h3>Dikkat!</h3><ul><li>Türkçedeki gibi sonu vurgulama: <i>kompüTER</i> → <i>kım-PYU-tır</i></li><li>teacher ilk heceden vurgulanır: <i>tiÇIR</i> → <i>Tİ-çır</i></li><li>Küçük kelimeleri tek tek güçlü söyleme: <i>AY UANT TU BAY E BAYK</i> → <i>I WANT to BUY a BIKE</i></li><li>can ile can't karışmasın: olumlu can hafif, olumsuz can't güçlüdür.</li></ul><h3>Kısaca</h3><p>Her İngilizce kelimenin bir vurgulu hecesi vardır; kelimeyi öğrenirken vurgusunu da öğren. Cümlede ise anlam taşıyan kelimeler güçlü, a, the, to gibi küçük kelimeler hafif söylenir.</p>","ornekler":[{"en":"My teacher has a new computer.","tr":"Öğretmenimin yeni bir bilgisayarı var. (Vurgu: TEAcher, comPUter)"},{"en":"I'd like a banana, please.","tr":"Bir muz istiyorum lütfen. (Vurgu: baNAna)"},{"en":"Look at this photograph of Papi!","tr":"Papi'nin şu fotoğrafına bak! (Vurgu: PHOtograph)"},{"en":"Ali wants to be a photographer.","tr":"Ali fotoğrafçı olmak istiyor. (Vurgu: phoTOgrapher)"},{"en":"Mert plays football on Sundays.","tr":"Mert pazar günleri futbol oynar. (Güçlü: MERT, PLAYS, FOOTball, SUNdays)"},{"en":"Where do you live?","tr":"Nerede yaşıyorsun? (Güçlü: WHERE, LIVE)"},{"en":"I can swim, but I can't dive.","tr":"Yüzebilirim ama dalamam. (can hafif, can't güçlü)"},{"en":"I want a blue pen, not a red one.","tr":"Kırmızı değil, mavi bir kalem istiyorum. (Güçlü: BLUE, RED)"},{"en":"Don't forget your homework!","tr":"Ödevini unutma! (Güçlü: DON'T, forGET, HOMEwork)"},{"en":"The elephant is eating a banana.","tr":"Fil bir muz yiyor. (Vurgu: ELephant, baNAna)"}],"test":[{"tip":"secim","soru":"\"teacher\" kelimesinde vurgu hangi hecededir?","secenekler":["İlk hece: tea","Son hece: cher","İki hece eşit"],"dogru":0,"aciklama":"teacher ilk heceden vurgulanır: Tİ-çır."},{"tip":"secim","soru":"\"banana\" kelimesinde vurgulu hece hangisi?","secenekler":["İlk hece","Ortadaki hece","Son hece"],"dogru":1,"aciklama":"banana ortadaki heceden vurgulanır: bı-NA-nı."},{"tip":"dogruyanlis","soru":"İngilizcede bütün kelimelerin vurgusu son hecededir.","dogru":false,"aciklama":"Hayır! Her kelimenin vurgusu farklıdır: TEAcher, baNAna, hoTEL."},{"tip":"secim","soru":"\"computer\" kelimesi nasıl okunur?","secenekler":["KOM-pyu-tır","kım-PYU-tır","kım-pyu-TIR"],"dogru":1,"aciklama":"computer ikinci heceden vurgulanır: kım-PYU-tır."},{"tip":"bosluk","soru":"Ali takes great pictures. He is a ___.","tr":"Ali harika fotoğraflar çeker. O bir fotoğrafçı.","secenekler":["photograph","photographer","photography"],"dogru":1,"aciklama":"Fotoğrafçı photographer'dır; vurgu ikinci hecededir: phoTOgrapher."},{"tip":"secim","soru":"Bir cümlede genellikle hangi kelimeler güçlü söylenir?","secenekler":["Sadece ilk kelime","a, the, to gibi küçük kelimeler","İsim, fiil, sıfat gibi anlam taşıyan kelimeler"],"dogru":2,"aciklama":"Anlamı taşıyan kelimeler güçlü, a, the, to gibi küçük kelimeler hafif söylenir."},{"tip":"bosluk","soru":"I love ___. I take pictures every day.","tr":"Fotoğrafçılığı çok seviyorum. Her gün fotoğraf çekiyorum.","secenekler":["photography","photograph","photographer"],"dogru":0,"aciklama":"Fotoğrafçılık photography'dir; vurgusu phoTOgraphy."},{"tip":"secim","soru":"\"I can swim.\" cümlesinde can nasıl söylenir?","secenekler":["Hafif ve kısa, kın gibi","Güçlü ve uzun, can't gibi","Ses yükselerek, soru gibi"],"dogru":0,"aciklama":"Olumlu cümlede can hafif söylenir; güçlü ve uzun söylenen olumsuz can't'tir."},{"tip":"dogruyanlis","soru":"\"present\" (hediye) kelimesinde vurgu ilk hecededir: PREsent.","dogru":true,"aciklama":"Doğru! Hediye anlamındaki present ilk heceden vurgulanır: PRE-zınt."},{"tip":"secim","soru":"Mert \"I want a BLUE pen.\" diyor ve BLUE kelimesini çok güçlü söylüyor. Ne demek istiyor?","secenekler":["Kalem değil, başka bir şey istiyor.","Başka bir renk değil, mavi kalem istiyor.","Kalemi başkası değil, kendisi istiyor."],"dogru":1,"aciklama":"Güçlü söylenen kelime öne çıkar: başka renk değil, MAVİ."}],"kelimeSozlugu":{"stress":{"tr":"vurgu","alt":""},"teacher":{"tr":"öğretmen","alt":"TEA-cher"},"computer":{"tr":"bilgisayar","alt":"com-PU-ter"},"banana":{"tr":"muz","alt":"ba-NA-na"},"photograph":{"tr":"fotoğraf","alt":"PHO-to-graph"},"photographer":{"tr":"fotoğrafçı","alt":"pho-TO-gra-pher"},"elephant":{"tr":"fil","alt":"EL-e-phant"}}}$dm$::jsonb where id = 'ab472ee9-a096-49aa-80c3-36d7cf579002' and topic_name = 'Word stress and sentence stress — Kelime ve Cümle Vurgusu';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir mağazada fiyat sormayı, kıyafet denemeyi, başka beden istemeyi ve ödeme yapmayı İngilizce öğreneceksin. Satıcının sorularına da doğru cevap verebileceksin.</p><h3>Alışveriş kelimeleri</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>shop assistant</b></td><td>satıcı, tezgâhtar</td><td><i>The shop assistant is very nice.</i></td></tr><tr><td><b>customer</b></td><td>müşteri</td><td><i>There are many customers today.</i></td></tr><tr><td><b>price</b></td><td>fiyat</td><td><i>What's the price of this bag?</i></td></tr><tr><td><b>cheap</b></td><td>ucuz</td><td><i>These socks are cheap.</i></td></tr><tr><td><b>expensive</b></td><td>pahalı</td><td><i>That bike is expensive.</i></td></tr><tr><td><b>size</b></td><td>beden, boy</td><td><i>What size are you?</i></td></tr><tr><td><b>on sale</b></td><td>indirimde</td><td><i>This jacket is on sale.</i></td></tr><tr><td><b>cash</b></td><td>nakit para</td><td><i>I can pay in cash.</i></td></tr><tr><td><b>card</b></td><td>kart</td><td><i>Can I pay by card?</i></td></tr><tr><td><b>change</b></td><td>para üstü</td><td><i>Here's your change.</i></td></tr><tr><td><b>receipt</b></td><td>fiş</td><td><i>Can I have the receipt?</i></td></tr><tr><td><b>queue</b></td><td>kuyruk, sıra</td><td><i>The queue is very long.</i></td></tr></table><p>Mağazada sen bir <b>customer</b> (müşteri) olursun, sana yardım eden kişi ise <b>shop assistant</b> olur. <b>Receipt</b> kelimesindeki p okunmaz: “risiit”. <b>Queue</b> ise “kyu” diye okunur.</p><h3>Fiyat sorma</h3><ul><li>Tek bir şey için: <b>How much is this ...?</b> → <b>It's ...</b> <i>How much is this pencil case? It's thirty lira.</i></li><li>Birden fazla şey için: <b>How much are these ...?</b> → <b>They're ...</b> <i>How much are these socks? They're fifteen lira.</i></li><li>Başka bir yol: <b>How much does it cost?</b> (Kaç para tutuyor?)</li></ul><h3>Mağazada mini diyaloglar</h3><ul><li>Satıcı: <i>Can I help you?</i> (Yardım edebilir miyim?) Sen: <i>No, thanks. I'm just looking.</i> (Hayır, teşekkürler. Sadece bakıyorum.)</li><li>Sen: <i>Can I try it on, please?</i> (Deneyebilir miyim?) Satıcı: <i>Sure. The fitting room is over there.</i> (Tabii. Deneme kabini orada.)</li><li>Sen: <i>Do you have this in a smaller size?</i> ya da <i>a bigger size?</i> (Bunun daha küçük / büyük bedeni var mı?)</li><li>Karar verince: <i>I'll take it.</i> (Bunu alıyorum.)</li><li>Ödeme: <i>Can I pay by card?</i> Satıcı: <i>Here's your receipt and your change.</i></li></ul><h3>Dikkat!</h3><ul><li>Fiyat sorarken iki kalıbı karıştırma. Yanlış: <i>How much is it cost?</i> → Doğru: <i>How much is it?</i> ya da <i>How much does it cost?</i></li><li>Para sayılamaz, <b>many</b> değil <b>much</b> kullanılır. Yanlış: <i>How many is it?</i> → Doğru: <i>How much is it?</i></li><li>Çoğul şeyler için <b>these/are</b> kullan. Yanlış: <i>How much is this shoes?</i> → Doğru: <i>How much are these shoes?</i></li><li>Yanlış: <i>I'm only look.</i> → Doğru: <i>I'm just looking.</i></li></ul><h3>Kısaca</h3><p>Fiyat için <b>How much is / are ...?</b>, denemek için <b>Can I try it on?</b>, ödemek için <b>Can I pay by card?</b> dersin. Para üstü <b>change</b>, fiş <b>receipt</b>, indirimde <b>on sale</b> demektir.</p>","ornekler":[{"en":"— How much is this pencil case? — It's thirty lira.","tr":"Bu kalem kutusu ne kadar? Otuz lira."},{"en":"— How much are these socks? — They're fifteen lira.","tr":"Bu çoraplar ne kadar? On beş lira."},{"en":"Can I try this jacket on, please?","tr":"Bu ceketi deneyebilir miyim lütfen?"},{"en":"Do you have this in a smaller size?","tr":"Bunun daha küçük bedeni var mı?"},{"en":"— Can I help you? — No, thanks. I'm just looking.","tr":"Yardım edebilir miyim? Hayır, teşekkürler. Sadece bakıyorum."},{"en":"This football is too expensive. That one is cheaper.","tr":"Bu top çok pahalı. Şu daha ucuz."},{"en":"— Can I pay by card? — Yes, of course.","tr":"Kartla ödeyebilir miyim? Evet, tabii ki."},{"en":"Here is your receipt and your change.","tr":"Buyurun fişiniz ve para üstünüz."},{"en":"Ece bought a cool backpack. It was on sale!","tr":"Ece harika bir sırt çantası aldı. İndirimdeydi!"},{"en":"There is a long queue at the checkout today.","tr":"Bugün kasada uzun bir kuyruk var."}],"test":[{"tip":"secim","soru":"\"Ucuz\" kelimesinin İngilizcesi hangisi?","secenekler":["expensive","cheap","change"],"dogru":1,"aciklama":"Ucuz cheap, pahalı expensive demektir. Change ise para üstüdür."},{"tip":"bosluk","soru":"How ___ is this toy car?","tr":"Bu oyuncak araba ne kadar?","secenekler":["much","many","cost"],"dogru":0,"aciklama":"Fiyat sorarken How much kullanılır, çünkü para sayılamaz."},{"tip":"secim","soru":"Satıcı \"Can I help you?\" dedi. Sadece bakıyorsan ne dersin?","secenekler":["Yes, I'm look only.","No, thanks. I'm only look.","No, thanks. I'm just looking."],"dogru":2,"aciklama":"Kalıp: No, thanks. I'm just looking. (Sadece bakıyorum.)"},{"tip":"bosluk","soru":"Can I ___ this jacket on, please?","tr":"Bu ceketi deneyebilir miyim lütfen?","secenekler":["wear","test","try"],"dogru":2,"aciklama":"Kıyafet denemek try on demektir: Can I try this jacket on?"},{"tip":"secim","soru":"\"Para üstü\" İngilizcede hangisi?","secenekler":["change","receipt","price"],"dogru":0,"aciklama":"Para üstü change, fiş receipt, fiyat price demektir."},{"tip":"bosluk","soru":"How much ___ these socks?","tr":"Bu çoraplar ne kadar?","secenekler":["is","are","does"],"dogru":1,"aciklama":"These socks çoğuldur, bu yüzden are kullanılır."},{"tip":"secim","soru":"\"This T-shirt is on sale.\" ne demek?","secenekler":["Bu tişört indirimde.","Bu tişört satıldı.","Bu tişört satılık değil."],"dogru":0,"aciklama":"On sale indirimde demektir."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["How","much","are","these","shoes"],"cevap":"How much are these shoes?","tr":"Bu ayakkabılar ne kadar?","aciklama":"Çoğul şeylerin fiyatı için How much are these ...? kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["How","much","does","this","backpack","cost"],"cevap":"How much does this backpack cost?","tr":"Bu sırt çantası kaç para?","aciklama":"Kalıp: How much does + şey + cost?"},{"tip":"dogruyanlis","soru":"\"How much is it cost?\" Bu cümle doğru mu?","dogru":false,"aciklama":"Ya How much is it? ya da How much does it cost? denir; ikisi karıştırılmaz."}],"kelimeSozlugu":{"price":{"tr":"fiyat","alt":""},"cheap":{"tr":"ucuz","alt":""},"expensive":{"tr":"pahalı","alt":""},"size":{"tr":"beden, boy","alt":""},"on sale":{"tr":"indirimde","alt":""},"change":{"tr":"para üstü","alt":"başka anlamı: değişmek"},"receipt":{"tr":"fiş","alt":"p okunmaz"},"queue":{"tr":"kuyruk, sıra","alt":"kyu diye okunur"},"customer":{"tr":"müşteri","alt":""},"try":{"tr":"denemek","alt":"try on: (kıyafet) denemek"}}}$dm$::jsonb where id = '1ade1de2-1c03-42fe-b3f1-deb0774fb0e9' and topic_name = 'At the shop and shopping — Mağazada ve Alışveriş';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bir gününü sabahtan akşama kadar İngilizce anlatmayı öğreneceksin. Kaçta kalktığını, okula nasıl gittiğini ve akşam neler yaptığını söyleyebileceksin. Her gün tekrar ettiğimiz işlere İngilizcede <b>routine</b> (rutin) denir.</p><h3>Sabah rutini</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>wake up</b></td><td>uyanmak</td><td><i>I wake up at seven.</i></td></tr><tr><td><b>get up</b></td><td>(yataktan) kalkmak</td><td><i>I get up at ten past seven.</i></td></tr><tr><td><b>have a shower</b></td><td>duş almak</td><td><i>I have a shower in the morning.</i></td></tr><tr><td><b>brush my teeth</b></td><td>dişlerimi fırçalamak</td><td><i>I brush my teeth after breakfast.</i></td></tr><tr><td><b>get dressed</b></td><td>giyinmek</td><td><i>I get dressed quickly.</i></td></tr><tr><td><b>have breakfast</b></td><td>kahvaltı yapmak</td><td><i>We have breakfast together.</i></td></tr><tr><td><b>catch the bus</b></td><td>otobüse yetişmek, binmek</td><td><i>I catch the bus at eight.</i></td></tr><tr><td><b>go to school</b></td><td>okula gitmek</td><td><i>I go to school by bus.</i></td></tr></table><h3>Öğleden sonra ve akşam</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>have lunch</b></td><td>öğle yemeği yemek</td><td><i>We have lunch at school.</i></td></tr><tr><td><b>come home</b></td><td>eve gelmek</td><td><i>I come home at four.</i></td></tr><tr><td><b>do my homework</b></td><td>ödevimi yapmak</td><td><i>I do my homework after school.</i></td></tr><tr><td><b>tidy my room</b></td><td>odamı toplamak</td><td><i>I tidy my room on Saturdays.</i></td></tr><tr><td><b>walk the dog</b></td><td>köpeği gezdirmek</td><td><i>I walk the dog in the evening.</i></td></tr><tr><td><b>watch TV</b></td><td>televizyon izlemek</td><td><i>I watch TV after dinner.</i></td></tr><tr><td><b>have dinner</b></td><td>akşam yemeği yemek</td><td><i>We have dinner at seven.</i></td></tr><tr><td><b>go to bed</b></td><td>yatmak</td><td><i>I go to bed at half past nine.</i></td></tr></table><p>Yemeklerin hepsinde <b>have</b> kullanılır: <b>have breakfast, have lunch, have dinner</b>.</p><h3>Ne sıklıkla? Ne zaman?</h3><p>Rutin anlatırken sıklık kelimeleri çok işe yarar: <b>always</b> (her zaman), <b>usually</b> (genellikle), <b>sometimes</b> (bazen), <b>never</b> (asla, hiç). Bu kelimeler fiilin <b>önüne</b> gelir: <i>I usually walk to school.</i> (Okula genellikle yürüyerek giderim.)</p><p>Zaman ifadeleri: <b>every day</b> (her gün), <b>in the morning</b> (sabahları), <b>in the afternoon</b> (öğleden sonra), <b>in the evening</b> (akşamları), <b>at night</b> (geceleri), <b>on Saturdays</b> (cumartesileri).</p><p>Başkasının gününü anlatırken (he, she, Ece, Ali) fiile <b>-s</b> ekle ve <b>my</b> yerine <b>his/her</b> kullan: <i>Ece gets up at seven. She brushes her teeth.</i></p><h3>Dikkat!</h3><ul><li>Ödev yapmak için <b>make</b> değil <b>do</b> kullanılır. Yanlış: <i>I make my homework.</i> → Doğru: <i>I do my homework.</i></li><li>Dişler yıkanmaz, fırçalanır. Yanlış: <i>I wash my teeth.</i> → Doğru: <i>I brush my teeth.</i></li><li>Yatmak <b>go to bed</b> olur, araya <b>the</b> girmez. Yanlış: <i>I go to the bed.</i> → Doğru: <i>I go to bed.</i> Eve gitmek de <i>go home</i> olur, <i>go to home</i> değil.</li><li>Odayı toplamak <b>collect</b> değildir. Yanlış: <i>I collect my room.</i> → Doğru: <i>I tidy my room.</i></li></ul><h3>Kısaca</h3><p>Günlük işlerini <b>wake up, have breakfast, go to school, do my homework, go to bed</b> gibi kalıplarla anlatırsın. Sıklık kelimelerini fiilin önüne koy, he/she için fiile -s eklemeyi unutma.</p>","ornekler":[{"en":"I wake up at seven o'clock every day.","tr":"Her gün saat yedide uyanırım."},{"en":"Ece brushes her teeth after breakfast.","tr":"Ece kahvaltıdan sonra dişlerini fırçalar."},{"en":"We have breakfast together on Sundays.","tr":"Pazar günleri birlikte kahvaltı yaparız."},{"en":"Mert catches the school bus at eight o'clock.","tr":"Mert saat sekizde okul servisine biner."},{"en":"I usually do my homework in the afternoon.","tr":"Ödevimi genellikle öğleden sonra yaparım."},{"en":"Zeynep never goes to bed late on school nights.","tr":"Zeynep ertesi gün okul varsa asla geç yatmaz."},{"en":"— Do you walk your dog every evening? — Yes, I do.","tr":"Köpeğini her akşam gezdiriyor musun? Evet, gezdiriyorum."},{"en":"Ali tidies his room on Saturdays.","tr":"Ali cumartesileri odasını toplar."},{"en":"Papi the parrot wakes up before everyone.","tr":"Papağan Papi herkesten önce uyanır."},{"en":"We have dinner at seven and go to bed at ten.","tr":"Saat yedide akşam yemeği yeriz, onda yatarız."}],"test":[{"tip":"secim","soru":"\"Kahvaltı yapmak\" İngilizcede nasıl söylenir?","secenekler":["do breakfast","have breakfast","take breakfast"],"dogru":1,"aciklama":"Yemeklerde have kullanılır: have breakfast, have lunch, have dinner."},{"tip":"secim","soru":"\"Get dressed\" ne demek?","secenekler":["giyinmek","duş almak","uyanmak"],"dogru":0,"aciklama":"Get dressed giyinmektir. Duş almak have a shower, uyanmak wake up olur."},{"tip":"bosluk","soru":"I ___ my teeth every morning.","tr":"Her sabah dişlerimi fırçalarım.","secenekler":["wash","comb","brush"],"dogru":2,"aciklama":"Dişler fırçalanır: brush my teeth. Comb saç taramaktır."},{"tip":"bosluk","soru":"I always ___ my homework after school.","tr":"Ödevimi her zaman okuldan sonra yaparım.","secenekler":["make","do","take"],"dogru":1,"aciklama":"Ödev yapmak do my homework olur, make kullanılmaz."},{"tip":"secim","soru":"\"Odamı toplarım.\" cümlesinin İngilizcesi hangisi?","secenekler":["I collect my room.","I make my room.","I tidy my room."],"dogru":2,"aciklama":"Odayı toplamak tidy my room demektir. Collect bir şeyleri biriktirmek, toplamaktır."},{"tip":"bosluk","soru":"Zeynep ___ to bed at half past nine.","tr":"Zeynep dokuz buçukta yatar.","secenekler":["goes","go","sleeps"],"dogru":0,"aciklama":"Yatmak go to bed olur; Zeynep (she) için fiile -es eklenir: goes."},{"tip":"secim","soru":"Hangisi \"her zaman\" anlamına gelir?","secenekler":["always","usually","sometimes"],"dogru":0,"aciklama":"Always her zaman, usually genellikle, sometimes bazen demektir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Ece","brushes","her","teeth"],"cevap":"Ece brushes her teeth.","tr":"Ece dişlerini fırçalar.","aciklama":"Dişler fırçalanır: brush. Ece (she) için fiile -es eklenir, my yerine her gelir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Mert","never","goes","to","bed","late"],"cevap":"Mert never goes to bed late.","tr":"Mert asla geç yatmaz.","aciklama":"Never fiilin önüne gelir; yatmak go to bed olur."},{"tip":"dogruyanlis","soru":"\"I go to the bed at ten.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Yatmak go to bed olur, the kullanılmaz: I go to bed at ten."}],"kelimeSozlugu":{"wake up":{"tr":"uyanmak","alt":""},"get up":{"tr":"kalkmak","alt":"yataktan kalkmak"},"get dressed":{"tr":"giyinmek","alt":""},"brush":{"tr":"fırçalamak","alt":"brush my teeth: dişlerimi fırçalamak"},"breakfast":{"tr":"kahvaltı","alt":"have breakfast: kahvaltı yapmak"},"homework":{"tr":"ödev","alt":"do my homework: ödevimi yapmak"},"tidy":{"tr":"toplamak, düzeltmek","alt":"tidy my room: odamı toplamak"},"usually":{"tr":"genellikle","alt":""},"never":{"tr":"asla, hiç","alt":""},"routine":{"tr":"rutin, her günkü düzen","alt":""}}}$dm$::jsonb where id = 'feffd2a5-81b2-47ea-a8ba-37254c07e3f6' and topic_name = 'Daily life and routines — Günlük Yaşam ve Rutinler';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Okul hayatını, dersleri, sınavları ve meslekleri anlatan kelimeleri öğreneceksin. Ayrıca gelecekte ne olmak istediğini İngilizce söyleyebileceksin.</p><h3>Okullar ve okul hayatı</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>primary school</b></td><td>ilkokul</td><td><i>My sister is at primary school.</i></td></tr><tr><td><b>secondary school</b></td><td>ortaokul</td><td><i>Elif is a student at a secondary school.</i></td></tr><tr><td><b>high school</b></td><td>lise</td><td><i>Ayşe's sister finished high school.</i></td></tr><tr><td><b>university</b></td><td>üniversite</td><td><i>He wants to go to university.</i></td></tr><tr><td><b>classmate</b></td><td>sınıf arkadaşı</td><td><i>Deniz is my classmate.</i></td></tr><tr><td><b>subject</b></td><td>ders (konu olarak)</td><td><i>My favourite subject is science.</i></td></tr><tr><td><b>timetable</b></td><td>ders programı</td><td><i>Look at the timetable.</i></td></tr><tr><td><b>homework</b></td><td>ödev</td><td><i>I do my homework after dinner.</i></td></tr></table><h3>Sınavlar ve notlar</h3><table><tr><th>English</th><th>Türkçe</th></tr><tr><td><b>take an exam</b></td><td>sınava girmek</td></tr><tr><td><b>pass an exam</b></td><td>sınavı geçmek (başarmak)</td></tr><tr><td><b>fail an exam</b></td><td>sınavdan kalmak</td></tr><tr><td><b>get a good mark</b></td><td>iyi bir not almak</td></tr><tr><td><b>study</b></td><td>ders çalışmak</td></tr><tr><td><b>learn</b></td><td>öğrenmek</td></tr><tr><td><b>graduate</b></td><td>mezun olmak</td></tr></table><p><i>We have a maths exam on Friday. I'm going to study hard because I want to pass the exam.</i> (Cuma günü matematik sınavımız var. Çok çalışacağım çünkü sınavı geçmek istiyorum.)</p><h3>Gelecek planları ve meslekler</h3><p>Gelecek hakkında konuşurken şu kalıpları kullan:</p><ul><li><b>What do you want to be in the future?</b> = Gelecekte ne olmak istiyorsun?</li><li><b>I want to be a ...</b> = ... olmak istiyorum.</li><li><b>I'm going to ...</b> = ...-eceğim (planın var).</li><li><b>I hope to ...</b> = ...-meyi umuyorum.</li></ul><p>Meslekler: <b>doctor</b> (doktor), <b>teacher</b> (öğretmen), <b>vet</b> (veteriner), <b>engineer</b> (mühendis), <b>pilot</b> (pilot), <b>scientist</b> (bilim insanı), <b>architect</b> (mimar). Bir mesleğin hayalindeki iş olduğunu söylemek için: <i>My dream job is ...</i></p><h3>Dikkat!</h3><ul><li>Meslekten önce a ya da an gelir: <i>I want to be doctor.</i> → <i>I want to be a doctor.</i> <i>an engineer</i>, <i>an architect</i>.</li><li>Sınav “yapılmaz”, girilir: <i>make an exam</i> → <i>take an exam</i></li><li>high school “yüksekokul” değil, <b>lise</b> demektir.</li><li>study ile learn farklı: ders çalışmak <i>study</i>, öğrenmek <i>learn</i>: <i>I study every day and I learn new words.</i></li></ul><h3>Kısaca</h3><p>Okul türleri, dersler ve sınavlarla ilgili kelimelerle okul hayatını anlatabilirsin. Gelecek planın için I want to be a ... ya da I'm going to ... kalıplarını kullan.</p>","ornekler":[{"en":"Elif is a student at a secondary school.","tr":"Elif bir ortaokul öğrencisi."},{"en":"My favourite subject is science.","tr":"En sevdiğim ders fen bilimleri."},{"en":"We have a maths exam on Friday.","tr":"Cuma günü matematik sınavımız var."},{"en":"Mert studies hard because he wants to pass the exam.","tr":"Mert çok çalışıyor çünkü sınavı geçmek istiyor."},{"en":"I got a good mark in English!","tr":"İngilizceden iyi bir not aldım!"},{"en":"My brother is going to go to university next year.","tr":"Ağabeyim gelecek yıl üniversiteye gidecek."},{"en":"What do you want to be in the future?","tr":"Gelecekte ne olmak istiyorsun?"},{"en":"I want to be a vet because I love animals.","tr":"Veteriner olmak istiyorum çünkü hayvanları çok seviyorum."},{"en":"Deniz hopes to become an engineer one day.","tr":"Deniz bir gün mühendis olmayı umuyor."},{"en":"Ayşe's sister graduated from high school last June.","tr":"Ayşe'nin ablası geçen haziranda liseden mezun oldu."}],"test":[{"tip":"secim","soru":"\"high school\" Türkçede ne demektir?","secenekler":["yüksekokul","lise","ilkokul"],"dogru":1,"aciklama":"high school lise demektir. İlkokul primary school'dur."},{"tip":"secim","soru":"\"Ders programı\" İngilizcede hangisidir?","secenekler":["timetable","lesson table","subject list"],"dogru":0,"aciklama":"Haftalık ders programına timetable denir."},{"tip":"bosluk","soru":"My favourite ___ is maths.","tr":"En sevdiğim ders matematik.","secenekler":["student","subject","teacher"],"dogru":1,"aciklama":"Matematik, fen gibi derslere subject denir."},{"tip":"bosluk","soru":"I'm going to ___ an English exam tomorrow.","tr":"Yarın İngilizce sınavına gireceğim.","secenekler":["make","take","give"],"dogru":1,"aciklama":"Sınava girmek take an exam'dir; make an exam denmez."},{"tip":"secim","soru":"\"Sınavı geçmek\" İngilizcede hangisidir?","secenekler":["fail the exam","take the exam","pass the exam"],"dogru":2,"aciklama":"pass = geçmek, fail = kalmak, take = sınava girmek."},{"tip":"bosluk","soru":"I love animals. I want to be a ___.","tr":"Hayvanları çok seviyorum. Veteriner olmak istiyorum.","secenekler":["pilot","engineer","vet"],"dogru":2,"aciklama":"Hayvan doktoruna vet (veteriner) denir."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","do","you","want","to","be"],"cevap":"What do you want to be?","tr":"Ne olmak istiyorsun?","aciklama":"Meslek sorusu: What do you want to be?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","want","to","be","a","scientist"],"cevap":"I want to be a scientist.","tr":"Bilim insanı olmak istiyorum.","aciklama":"Gelecek planı için: I want to be a/an + meslek."},{"tip":"secim","soru":"\"Ders çalışmak\" İngilizcede hangisidir?","secenekler":["learn","read lesson","study"],"dogru":2,"aciklama":"Ders çalışmak study'dir; learn öğrenmek demektir."},{"tip":"dogruyanlis","soru":"\"fail an exam\" sınavı başarıyla geçmek demektir.","dogru":false,"aciklama":"Hayır! fail sınavdan kalmak demektir. Geçmek pass'tir."}],"kelimeSozlugu":{"secondary school":{"tr":"ortaokul","alt":""},"high school":{"tr":"lise","alt":"yüksekokul değil"},"university":{"tr":"üniversite","alt":""},"subject":{"tr":"ders","alt":"matematik, fen gibi"},"exam":{"tr":"sınav","alt":""},"pass":{"tr":"geçmek","alt":"sınavı başarmak"},"mark":{"tr":"not","alt":"sınav notu"},"future":{"tr":"gelecek","alt":""},"vet":{"tr":"veteriner","alt":""},"engineer":{"tr":"mühendis","alt":""},"graduated":{"tr":"mezun oldu","alt":"graduate"}}}$dm$::jsonb where id = '421242b4-7824-4678-a99f-62c0fffa41a5' and topic_name = 'Education and future plans — Eğitim ve Gelecek Planları';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Filmler, müzik ve sinema ile ilgili İngilizce kelimeleri öğreneceksin. Hangi filmleri ve müziği sevdiğini anlatabilecek, arkadaşına da sorabileceksin.</p><h3>Film türleri</h3><p>Film için İngilizcede iki kelime var: <b>film</b> (İngiltere) ve <b>movie</b> (Amerika). İkisi de doğrudur. Çizgi filme ise <b>cartoon</b> denir.</p><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>cartoon</b> </td><td>çizgi film</td><td><i>I watch cartoons on Saturdays.</i></td></tr><tr><td><b>comedy</b></td><td>komedi</td><td><i>Comedy films make me laugh.</i></td></tr><tr><td><b>action film</b></td><td>aksiyon filmi</td><td><i>Action films are exciting.</i></td></tr><tr><td><b>science fiction film</b></td><td>bilim kurgu filmi</td><td><i>This science fiction film is about space.</i></td></tr><tr><td><b>horror film</b></td><td>korku filmi</td><td><i>Horror films are too scary for me.</i></td></tr><tr><td><b>documentary</b></td><td>belgesel</td><td><i>We watched a documentary about whales.</i></td></tr><tr><td><b>TV series</b></td><td>dizi</td><td><i>My mum loves this TV series.</i></td></tr></table><h3>Sinemada</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>cinema</b></td><td>sinema</td><td><i>Let's go to the cinema.</i></td></tr><tr><td><b>ticket</b> </td><td>bilet</td><td><i>Two tickets, please.</i></td></tr><tr><td><b>popcorn</b></td><td>patlamış mısır</td><td><i>I always eat popcorn at the cinema.</i></td></tr><tr><td><b>screen</b></td><td>perde, ekran</td><td><i>The screen is very big.</i></td></tr><tr><td><b>actor / actress</b></td><td>erkek oyuncu / kadın oyuncu</td><td><i>She is a famous actress.</i></td></tr></table><h3>Müzik dünyası</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>song</b></td><td>şarkı</td><td><i>This is my favourite song.</i></td></tr><tr><td><b>singer</b></td><td>şarkıcı</td><td><i>Who is your favourite singer?</i></td></tr><tr><td><b>band</b></td><td>müzik grubu</td><td><i>My brother is in a rock band.</i></td></tr><tr><td><b>concert</b></td><td>konser</td><td><i>The concert starts at eight.</i></td></tr><tr><td><b>stage</b></td><td>sahne</td><td><i>The band is on the stage.</i></td></tr><tr><td><b>guitar / piano / drums</b></td><td>gitar / piyano / davul</td><td><i>Can you play the piano?</i></td></tr></table><h3>Sık kullanılan kalıplar</h3><ul><li><b>watch a film / watch TV</b> = film izlemek / televizyon izlemek</li><li><b>listen to music</b> = müzik dinlemek</li><li><b>play the guitar</b> = gitar çalmak</li><li><b>What kind of films do you like?</b> = Ne tür filmler seversin? <i>I like comedies.</i></li><li><b>What kind of music do you like?</b> = Ne tür müzik seversin? <i>I like pop music.</i></li><li>Filmi anlatmak için: <b>funny</b> (komik), <b>exciting</b> (heyecanlı), <b>scary</b> (korkutucu), <b>boring</b> (sıkıcı).</li></ul><h3>Dikkat!</h3><ul><li><b>listen</b> fiilinden sonra <b>to</b> gelir: <i>I listen music.</i> → <i>I listen to music.</i></li><li>Film izlemek için <b>look</b> değil <b>watch</b> kullanılır: <i>I look a film.</i> → <i>I watch a film.</i></li><li>Türkçede “film izlemeyi severim” deriz ama İngilizcede genel konuşurken çoğul kullanılır: <i>I like watching film.</i> → <i>I like watching films.</i></li><li><b>song</b> şarkıdır, <b>singer</b> şarkıyı söyleyen kişidir: <i>He is a good song.</i> → <i>He is a good singer.</i></li></ul><h3>Kısaca</h3><p>Film türlerini, sinema ve müzik kelimelerini öğrendin. <b>watch a film</b>, <b>listen to music</b> ve <b>play the guitar</b> kalıplarını unutma.</p>","ornekler":[{"en":"I love watching cartoons on Saturday mornings.","tr":"Cumartesi sabahları çizgi film izlemeyi çok severim."},{"en":"Comedy films always make me laugh.","tr":"Komedi filmleri beni hep güldürür."},{"en":"What kind of films do you like? I like action films.","tr":"Ne tür filmler seversin? Aksiyon filmlerini severim."},{"en":"Ece listens to music on the bus.","tr":"Ece otobüste müzik dinler."},{"en":"My brother plays the guitar in a rock band.","tr":"Ağabeyim bir rock grubunda gitar çalar."},{"en":"We bought two tickets and some popcorn.","tr":"İki bilet ve biraz patlamış mısır aldık."},{"en":"Who is your favourite singer?","tr":"En sevdiğin şarkıcı kim?"},{"en":"The actor was very funny in this film.","tr":"Oyuncu bu filmde çok komikti."},{"en":"Let's go to the concert on Friday.","tr":"Cuma günü konsere gidelim."},{"en":"I don't like horror films. They're too scary.","tr":"Korku filmlerini sevmem. Çok korkutucular."}],"test":[{"tip":"secim","soru":"\"Cartoon\" ne demektir?","secenekler":["çizgi film","belgesel","dizi"],"dogru":0,"aciklama":"Cartoon çizgi filmdir. Belgesel documentary, dizi TV series'dir."},{"tip":"secim","soru":"Şarkı söyleyen kişiye İngilizcede ne denir?","secenekler":["song","singer","band"],"dogru":1,"aciklama":"Şarkıcı singer'dır. Song şarkının kendisi, band müzik grubudur."},{"tip":"bosluk","soru":"I listen ___ music every evening.","tr":"Her akşam müzik dinlerim.","secenekler":["at","for","to"],"dogru":2,"aciklama":"Listen fiilinden sonra to gelir: listen to music."},{"tip":"secim","soru":"Sinemaya girmek için ne alman gerekir?","secenekler":["a screen","a stage","a ticket"],"dogru":2,"aciklama":"Sinemaya girmek için bilet (ticket) alırsın."},{"tip":"bosluk","soru":"We ___ a funny film last night.","tr":"Dün gece komik bir film izledik.","secenekler":["looked","watched","listened"],"dogru":1,"aciklama":"Film izlemek watch a film'dir. Look bakmak, listen dinlemektir."},{"tip":"bosluk","soru":"This comedy is so ___! Everyone is laughing.","tr":"Bu komedi çok komik! Herkes gülüyor.","secenekler":["funny","boring","scary"],"dogru":0,"aciklama":"Herkes gülüyorsa film komiktir: funny. Boring sıkıcı, scary korkutucu demektir."},{"tip":"secim","soru":"Arkadaşın soruyor: \"What kind of music do you like?\" Hangisi uygun cevaptır?","secenekler":["Yes, I do.","I like pop music.","I like music very."],"dogru":1,"aciklama":"Ne tür müzik sevdiğin soruluyor, türü söylersin: I like pop music."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What","kind","of","films","do","you","like"],"cevap":"What kind of films do you like?","tr":"Ne tür filmler seversin?","aciklama":"Soru kalıbı: What kind of + isim + do you like?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["My","brother","plays","the","guitar"],"cevap":"My brother plays the guitar.","tr":"Ağabeyim gitar çalar.","aciklama":"Müzik aleti çalmak: play the + alet. He/she ile plays olur."},{"tip":"dogruyanlis","soru":"Müzik aleti çalmak için \"play\" fiili kullanılır: play the piano. Bu doğru mu?","dogru":true,"aciklama":"Doğru! Gitar, piyano, davul çalmak için play the kullanılır."}],"kelimeSozlugu":{"cartoon":{"tr":"çizgi film","alt":""},"comedy":{"tr":"komedi","alt":""},"actor":{"tr":"erkek oyuncu","alt":"kadın oyuncu: actress"},"singer":{"tr":"şarkıcı","alt":""},"band":{"tr":"müzik grubu","alt":""},"concert":{"tr":"konser","alt":""},"ticket":{"tr":"bilet","alt":""},"popcorn":{"tr":"patlamış mısır","alt":""},"guitar":{"tr":"gitar","alt":"play the guitar: gitar çalmak"},"scary":{"tr":"korkutucu","alt":""}}}$dm$::jsonb where id = '3e2b8b43-3386-45dc-b682-a23f926a7c26' and topic_name = 'Entertainment (films, music, etc.) — Eğlence (Filmler, Müzik vb.)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Doğayı ve çevreyi anlatan İngilizce kelimeleri öğreneceksin. Çevre sorunlarını ve doğayı korumak için neler yapabileceğini İngilizce söyleyebileceksin.</p><h3>Doğada neler var?</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>nature</b></td><td>doğa</td><td><i>I love nature.</i></td></tr><tr><td><b>environment</b></td><td>çevre</td><td><i>Keep the environment clean.</i></td></tr><tr><td><b>forest</b></td><td>orman</td><td><i>There are many trees in the forest.</i></td></tr><tr><td><b>rainforest</b></td><td>yağmur ormanı</td><td><i>Parrots live in rainforests.</i></td></tr><tr><td><b>river</b></td><td>nehir</td><td><i>The river is very long.</i></td></tr><tr><td><b>lake</b></td><td>göl</td><td><i>We swam in the lake.</i></td></tr><tr><td><b>mountain</b></td><td>dağ</td><td><i>The mountain is very high.</i></td></tr><tr><td><b>plant</b></td><td>bitki</td><td><i>Plants need water and sun.</i></td></tr><tr><td><b>wild animals</b></td><td>vahşi hayvanlar</td><td><i>Bears are wild animals.</i></td></tr><tr><td><b>air</b></td><td>hava (soluduğumuz)</td><td><i>Fresh air is good for you.</i></td></tr></table><h3>Çevre sorunları</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>pollution</b></td><td>kirlilik</td><td><i>Air pollution is bad for our health.</i></td></tr><tr><td><b>polluted</b></td><td>kirlenmiş</td><td><i>The river is polluted.</i></td></tr><tr><td><b>rubbish</b></td><td>çöp</td><td><i>There is rubbish on the beach.</i></td></tr><tr><td><b>plastic bag</b></td><td>plastik poşet</td><td><i>Plastic bags hurt sea animals.</i></td></tr><tr><td><b>endangered</b></td><td>nesli tükenmekte olan</td><td><i>Some sea turtles are endangered.</i></td></tr><tr><td><b>cut down</b></td><td>(ağaç) kesmek</td><td><i>People cut down too many trees.</i></td></tr><tr><td><b>climate change</b></td><td>iklim değişikliği</td><td><i>Climate change is a big problem.</i></td></tr></table><p>Amerikan İngilizcesinde çöp için <b>garbage</b> ya da <b>trash</b> da denir. Çöp kutusu ise <b>bin</b>'dir.</p><h3>Çevreyi koruyalım</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>protect</b></td><td>korumak</td><td><i>We must protect nature.</i></td></tr><tr><td><b>recycle</b></td><td>geri dönüştürmek</td><td><i>We recycle paper and glass.</i></td></tr><tr><td><b>reuse</b></td><td>yeniden kullanmak</td><td><i>Reuse your shopping bags.</i></td></tr><tr><td><b>save</b></td><td>tasarruf etmek, kurtarmak</td><td><i>Save water!</i></td></tr><tr><td><b>plant a tree</b></td><td>ağaç dikmek</td><td><i>Let's plant a tree.</i></td></tr><tr><td><b>turn off</b></td><td>kapatmak</td><td><i>Turn off the lights.</i></td></tr></table><p>Öneri ve kural söylerken şu kalıpları kullan:</p><ul><li><b>We should + fiil</b> = ...meliyiz: <i>We should save water.</i></li><li><b>We shouldn't + fiil</b> = ...memeliyiz: <i>We shouldn't cut down the forests.</i></li><li><b>Don't + fiil</b> = ...me!: <i>Don't throw rubbish on the ground.</i></li></ul><h3>Dikkat!</h3><ul><li>Türkçede “hava” iki anlamlıdır. Soluduğumuz hava <b>air</b>, hava durumu <b>weather</b>: <i>The weather is dirty.</i> → <i>The air is dirty.</i></li><li><b>endangered</b> (nesli tükenmekte) ile <b>dangerous</b> (tehlikeli) farklıdır: <i>Sea turtles are dangerous.</i> → <i>Sea turtles are endangered.</i></li><li><b>nature</b> genelde <b>the</b> almaz: <i>I love the nature.</i> → <i>I love nature.</i></li><li><b>recycle</b> fabrikada yeniden işlemek, <b>reuse</b> aynı şeyi tekrar kullanmaktır. Eski şişeyi vazo yaparsan <i>reuse</i> edersin.</li></ul><h3>Kısaca</h3><p>Doğa <b>nature</b>, çevre <b>environment</b>, kirlilik <b>pollution</b> demektir. Çevreyi korumak için <b>We should recycle, save water and plant trees</b> diyebilirsin.</p>","ornekler":[{"en":"We must protect nature and wild animals.","tr":"Doğayı ve vahşi hayvanları korumalıyız."},{"en":"Our family recycles paper, glass and plastic.","tr":"Ailemiz kağıdı, camı ve plastiği geri dönüştürür."},{"en":"Don't throw rubbish on the ground. Put it in the bin.","tr":"Çöpü yere atma. Çöp kutusuna at."},{"en":"Plastic bags cause pollution in the sea.","tr":"Plastik poşetler denizde kirliliğe neden olur."},{"en":"Some sea turtles are endangered.","tr":"Bazı deniz kaplumbağalarının nesli tükenmek üzere."},{"en":"Our class planted ten trees in the school garden.","tr":"Sınıfımız okul bahçesine on ağaç dikti."},{"en":"Turn off the lights when you leave the room.","tr":"Odadan çıkarken ışıkları kapat."},{"en":"Is the river clean? No, it isn't. It's polluted.","tr":"Nehir temiz mi? Hayır, değil. Kirlenmiş."},{"en":"We shouldn't cut down the forests.","tr":"Ormanları kesmemeliyiz."},{"en":"Many parrots like Papi live in rainforests.","tr":"Papi gibi birçok papağan yağmur ormanlarında yaşar."}],"test":[{"tip":"secim","soru":"\"Forest\" kelimesinin Türkçesi nedir?","secenekler":["nehir","orman","dağ"],"dogru":1,"aciklama":"Forest orman demektir. Nehir river, dağ mountain'dır."},{"tip":"secim","soru":"\"Geri dönüştürmek\" İngilizcede hangisidir?","secenekler":["recycle","reuse","protect"],"dogru":0,"aciklama":"Geri dönüştürmek recycle'dır. Reuse yeniden kullanmak, protect korumak demektir."},{"tip":"bosluk","soru":"Don't throw rubbish on the ground. Put it in the ___.","tr":"Çöpü yere atma. Çöp kutusuna at.","secenekler":["box","bin","bag"],"dogru":1,"aciklama":"Çöp kutusu bin'dir. Box kutu, bag çanta ya da poşettir."},{"tip":"secim","soru":"Hangisi bir çevre sorunudur?","secenekler":["recycling","planting trees","air pollution"],"dogru":2,"aciklama":"Air pollution (hava kirliliği) bir sorundur. Diğer ikisi çevreye iyi gelir."},{"tip":"bosluk","soru":"Some sea turtles are ___.","tr":"Bazı deniz kaplumbağalarının nesli tükenmek üzere.","secenekler":["endangered","dangerous","danger"],"dogru":0,"aciklama":"Nesli tükenmekte olan: endangered. Dangerous tehlikeli demektir."},{"tip":"bosluk","soru":"The ___ in the city is very dirty today.","tr":"Bugün şehirdeki hava çok kirli.","secenekler":["weather","air","wind"],"dogru":1,"aciklama":"Soluduğumuz hava air'dir. Weather hava durumu, wind rüzgardır."},{"tip":"secim","soru":"Eski bir şişeyi atmıyor, ona çiçek koyup vazo yapıyorsun. Bu hangisidir?","secenekler":["recycle","pollute","reuse"],"dogru":2,"aciklama":"Bir şeyi tekrar kullanmak reuse'dur. Recycle fabrikada yeniden işlemektir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Parrots","live","in","rainforests"],"cevap":"Parrots live in rainforests.","tr":"Papağanlar yağmur ormanlarında yaşar.","aciklama":"rainforest yağmur ormanı demektir; yer için in kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Our","class","planted","ten","trees"],"cevap":"Our class planted ten trees.","tr":"Sınıfımız on ağaç dikti.","aciklama":"Ağaç dikmek plant a tree demektir; geçmiş zamanda planted olur."},{"tip":"dogruyanlis","soru":"\"I love the nature.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Nature genelde the almaz. Doğrusu: I love nature."}],"kelimeSozlugu":{"nature":{"tr":"doğa","alt":""},"environment":{"tr":"çevre","alt":""},"forest":{"tr":"orman","alt":""},"pollution":{"tr":"kirlilik","alt":""},"recycle":{"tr":"geri dönüştürmek","alt":""},"endangered":{"tr":"nesli tükenmekte olan","alt":"dangerous (tehlikeli) ile karıştırma"},"protect":{"tr":"korumak","alt":""},"rubbish":{"tr":"çöp","alt":"ABD: trash, garbage"},"bin":{"tr":"çöp kutusu","alt":""},"air":{"tr":"hava","alt":"soluduğumuz hava; hava durumu weather"}}}$dm$::jsonb where id = 'e7e3b095-c55b-491b-8c96-bd4b3619ef99' and topic_name = 'Environment and nature — Çevre ve Doğa';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Nasıl hissettiğini ve insanların nasıl biri olduğunu İngilizce anlatmayı öğreneceksin. Duygular (feelings) değişir, kişilik (personality) ise bir insanın karakteridir.</p><h3>Duygular: Şu an nasıl hissediyorsun?</h3><p>Duygu söylerken <b>I am / I'm + duygu</b> ya da <b>I feel + duygu</b> kalıbını kullan.</p><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>happy</b></td><td>mutlu</td><td><i>I'm happy today.</i></td></tr><tr><td><b>sad</b></td><td>üzgün</td><td><i>Why are you sad?</i></td></tr><tr><td><b>angry</b></td><td>kızgın</td><td><i>Dad is angry.</i></td></tr><tr><td><b>tired</b></td><td>yorgun</td><td><i>I feel tired after football.</i></td></tr><tr><td><b>bored</b></td><td>sıkılmış</td><td><i>I'm bored at home.</i></td></tr><tr><td><b>excited</b></td><td>heyecanlı</td><td><i>Can is excited about his party.</i></td></tr><tr><td><b>nervous</b></td><td>gergin</td><td><i>I feel nervous before exams.</i></td></tr><tr><td><b>scared / afraid</b></td><td>korkmuş</td><td><i>She is afraid of spiders.</i></td></tr><tr><td><b>surprised</b></td><td>şaşırmış</td><td><i>I was surprised by the gift.</i></td></tr><tr><td><b>proud</b></td><td>gururlu</td><td><i>Mum is proud of me.</i></td></tr></table><h3>Kişilik: Nasıl birisin?</h3><p>Karakter söylerken <b>He is / She is + özellik</b> kalıbını kullan.</p><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>kind</b></td><td>nazik, iyi kalpli</td><td><i>Zeynep is very kind.</i></td></tr><tr><td><b>friendly</b></td><td>cana yakın</td><td><i>Our new neighbour is friendly.</i></td></tr><tr><td><b>helpful</b></td><td>yardımsever</td><td><i>Ali is always helpful.</i></td></tr><tr><td><b>honest</b></td><td>dürüst</td><td><i>An honest person tells the truth.</i></td></tr><tr><td><b>shy</b></td><td>utangaç</td><td><i>Deniz is a bit shy.</i></td></tr><tr><td><b>brave</b></td><td>cesur</td><td><i>Firefighters are brave.</i></td></tr><tr><td><b>cheerful</b></td><td>neşeli</td><td><i>Elif is a cheerful girl.</i></td></tr><tr><td><b>clever</b></td><td>zeki</td><td><i>Papi is a clever parrot.</i></td></tr><tr><td><b>lazy</b></td><td>tembel</td><td><i>My cat is very lazy.</i></td></tr><tr><td><b>hard-working</b></td><td>çalışkan</td><td><i>Mert is hard-working.</i></td></tr></table><h3>Soru sormak</h3><ul><li><b>How do you feel?</b> / <b>How are you feeling?</b> = Nasıl hissediyorsun? <i>I feel great!</i></li><li><b>What is he like?</b> = O nasıl biri? (karakterini sorar) <i>He's funny and kind.</i></li><li><b>What does he look like?</b> = Nasıl görünüyor? (dış görünüşü sorar) <i>He's tall.</i></li><li><b>afraid of</b> = ...den korkmak: <i>I'm afraid of dogs.</i></li></ul><h3>Dikkat!</h3><ul><li>Türkçedeki “kendimi” İngilizceye çevrilmez: <i>I feel myself happy.</i> → <i>I feel happy.</i></li><li><b>bored</b> sıkılmış, <b>boring</b> sıkıcı demektir: <i>I'm boring.</i> (Ben sıkıcıyım!) → <i>I'm bored.</i> (Sıkıldım.)</li><li>“...den korkmak” için <b>from</b> değil <b>of</b>: <i>I'm afraid from dogs.</i> → <i>I'm afraid of dogs.</i></li><li><b>What is she like?</b> içindeki like “sevmek” değildir, “nasıl” anlamı katar. Cevap olarak <i>She likes pizza.</i> değil <i>She's kind.</i> de.</li></ul><h3>Kısaca</h3><p>Duygular için <b>I'm / I feel + happy, tired, nervous</b> gibi kelimeleri kullan. Birinin karakterini anlatmak için <b>She is kind, honest, shy</b> de; sormak için <b>What is she like?</b></p>","ornekler":[{"en":"My best friend Zeynep is very kind and helpful.","tr":"En iyi arkadaşım Zeynep çok nazik ve yardımseverdir."},{"en":"I feel nervous before every exam.","tr":"Her sınavdan önce gergin hissederim."},{"en":"Can was very excited about his birthday party.","tr":"Can doğum günü partisi için çok heyecanlıydı."},{"en":"Don't be shy. Come and play with us!","tr":"Utangaç olma. Gel, bizimle oyna!"},{"en":"An honest person never tells lies.","tr":"Dürüst bir insan asla yalan söylemez."},{"en":"Why are you sad, Elif?","tr":"Elif, neden üzgünsün?"},{"en":"I'm bored. Let's play a game.","tr":"Sıkıldım. Hadi bir oyun oynayalım."},{"en":"My little brother is afraid of the dark.","tr":"Küçük kardeşim karanlıktan korkar."},{"en":"What is your teacher like? She's funny and clever.","tr":"Öğretmenin nasıl biri? Komik ve zeki."},{"en":"The brave firefighter saved the cat.","tr":"Cesur itfaiyeci kediyi kurtardı."}],"test":[{"tip":"secim","soru":"\"Shy\" ne demektir?","secenekler":["utangaç","cesur","kızgın"],"dogru":0,"aciklama":"Shy utangaç demektir. Cesur brave, kızgın angry'dir."},{"tip":"secim","soru":"Hangisi bir kişilik (karakter) özelliğidir?","secenekler":["tired","bored","honest"],"dogru":2,"aciklama":"Honest (dürüst) bir karakter özelliğidir. Tired ve bored geçici duygulardır."},{"tip":"bosluk","soru":"I'm ___. There's nothing to do.","tr":"Sıkıldım. Yapacak hiçbir şey yok.","secenekler":["boring","bored","bore"],"dogru":1,"aciklama":"Sıkılmış hissediyorsan bored dersin. Boring sıkıcı demektir."},{"tip":"bosluk","soru":"My little brother is afraid ___ the dark.","tr":"Küçük kardeşim karanlıktan korkar.","secenekler":["from","of","to"],"dogru":1,"aciklama":"...den korkmak: afraid of. Türkçedeki -den eki yüzünden from demek yanlıştır."},{"tip":"secim","soru":"Ali bütün arkadaşlarına ödevlerinde yardım eder. Ali nasıl biridir?","secenekler":["helpful","lazy","shy"],"dogru":0,"aciklama":"Herkese yardım eden kişi helpful (yardımsever) biridir."},{"tip":"bosluk","soru":"I feel ___ before every exam.","tr":"Her sınavdan önce gergin hissederim.","secenekler":["proud","honest","nervous"],"dogru":2,"aciklama":"Gergin hissetmek: feel nervous."},{"tip":"secim","soru":"Arkadaşın soruyor: \"What is your teacher like?\" Hangisi uygun cevaptır?","secenekler":["She likes pizza.","She's tall.","She's kind and funny."],"dogru":2,"aciklama":"What is she like? karakteri sorar: She's kind and funny. Boyu sormak için What does she look like? denir."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Why","are","you","so","sad"],"cevap":"Why are you so sad?","tr":"Neden bu kadar üzgünsün?","aciklama":"Soru kalıbı: Why + are + you + duygu?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","feel","very","proud","of","my","brother"],"cevap":"I feel very proud of my brother.","tr":"Kardeşimle çok gurur duyuyorum.","aciklama":"Duygu anlatmak için: I feel + (very) + duygu. proud of = ...ile gurur duymak."},{"tip":"dogruyanlis","soru":"\"I feel myself happy.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Kendimi kelimesi çevrilmez. Doğrusu: I feel happy."}],"kelimeSozlugu":{"feel":{"tr":"hissetmek","alt":""},"kind":{"tr":"nazik, iyi kalpli","alt":""},"helpful":{"tr":"yardımsever","alt":""},"honest":{"tr":"dürüst","alt":""},"shy":{"tr":"utangaç","alt":""},"brave":{"tr":"cesur","alt":""},"nervous":{"tr":"gergin","alt":""},"excited":{"tr":"heyecanlı","alt":""},"bored":{"tr":"sıkılmış","alt":"boring: sıkıcı"},"afraid":{"tr":"korkmuş","alt":"afraid of: ...den korkmak"},"proud":{"tr":"gururlu","alt":"proud of: ...ile gurur duymak"}}}$dm$::jsonb where id = 'd0c86af7-c325-4996-8c5a-41b523aeb626' and topic_name = 'Feelings and personality — Duygular ve Kişilik';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Vücudunun bölümlerini İngilizce söylemeyi ve bir yerin ağrıdığında bunu anlatmayı öğreneceksin. Hasta bir arkadaşına ne yapması gerektiğini de söyleyebileceksin.</p><h3>Vücudumuz</h3><table><tr><th>English</th><th>Türkçe</th><th>English</th><th>Türkçe</th></tr><tr><td><b>head</b></td><td>baş, kafa</td><td><b>arm</b></td><td>kol</td></tr><tr><td><b>eye</b></td><td>göz</td><td><b>hand</b></td><td>el</td></tr><tr><td><b>ear</b></td><td>kulak</td><td><b>finger</b></td><td>parmak</td></tr><tr><td><b>nose</b></td><td>burun</td><td><b>back</b></td><td>sırt</td></tr><tr><td><b>mouth</b></td><td>ağız</td><td><b>stomach</b></td><td>mide, karın</td></tr><tr><td><b>tooth</b> / <b>teeth</b></td><td>diş / dişler</td><td><b>leg</b></td><td>bacak</td></tr><tr><td><b>throat</b></td><td>boğaz</td><td><b>knee</b></td><td>diz</td></tr><tr><td><b>shoulder</b></td><td>omuz</td><td><b>foot</b> / <b>feet</b></td><td>ayak / ayaklar</td></tr></table><p>Dikkat: <b>tooth</b> ve <b>foot</b> kelimelerinin çoğulu düzensizdir: <b>teeth</b>, <b>feet</b>. <i>Knee</i> kelimesindeki k okunmaz: “nii”.</p><h3>Neyin var? Ağrılar ve hastalıklar</h3><p>Biri sana <b>What's the matter?</b> ya da <b>What's wrong?</b> (Neyin var?) diye sorabilir. Cevap vermenin iki yolu var:</p><ul><li><b>I have a ...</b> = Bende ... var: <i>I have a headache.</i> (Başım ağrıyor.)</li><li><b>My ... hurts.</b> = ...m acıyor: <i>My leg hurts.</i> (Bacağım acıyor.)</li></ul><table><tr><th>English</th><th>Türkçe</th></tr><tr><td><b>a headache</b></td><td>baş ağrısı</td></tr><tr><td><b>a toothache</b></td><td>diş ağrısı</td></tr><tr><td><b>an earache</b></td><td>kulak ağrısı</td></tr><tr><td><b>a stomachache</b></td><td>karın ağrısı</td></tr><tr><td><b>a sore throat</b></td><td>boğaz ağrısı</td></tr><tr><td><b>a cold</b></td><td>soğuk algınlığı, nezle</td></tr><tr><td><b>a cough</b></td><td>öksürük</td></tr><tr><td><b>a fever</b></td><td>ateş</td></tr></table><p><b>ache</b> ağrı demektir ve “eyk” diye okunur. Vücut kelimesine eklenir: <i>head + ache = headache</i>.</p><h3>Ne yapmalısın?</h3><p>Tavsiye verirken <b>You should ...</b> (… yapmalısın) kalıbını kullan:</p><ul><li><i>You should see a doctor.</i> (Doktora gitmelisin.)</li><li><i>You should take some medicine.</i> (Biraz ilaç almalısın.)</li><li><i>You should rest and drink water.</i> (Dinlenmeli ve su içmelisin.)</li></ul><p>Sağlıklı kalmak için: <i>Wash your hands.</i> (Ellerini yıka.) <i>Eat fruit and vegetables.</i> <i>Sleep well.</i></p><h3>Dikkat!</h3><ul><li>Hastalık <b>have</b> ile söylenir. Yanlış: <i>I am headache.</i> → Doğru: <i>I have a headache.</i></li><li><b>I am cold</b> üşüyorum demektir, <b>I have a cold</b> ise nezleyim demektir. İkisini karıştırma!</li><li>Tek bir yer için <b>hurts</b> kullan. Yanlış: <i>My leg hurt.</i> (şimdiki ağrı için) → Doğru: <i>My leg hurts.</i></li><li>Çoğullar düzensiz. Yanlış: <i>my foots, my tooths</i> → Doğru: <i>my feet, my teeth</i></li></ul><h3>Kısaca</h3><p>Vücut bölümlerini öğren ve ağrıyı <b>I have a ...</b> ya da <b>My ... hurts</b> diye anlat. Tavsiye vermek için <b>You should ...</b> de.</p>","ornekler":[{"en":"I have a headache. Can I sit down, please?","tr":"Başım ağrıyor. Oturabilir miyim lütfen?"},{"en":"Ali has a sore throat, so he can't sing today.","tr":"Ali'nin boğazı ağrıyor, bu yüzden bugün şarkı söyleyemez."},{"en":"— What's the matter? — My stomach hurts.","tr":"Neyin var? Karnım ağrıyor."},{"en":"Zeynep has a cold and a bad cough.","tr":"Zeynep nezle olmuş ve kötü bir öksürüğü var."},{"en":"Elif has a fever, so she must stay in bed.","tr":"Elif'in ateşi var, bu yüzden yatakta kalmalı."},{"en":"Wash your hands before you eat.","tr":"Yemek yemeden önce ellerini yıka."},{"en":"You should drink some water and rest.","tr":"Biraz su içip dinlenmelisin."},{"en":"Mert fell off his bike and hurt his knee.","tr":"Mert bisikletten düştü ve dizini incitti."},{"en":"The doctor gave me some medicine for my earache.","tr":"Doktor kulak ağrım için bana biraz ilaç verdi."},{"en":"Papi doesn't feel well today. Poor Papi!","tr":"Papi bugün kendini iyi hissetmiyor. Zavallı Papi!"}],"test":[{"tip":"secim","soru":"\"Diş ağrısı\" İngilizcede hangisi?","secenekler":["toothache","headache","earache"],"dogru":0,"aciklama":"Tooth (diş) + ache (ağrı) = toothache. Headache baş, earache kulak ağrısıdır."},{"tip":"secim","soru":"\"I have a cold.\" ne demek?","secenekler":["Üşüyorum.","Nezleyim, soğuk algınlığım var.","Soğuk bir şey istiyorum."],"dogru":1,"aciklama":"I have a cold nezleyim demektir. Üşüyorum ise I am cold olur."},{"tip":"bosluk","soru":"I have a sore ___. I can't talk.","tr":"Boğazım ağrıyor. Konuşamıyorum.","secenekler":["stomach","knee","throat"],"dogru":2,"aciklama":"Boğaz throat demektir: a sore throat = boğaz ağrısı."},{"tip":"bosluk","soru":"— What's the matter? — My leg ___.","tr":"Neyin var? Bacağım acıyor.","secenekler":["hurt","hurts","hurting"],"dogru":1,"aciklama":"My leg tek bir şeydir (it), şimdiki ağrı için hurts denir."},{"tip":"secim","soru":"Elif'in ateşi var. Hangisi doğru?","secenekler":["Elif has a fever.","Elif is fever.","Elif have a fever."],"dogru":0,"aciklama":"Hastalık have ile söylenir; Elif (she) için has kullanılır: Elif has a fever."},{"tip":"bosluk","soru":"My ___ hurt. I can't walk.","tr":"Ayaklarım acıyor. Yürüyemiyorum.","secenekler":["foots","feets","feet"],"dogru":2,"aciklama":"Foot kelimesinin çoğulu düzensizdir: feet."},{"tip":"secim","soru":"Hangisi vücudun bir bölümü DEĞİLDİR?","secenekler":["shoulder","medicine","knee"],"dogru":1,"aciklama":"Medicine ilaç demektir. Shoulder omuz, knee dizdir."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Zeynep","has","a","bad","cough"],"cevap":"Zeynep has a bad cough.","tr":"Zeynep'in kötü bir öksürüğü var.","aciklama":"Hastalık have ile söylenir; Zeynep (she) için has kullanılır."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["What's","the","matter","with","your","arm"],"cevap":"What's the matter with your arm?","tr":"Koluna ne oldu?","aciklama":"What's the matter with ...? = ... neyi var, ne oldu?"},{"tip":"dogruyanlis","soru":"\"I am cold\" ve \"I have a cold\" aynı anlama gelir.","dogru":false,"aciklama":"I am cold üşüyorum, I have a cold ise nezleyim demektir."}],"kelimeSozlugu":{"headache":{"tr":"baş ağrısı","alt":"I have a headache."},"stomach":{"tr":"mide, karın","alt":""},"throat":{"tr":"boğaz","alt":"a sore throat: boğaz ağrısı"},"knee":{"tr":"diz","alt":"k okunmaz"},"fever":{"tr":"ateş","alt":"hastalıkta vücut ateşi"},"cold":{"tr":"soğuk algınlığı, nezle","alt":"have a cold"},"cough":{"tr":"öksürük","alt":""},"hurts":{"tr":"acıyor","alt":"My leg hurts."},"medicine":{"tr":"ilaç","alt":""},"doctor":{"tr":"doktor","alt":""}}}$dm$::jsonb where id = 'a17fe291-9982-4f6a-a315-f0fca83d6485' and topic_name = 'Health and the body — Sağlık ve Vücut';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Tatil planlarını ve gezilerini İngilizce anlatmayı öğreneceksin. Bavul hazırlamaktan havalimanına, otelden hediyelik eşya almaya kadar en çok kullanılan kelimeleri tanıyacaksın.</p><h3>Yolculuğa hazırlık</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>holiday</b></td><td>tatil</td><td><i>We are going on holiday.</i></td></tr><tr><td><b>trip</b></td><td>gezi, kısa yolculuk</td><td><i>We went on a school trip.</i></td></tr><tr><td><b>suitcase</b></td><td>bavul</td><td><i>My suitcase is heavy.</i></td></tr><tr><td><b>luggage</b></td><td>bagaj, yük (tüm çantalar)</td><td><i>Where is our luggage?</i></td></tr><tr><td><b>pack</b></td><td>(bavul) hazırlamak</td><td><i>Pack your suitcase tonight.</i></td></tr><tr><td><b>passport</b></td><td>pasaport</td><td><i>Don't forget your passport.</i></td></tr><tr><td><b>ticket</b></td><td>bilet</td><td><i>I have two train tickets.</i></td></tr><tr><td><b>map</b></td><td>harita</td><td><i>Let's look at the map.</i></td></tr></table><h3>Havalimanında ve otelde</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>airport</b></td><td>havalimanı</td><td><i>We arrived at the airport early.</i></td></tr><tr><td><b>flight</b></td><td>uçuş</td><td><i>Our flight is at nine.</i></td></tr><tr><td><b>check in</b></td><td>giriş işlemi yapmak</td><td><i>We check in at the airport.</i></td></tr><tr><td><b>delayed</b></td><td>gecikmiş, rötarlı</td><td><i>The flight is delayed.</i></td></tr><tr><td><b>hotel</b></td><td>otel</td><td><i>The hotel has a big pool.</i></td></tr><tr><td><b>stay</b></td><td>kalmak</td><td><i>We stayed at a hotel.</i></td></tr><tr><td><b>check out</b></td><td>otelden çıkış yapmak</td><td><i>We check out at noon.</i></td></tr></table><p><b>Check in</b> havalimanında ya da otelde kayıt yaptırmak, <b>check out</b> ise otelden ayrılırken çıkış yapmaktır.</p><h3>Tatilde neler yaparız?</h3><ul><li><b>go sightseeing</b> = gezip görülecek yerleri gezmek: <i>We went sightseeing in Istanbul.</i></li><li><b>go camping</b> = kampa gitmek: <i>We went camping and slept in a tent.</i></li><li><b>go swimming</b> = yüzmeye gitmek</li><li><b>take photos</b> = fotoğraf çekmek: <i>Can you take a photo of us?</i></li><li><b>buy souvenirs</b> = hediyelik eşya almak. <b>Souvenir</b> “suvınir” diye okunur.</li><li><b>visit</b> = ziyaret etmek, gezmek: <i>We visited a museum.</i></li></ul><h3>Dikkat!</h3><ul><li>Tatile gitmek <b>go on holiday</b> olur. Yanlış: <i>We go to holiday.</i> → Doğru: <i>We go on holiday.</i></li><li><b>Visit</b> fiilinden sonra <b>to</b> gelmez. Yanlış: <i>I visited to Antalya.</i> → Doğru: <i>I visited Antalya.</i></li><li><b>Luggage</b> sayılamaz, -s almaz. Yanlış: <i>three luggages</i> → Doğru: <i>three bags</i> ya da <i>a lot of luggage</i></li><li>Otelde kalmak için <b>live</b> değil <b>stay</b> kullanılır. Yanlış: <i>We lived at a hotel.</i> → Doğru: <i>We stayed at a hotel.</i></li></ul><h3>Kısaca</h3><p>Tatile çıkarken <b>pack your suitcase</b>, yanına <b>passport</b> ve <b>ticket</b> al. Tatilde <b>go sightseeing</b>, <b>take photos</b> ve <b>buy souvenirs</b> gibi kalıplarla neler yaptığını anlatırsın.</p>","ornekler":[{"en":"We are going on holiday to Antalya next week.","tr":"Gelecek hafta Antalya'ya tatile gidiyoruz."},{"en":"Don't forget your passport and your ticket!","tr":"Pasaportunu ve biletini unutma!"},{"en":"Ece is packing her suitcase for the trip.","tr":"Ece gezi için bavulunu hazırlıyor."},{"en":"Our flight was delayed by two hours.","tr":"Uçuşumuz iki saat rötar yaptı."},{"en":"We stayed at a small hotel near the beach.","tr":"Plajın yakınındaki küçük bir otelde kaldık."},{"en":"— Did you go sightseeing in Rome? — Yes, we did.","tr":"Roma'da gezip görülecek yerleri gezdiniz mi? Evet, gezdik."},{"en":"Mert bought a souvenir for his grandma.","tr":"Mert büyükannesi için bir hediyelik eşya aldı."},{"en":"We went camping and slept in a tent.","tr":"Kampa gittik ve çadırda uyuduk."},{"en":"Excuse me, can you take a photo of us, please?","tr":"Affedersiniz, bizim bir fotoğrafımızı çekebilir misiniz lütfen?"},{"en":"Papi can't come by plane, so he stays with Grandma.","tr":"Papi uçakla gelemez, bu yüzden büyükannemin yanında kalır."}],"test":[{"tip":"secim","soru":"\"Bavul\" kelimesinin İngilizcesi hangisi?","secenekler":["ticket","suitcase","souvenir"],"dogru":1,"aciklama":"Bavul suitcase demektir. Ticket bilet, souvenir hediyelik eşyadır."},{"tip":"bosluk","soru":"We are going ___ holiday in August.","tr":"Ağustosta tatile gidiyoruz.","secenekler":["on","to","in"],"dogru":0,"aciklama":"Tatile gitmek go on holiday olur."},{"tip":"secim","soru":"\"Souvenir\" ne demek?","secenekler":["hediyelik eşya","harita","pasaport"],"dogru":0,"aciklama":"Souvenir gezdiğin yerden aldığın hediyelik eşyadır. Harita map'tir."},{"tip":"bosluk","soru":"Our flight was ___. We waited for three hours.","tr":"Uçuşumuz rötar yaptı. Üç saat bekledik.","secenekler":["waited","slow","delayed"],"dogru":2,"aciklama":"Geç kalan, rötar yapan uçuş için delayed denir."},{"tip":"secim","soru":"Hangisi doğru?","secenekler":["I have three bags.","I have three luggages.","I have three luggage."],"dogru":0,"aciklama":"Luggage sayılamaz, sayı ile kullanılmaz. Sayarken bags deriz."},{"tip":"bosluk","soru":"We ___ at a hotel near the beach.","tr":"Plajın yakınındaki bir otelde kaldık.","secenekler":["lived","stayed","visited"],"dogru":1,"aciklama":"Tatilde otelde kalmak stay olur; live orada yaşamak demektir."},{"tip":"secim","soru":"Havalimanında uçuştan önce bavulunu teslim edip kayıt yaptırırsın. Buna ne denir?","secenekler":["check out","sign in","check in"],"dogru":2,"aciklama":"Havalimanında ve otelde kayıt yaptırmak check in, otelden çıkmak check out'tur."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Don't","forget","to","pack","your","passport"],"cevap":"Don't forget to pack your passport.","tr":"Pasaportunu bavula koymayı unutma.","aciklama":"Don't forget to + fiil = ... yapmayı unutma."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We","visited","a","museum"],"cevap":"We visited a museum.","tr":"Bir müze gezdik.","aciklama":"visit fiilinden sonra to gelmez: visited a museum."},{"tip":"dogruyanlis","soru":"\"I visited to Antalya last summer.\" Bu cümle doğru mu?","dogru":false,"aciklama":"Visit fiilinden sonra to gelmez: I visited Antalya last summer."}],"kelimeSozlugu":{"holiday":{"tr":"tatil","alt":"go on holiday: tatile gitmek"},"suitcase":{"tr":"bavul","alt":""},"passport":{"tr":"pasaport","alt":""},"ticket":{"tr":"bilet","alt":""},"flight":{"tr":"uçuş","alt":""},"delayed":{"tr":"rötarlı, gecikmiş","alt":""},"sightseeing":{"tr":"gezip görme","alt":"go sightseeing"},"souvenir":{"tr":"hediyelik eşya","alt":"suvınir diye okunur"},"luggage":{"tr":"bagaj","alt":"sayılamaz"},"camping":{"tr":"kamp yapma","alt":"go camping"},"stayed":{"tr":"kaldı, kaldık","alt":"stay: kalmak"}}}$dm$::jsonb where id = 'aff9ef72-926f-4a2a-b3f4-55ee20e63cb8' and topic_name = 'Holidays and travel — Tatiller ve Seyahat';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Meslekleri ve bu meslekleri yapan kişilerin nerede çalıştığını İngilizce söylemeyi öğreneceksin. Ailendeki insanların ne iş yaptığını anlatabilecek ve büyüyünce ne olmak istediğini söyleyebileceksin.</p><h3>Meslekler ve çalışma yerleri</h3><table><tr><th>Meslek</th><th>Türkçe</th><th>Nerede çalışır?</th></tr><tr><td><b>teacher</b></td><td>öğretmen</td><td>in a school (okulda)</td></tr><tr><td><b>doctor</b></td><td>doktor</td><td>in a hospital (hastanede)</td></tr><tr><td><b>nurse</b></td><td>hemşire</td><td>in a hospital</td></tr><tr><td><b>dentist</b></td><td>diş hekimi</td><td>in a clinic (muayenehanede)</td></tr><tr><td><b>vet</b></td><td>veteriner</td><td>in a clinic, on a farm</td></tr><tr><td><b>police officer</b></td><td>polis memuru</td><td>at a police station (karakolda)</td></tr><tr><td><b>firefighter</b></td><td>itfaiyeci</td><td>at a fire station (itfaiyede)</td></tr><tr><td><b>chef</b> / <b>cook</b></td><td>şef / aşçı</td><td>in a restaurant kitchen (restoran mutfağında)</td></tr><tr><td><b>waiter</b></td><td>garson</td><td>in a restaurant, in a café</td></tr><tr><td><b>mechanic</b></td><td>tamirci</td><td>in a garage (oto tamirhanesinde)</td></tr><tr><td><b>farmer</b></td><td>çiftçi</td><td>on a farm (çiftlikte)</td></tr><tr><td><b>pilot</b></td><td>pilot</td><td>on a plane, at an airport</td></tr><tr><td><b>engineer</b></td><td>mühendis</td><td>in an office, in a factory</td></tr><tr><td><b>architect</b></td><td>mimar</td><td>in an office</td></tr><tr><td><b>shop assistant</b></td><td>satış görevlisi</td><td>in a shop (mağazada)</td></tr></table><p>Mesleğin ne yaptığını anlatmak için: <i>A mechanic fixes cars.</i> (Tamirci araba tamir eder.) <i>A farmer grows vegetables.</i> (Çiftçi sebze yetiştirir.) <i>An architect designs buildings.</i> (Mimar bina tasarlar.)</p><h3>Meslek sorma ve söyleme</h3><ul><li><b>What does your mother do?</b> = Annen ne iş yapıyor? → <i>She's a nurse.</i></li><li><b>What's your father's job?</b> = Babanın mesleği ne? → <i>He's a mechanic.</i></li><li><b>Where does he work?</b> = Nerede çalışıyor? → <i>He works in a garage.</i></li><li><b>What do you want to be?</b> = Ne olmak istiyorsun? → <i>I want to be a vet.</i></li></ul><h3>a mı, an mi?</h3><p>İngilizcede meslekten önce <b>a</b> ya da <b>an</b> (bir) kullanmak zorunludur. Türkçede “Babam doktor.” deriz ama İngilizcede <i>My father is a doctor.</i> deriz. Meslek sesli harf sesiyle başlıyorsa <b>an</b> kullanılır: <i>an engineer, an architect</i>. Diğerlerinde <b>a</b>: <i>a teacher, a pilot</i>.</p><h3>Dikkat!</h3><ul><li>Meslekten önce a/an'ı unutma. Yanlış: <i>She is teacher.</i> → Doğru: <i>She is a teacher.</i></li><li>Yanlış: <i>He is a engineer.</i> → Doğru: <i>He is an engineer.</i></li><li><b>Cooker</b> ocak, fırın demektir, kişi değildir. Yanlış: <i>My uncle is a cooker.</i> → Doğru: <i>My uncle is a cook.</i></li><li>Ne iş yaptığını sorarken <b>do</b> kullanılır. Yanlış: <i>What does your mother make?</i> → Doğru: <i>What does your mother do?</i></li></ul><h3>Kısaca</h3><p>Meslek söylerken <b>a</b> ya da <b>an</b> kullan: <i>She's a nurse. He's an engineer.</i> Birinin mesleğini <b>What does he do?</b>, nerede çalıştığını <b>Where does he work?</b> diye sorarsın.</p>","ornekler":[{"en":"— What does your mother do? — She's a nurse.","tr":"Annen ne iş yapıyor? O bir hemşire."},{"en":"A nurse works in a hospital.","tr":"Hemşire hastanede çalışır."},{"en":"My uncle is a mechanic. He fixes cars in a garage.","tr":"Amcam tamirci. Bir tamirhanede araba tamir eder."},{"en":"Elif wants to be a vet because she loves animals.","tr":"Elif veteriner olmak istiyor çünkü hayvanları çok seviyor."},{"en":"Firefighters work at the fire station.","tr":"İtfaiyeciler itfaiye binasında çalışır."},{"en":"The chef cooks delicious food in the kitchen.","tr":"Şef mutfakta lezzetli yemekler pişirir."},{"en":"An architect designs houses and schools.","tr":"Mimar evler ve okullar tasarlar."},{"en":"— Is your dad a pilot? — No, he isn't. He's a teacher.","tr":"Baban pilot mu? Hayır, değil. O bir öğretmen."},{"en":"A farmer grows vegetables and looks after animals.","tr":"Çiftçi sebze yetiştirir ve hayvanlara bakar."},{"en":"— What do you want to be? — An engineer!","tr":"Ne olmak istiyorsun? Mühendis!"}],"test":[{"tip":"secim","soru":"Hastanede çalışan ve hastalara bakan kişi hangisi?","secenekler":["farmer","nurse","mechanic"],"dogru":1,"aciklama":"Nurse hemşiredir ve hastanede çalışır. Farmer çiftçi, mechanic tamircidir."},{"tip":"secim","soru":"\"Vet\" ne demek?","secenekler":["veteriner","öğretmen","aşçı"],"dogru":0,"aciklama":"Vet hayvanları tedavi eden veterinerdir."},{"tip":"bosluk","soru":"My father is ___ engineer.","tr":"Babam bir mühendis.","secenekler":["a","an","one"],"dogru":1,"aciklama":"Engineer sesli harf sesiyle başlar, bu yüzden an kullanılır."},{"tip":"bosluk","soru":"A chef works in a ___.","tr":"Bir şef restoranda çalışır.","secenekler":["restaurant","farm","garage"],"dogru":0,"aciklama":"Şef restoranın mutfağında çalışır: restaurant."},{"tip":"secim","soru":"Hangi cümle doğru?","secenekler":["She is teacher.","She is a teacher.","She a teacher."],"dogru":1,"aciklama":"Meslekten önce a/an gelir ve is unutulmaz: She is a teacher."},{"tip":"bosluk","soru":"— What does your mother ___? — She's a dentist.","tr":"Annen ne iş yapıyor? O bir diş hekimi.","secenekler":["make","does","do"],"dogru":2,"aciklama":"Meslek sorusu: What does she do? Does zaten başta olduğu için sonra do gelir."},{"tip":"secim","soru":"Tamirci (mechanic) nerede çalışır?","secenekler":["in a hospital","in a school","in a garage"],"dogru":2,"aciklama":"Tamirci arabaları garage denen tamirhanede tamir eder."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I","want","to","be","a","pilot"],"cevap":"I want to be a pilot.","tr":"Pilot olmak istiyorum.","aciklama":"Ne olmak istediğini söylerken: I want to be a/an + meslek."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Firefighters","work","at","the","fire","station"],"cevap":"Firefighters work at the fire station.","tr":"İtfaiyeciler itfaiye binasında çalışır.","aciklama":"Kalıp: Kim + work(s) + at/in + yer."},{"tip":"dogruyanlis","soru":"\"Cooker\" yemek pişiren kişi demektir.","dogru":false,"aciklama":"Cooker ocak ya da fırındır. Yemek pişiren kişi cook ya da chef'tir."}],"kelimeSozlugu":{"nurse":{"tr":"hemşire","alt":""},"vet":{"tr":"veteriner","alt":""},"mechanic":{"tr":"tamirci","alt":""},"firefighters":{"tr":"itfaiyeciler","alt":"tekili: firefighter"},"chef":{"tr":"şef, aşçı","alt":"şef diye okunur"},"farmer":{"tr":"çiftçi","alt":""},"engineer":{"tr":"mühendis","alt":"an engineer"},"architect":{"tr":"mimar","alt":"arkitekt diye okunur"},"garage":{"tr":"oto tamirhanesi, garaj","alt":""},"job":{"tr":"meslek, iş","alt":""}}}$dm$::jsonb where id = '3cf775c9-cf72-4c06-80fc-3440efa12932' and topic_name = 'Jobs and places of work — Meslekler ve Çalışma Yerleri';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Şehirdeki hizmet yerlerinin (banka, postane, karakol, eczane gibi) İngilizce adlarını öğreneceksin. Bu yerlerde ne yapıldığını anlatabilecek ve kibarca bir şey isteyebileceksin.</p><h3>Hizmet yerleri</h3><table><tr><th>English</th><th>Türkçe</th><th>Orada ne yaparsın?</th></tr><tr><td><b>bank</b></td><td>banka</td><td><i>I put my pocket money in the bank.</i></td></tr><tr><td><b>post office</b></td><td>postane, PTT</td><td><i>I send letters at the post office.</i></td></tr><tr><td><b>police station</b></td><td>karakol</td><td><i>The police station is next to the park.</i></td></tr><tr><td><b>fire station</b></td><td>itfaiye</td><td><i>The fire station has red trucks.</i></td></tr><tr><td><b>hospital</b></td><td>hastane</td><td><i>Doctors and nurses work at the hospital.</i></td></tr><tr><td><b>pharmacy</b></td><td>eczane</td><td><i>You can buy medicine at the pharmacy.</i></td></tr><tr><td><b>dentist</b></td><td>dişçi</td><td><i>I go to the dentist twice a year.</i></td></tr><tr><td><b>library</b></td><td>kütüphane</td><td><i>We borrow books from the library.</i></td></tr><tr><td><b>hairdresser's</b></td><td>kuaför, berber</td><td><i>I had a haircut at the hairdresser's.</i></td></tr></table><p>İngiltere'de eczaneye <b>chemist's</b> da denir.</p><h3>Postanede ve bankada</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>letter</b></td><td>mektup</td><td><i>Ali wrote a letter to his grandma.</i></td></tr><tr><td><b>postcard</b></td><td>kartpostal</td><td><i>Send me a postcard from Bodrum!</i></td></tr><tr><td><b>parcel</b></td><td>paket, koli</td><td><i>This parcel is heavy.</i></td></tr><tr><td><b>stamp</b></td><td>pul</td><td><i>I need a stamp for this letter.</i></td></tr><tr><td><b>envelope</b></td><td>zarf</td><td><i>Put the card in an envelope.</i></td></tr><tr><td><b>money / coin</b></td><td>para / bozuk para</td><td><i>I keep my coins in a box.</i></td></tr><tr><td><b>bank account</b></td><td>banka hesabı</td><td><i>Mum opened a bank account for me.</i></td></tr><tr><td><b>appointment</b></td><td>randevu</td><td><i>I have an appointment at four.</i></td></tr></table><h3>Kibarca isteme ve sorma</h3><p>Bu yerlerde konuşurken <b>I'd like to ...</b> (... istiyorum) ve <b>Can I ...?</b> (...bilir miyim?) kalıpları çok işe yarar.</p><ul><li><b>Excuse me, where is the nearest post office?</b> = Affedersiniz, en yakın postane nerede?</li><li><b>I'd like to send this parcel to İzmir, please.</b> = Bu paketi İzmir'e göndermek istiyorum.</li><li><b>How much is a stamp?</b> = Bir pul ne kadar?</li><li><b>Can I make an appointment, please?</b> = Randevu alabilir miyim, lütfen?</li></ul><p>Postanede kısa bir konuşma: <i>— Hello. I'd like to send this postcard to London. — Sure. That's twenty lira. — Here you are. — Thank you!</i></p><h3>Dikkat!</h3><ul><li><b>library</b> kitapçı değil, <b>kütüphane</b>dir. Kitap satın aldığın yer <b>bookshop</b>’tur.</li><li>Randevu almak <b>make an appointment</b>’tır: <i>take an appointment</i> → <i>make an appointment</i></li><li>“Dişçiye gitmek” derken <b>the</b> unutulmaz: <i>I go to dentist.</i> → <i>I go to the dentist.</i></li><li>Kibar istekte <b>to</b> unutma: <i>I'd like send a letter.</i> → <i>I'd like to send a letter.</i></li></ul><h3>Kısaca</h3><p>Bank, post office, police station, pharmacy ve library şehrin önemli hizmet yerleridir. Bu yerlerde bir şey isterken <b>I'd like to ...</b> ve <b>Can I ...?</b> kalıplarını kullan.</p>","ornekler":[{"en":"I'd like to send this parcel to İzmir, please.","tr":"Bu paketi İzmir'e göndermek istiyorum, lütfen."},{"en":"How much is a stamp for this postcard?","tr":"Bu kartpostal için pul ne kadar?"},{"en":"Excuse me, where is the nearest post office?","tr":"Affedersiniz, en yakın postane nerede?"},{"en":"The police station is next to the hospital.","tr":"Karakol hastanenin yanında."},{"en":"I put my pocket money in the bank.","tr":"Harçlığımı bankaya yatırırım."},{"en":"I have an appointment at the dentist's on Monday.","tr":"Pazartesi dişçide randevum var."},{"en":"We borrow books from the library every week.","tr":"Her hafta kütüphaneden kitap ödünç alırız."},{"en":"You can buy medicine at the pharmacy.","tr":"Eczaneden ilaç alabilirsin."},{"en":"The firefighters at the fire station are very brave.","tr":"İtfaiyedeki itfaiyeciler çok cesurdur."},{"en":"Can I make an appointment with the doctor, please?","tr":"Doktordan randevu alabilir miyim, lütfen?"}],"test":[{"tip":"secim","soru":"\"Post office\" ne demektir?","secenekler":["postane","karakol","eczane"],"dogru":0,"aciklama":"Post office postanedir. Karakol police station, eczane pharmacy'dir."},{"tip":"secim","soru":"Kitap ödünç almak için nereye gidersin?","secenekler":["bookshop","bank","library"],"dogru":2,"aciklama":"Kitap ödünç alınan yer library (kütüphane)dir. Bookshop'ta kitap satın alırsın."},{"tip":"bosluk","soru":"You can buy medicine at the ___.","tr":"Eczaneden ilaç alabilirsin.","secenekler":["bank","pharmacy","library"],"dogru":1,"aciklama":"İlaç eczaneden alınır: pharmacy."},{"tip":"bosluk","soru":"I need a ___ for this letter.","tr":"Bu mektup için bir pula ihtiyacım var.","secenekler":["parcel","ticket","stamp"],"dogru":2,"aciklama":"Mektuba yapıştırılan pul stamp'tir. Parcel paket, ticket bilettir."},{"tip":"secim","soru":"Sokakta birinin cüzdanını buldun. Onu nereye götürürsün?","secenekler":["police station","fire station","hairdresser's"],"dogru":0,"aciklama":"Bulunan eşyalar karakola (police station) götürülür."},{"tip":"bosluk","soru":"Can I ___ an appointment with the dentist?","tr":"Dişçiden randevu alabilir miyim?","secenekler":["take","make","do"],"dogru":1,"aciklama":"Randevu almak make an appointment'tır. Türkçedeki 'almak' yüzünden take demek yanlıştır."},{"tip":"secim","soru":"Postanedeki görevli soruyor: \"Where do you want to send it?\" Ne cevap verirsin?","secenekler":["It's two kilos.","To Ankara, please.","Yes, I want."],"dogru":1,"aciklama":"Nereye göndermek istediğin soruluyor, yeri söylersin: To Ankara, please."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["Where","is","the","nearest","post","office"],"cevap":"Where is the nearest post office?","tr":"En yakın postane nerede?","aciklama":"Yer sormak için: Where is the nearest + yer?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["I'd","like","to","send","this","parcel"],"cevap":"I'd like to send this parcel.","tr":"Bu paketi göndermek istiyorum.","aciklama":"Kibar istek: I'd like to + fiil."},{"tip":"dogruyanlis","soru":"\"Library\" kitapçı demektir. Bu doğru mu?","dogru":false,"aciklama":"Yanlış! Library kütüphanedir. Kitapçı bookshop'tur."}],"kelimeSozlugu":{"bank":{"tr":"banka","alt":""},"post office":{"tr":"postane","alt":"PTT"},"police station":{"tr":"karakol","alt":""},"pharmacy":{"tr":"eczane","alt":"İngiltere'de chemist's da denir"},"library":{"tr":"kütüphane","alt":"kitapçı değil: bookshop"},"dentist":{"tr":"dişçi","alt":""},"stamp":{"tr":"pul","alt":""},"parcel":{"tr":"paket, koli","alt":""},"letter":{"tr":"mektup","alt":"harf anlamı da var"},"appointment":{"tr":"randevu","alt":"make an appointment: randevu almak"}}}$dm$::jsonb where id = '50598529-1646-4073-b5a9-05792b29f936' and topic_name = 'Services (bank, post office, etc.) — Hizmetler (Banka, PTT vb.)';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Bilgisayar, tablet ve telefonla ilgili kelimeleri ve internette yaptığımız şeyleri anlatan kalıpları öğreneceksin. İnternette güvende kalmak için kullanılan cümleleri de İngilizce söyleyebileceksin.</p><h3>Cihazlar ve parçaları</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>computer</b></td><td>bilgisayar</td><td><i>Turn off the computer.</i></td></tr><tr><td><b>laptop</b></td><td>dizüstü bilgisayar</td><td><i>My laptop is new.</i></td></tr><tr><td><b>tablet</b></td><td>tablet</td><td><i>I read books on my tablet.</i></td></tr><tr><td><b>smartphone</b></td><td>akıllı telefon</td><td><i>Her smartphone is pink.</i></td></tr><tr><td><b>screen</b></td><td>ekran</td><td><i>The screen is very small.</i></td></tr><tr><td><b>keyboard</b></td><td>klavye</td><td><i>The keyboard doesn't work.</i></td></tr><tr><td><b>headphones</b></td><td>kulaklık</td><td><i>Put on your headphones.</i></td></tr><tr><td><b>charger</b></td><td>şarj aleti</td><td><i>Where is my charger?</i></td></tr></table><h3>İnternette yaptıklarımız</h3><table><tr><th>English</th><th>Türkçe</th></tr><tr><td><b>go online</b></td><td>internete girmek</td></tr><tr><td><b>search the internet</b></td><td>internette araştırma yapmak</td></tr><tr><td><b>download</b></td><td>indirmek</td></tr><tr><td><b>upload</b></td><td>yüklemek (internete koymak)</td></tr><tr><td><b>click on a link</b></td><td>bağlantıya tıklamak</td></tr><tr><td><b>send a message</b></td><td>mesaj göndermek</td></tr><tr><td><b>play online games</b></td><td>çevrim içi oyun oynamak</td></tr></table><p>Kolay hatırla: internetten kendi cihazına bir şey alırsan <b>download</b> (aşağı), kendi cihazından internete bir şey koyarsan <b>upload</b> (yukarı). Bir uygulamaya kısaca <b>app</b>, internet sitesine <b>website</b> denir.</p><h3>Hesap ve güvenlik</h3><ul><li><b>username</b> = kullanıcı adı, <b>password</b> = şifre</li><li><b>log in</b> = giriş yapmak, <b>log out</b> = çıkış yapmak</li><li><b>Wi-Fi</b> = kablosuz internet. Okunuşu: “uay-fay”.</li><li><i>Never share your password.</i> = Şifreni asla paylaşma.</li><li><i>Don't click on strange links.</i> = Garip bağlantılara tıklama.</li></ul><h3>Dikkat!</h3><ul><li>Bilgisayarı açmak için open değil turn on kullanılır: <i>Open the computer.</i> → <i>Turn on the computer.</i></li><li>İnternet için on kullanılır: <i>in the internet</i> → <i>on the internet</i></li><li>Wi-Fi “vi-fi” değil, “uay-fay” diye okunur.</li><li>download ile upload'ı karıştırma: <i>I uploaded a game from the internet.</i> → <i>I downloaded a game.</i></li></ul><h3>Kısaca</h3><p>Cihaz kelimeleri ve download, upload, click, log in gibi fiillerle internette yaptıklarını anlatabilirsin. Unutma: şifreni kimseyle paylaşma ve işin bitince log out yap.</p>","ornekler":[{"en":"My tablet's battery is low. Where is the charger?","tr":"Tabletimin şarjı az. Şarj aleti nerede?"},{"en":"I downloaded a new game app yesterday.","tr":"Dün yeni bir oyun uygulaması indirdim."},{"en":"Never share your password with anyone.","tr":"Şifreni asla kimseyle paylaşma."},{"en":"The Wi-Fi is very slow today.","tr":"Bugün kablosuz internet çok yavaş."},{"en":"Click on this link to watch the video.","tr":"Videoyu izlemek için bu bağlantıya tıkla."},{"en":"Ece is searching the internet for her homework.","tr":"Ece ödevi için internette araştırma yapıyor."},{"en":"Don't forget to log out of your account.","tr":"Hesabından çıkış yapmayı unutma."},{"en":"Can you send me the photos by email?","tr":"Fotoğrafları bana e-postayla gönderebilir misin?"},{"en":"Turn off the computer before you go to bed.","tr":"Yatmadan önce bilgisayarı kapat."},{"en":"Mert uploads his drawings to the school website.","tr":"Mert resimlerini okulun web sitesine yükler."}],"test":[{"tip":"secim","soru":"\"password\" ne demektir?","secenekler":["şifre","kullanıcı adı","bağlantı"],"dogru":0,"aciklama":"password şifre demektir. Kullanıcı adı username'dir."},{"tip":"secim","soru":"\"Şarj aleti\" İngilizcede hangisidir?","secenekler":["battery","charger","cable"],"dogru":1,"aciklama":"Şarj aleti charger'dır. battery pil, cable kablodur."},{"tip":"bosluk","soru":"I ___ a new app on my phone.","tr":"Telefonuma yeni bir uygulama indirdim.","secenekler":["uploaded","downloaded","clicked"],"dogru":1,"aciklama":"İnternetten cihazına almak download'dır: I downloaded a new app."},{"tip":"bosluk","soru":"___ on the link to open the page.","tr":"Sayfayı açmak için bağlantıya tıkla.","secenekler":["Click","Push","Open"],"dogru":0,"aciklama":"Bağlantıya tıklamak click on a link'tir."},{"tip":"secim","soru":"\"Bilgisayarı aç.\" cümlesinin İngilizcesi hangisi?","secenekler":["Open the computer.","Start on the computer.","Turn on the computer."],"dogru":2,"aciklama":"Elektronik cihazları açmak için turn on kullanılır."},{"tip":"bosluk","soru":"My little brother plays games ___ the internet.","tr":"Küçük kardeşim internette oyun oynar.","secenekler":["in","at","on"],"dogru":2,"aciklama":"İnternette = on the internet. in kullanılmaz."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Never","share","your","password","with","anyone"],"cevap":"Never share your password with anyone.","tr":"Şifreni asla kimseyle paylaşma.","aciklama":"Güvenlik kuralı: Never share your password."},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["Don't","forget","to","log","out"],"cevap":"Don't forget to log out.","tr":"Çıkış yapmayı unutma.","aciklama":"log out = çıkış yapmak; Don't forget to + fiil."},{"tip":"secim","soru":"Resmini okulun web sitesine koyuyorsun. Hangi fiili kullanırsın?","secenekler":["download","upload","log in"],"dogru":1,"aciklama":"Kendi cihazından internete bir şey koymak upload'dır."},{"tip":"dogruyanlis","soru":"\"Wi-Fi\" kelimesi İngilizcede \"vi-fi\" diye okunur.","dogru":false,"aciklama":"Hayır! Wi-Fi \"uay-fay\" diye okunur."}],"kelimeSozlugu":{"charger":{"tr":"şarj aleti","alt":""},"app":{"tr":"uygulama","alt":""},"password":{"tr":"şifre","alt":""},"Wi-Fi":{"tr":"kablosuz internet","alt":"uay-fay"},"link":{"tr":"bağlantı","alt":""},"internet":{"tr":"internet","alt":"on the internet"},"log out":{"tr":"çıkış yapmak","alt":""},"website":{"tr":"web sitesi","alt":""},"download":{"tr":"indirmek","alt":""},"upload":{"tr":"yüklemek","alt":"internete koymak"}}}$dm$::jsonb where id = 'c725b987-3f26-4f26-bdd6-3e818f56e170' and topic_name = 'Technology and the Internet — Teknoloji ve İnternet';
update public.lesson_topics set content = (content - 'testJSON') || $dm${"anlatimHTML":"<h3>Bu konuda ne öğreneceğiz?</h3><p>Taşıtların İngilizce adlarını ve yolculukta kullanılan kelimeleri öğreneceksin. Okula ya da tatile nasıl gittiğini doğru kalıplarla anlatabileceksin.</p><h3>Taşıtlar</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>car</b></td><td>araba</td><td><i>Dad drives his car to work.</i></td></tr><tr><td><b>bus</b></td><td>otobüs</td><td><i>I take the bus to school.</i></td></tr><tr><td><b>train</b></td><td>tren</td><td><i>The train is fast.</i></td></tr><tr><td><b>plane</b></td><td>uçak</td><td><i>We went to Antalya by plane.</i></td></tr><tr><td><b>ship / ferry</b></td><td>gemi / vapur</td><td><i>We crossed the sea by ferry.</i></td></tr><tr><td><b>bike (bicycle)</b></td><td>bisiklet</td><td><i>I ride my bike in the park.</i></td></tr><tr><td><b>motorbike</b></td><td>motosiklet</td><td><i>My uncle has a red motorbike.</i></td></tr><tr><td><b>taxi</b></td><td>taksi</td><td><i>Let's take a taxi.</i></td></tr><tr><td><b>tram</b></td><td>tramvay</td><td><i>The tram stops here.</i></td></tr><tr><td><b>underground / subway</b></td><td>metro</td><td><i>Can takes the subway every day.</i></td></tr></table><p>Metro için İngiltere'de <b>underground</b>, Amerika'da <b>subway</b> denir; <b>metro</b> da anlaşılır.</p><h3>Nasıl gidiyorsun?</h3><ul><li><b>by + taşıt</b> (the yok!): <i>by bus, by car, by train, by plane, by ferry</i> = otobüsle, arabayla...</li><li>Yürüyerek: <b>on foot</b> ya da <b>walk</b>: <i>I walk to school.</i></li><li><b>take the bus / the train</b> = otobüse / trene binip gitmek</li><li><b>ride a bike</b> = bisiklet sürmek, <b>drive a car</b> = araba sürmek, <b>fly</b> = uçmak</li><li>Otobüs, tren, uçak: <b>get on / get off</b> (binmek / inmek). Araba ve taksi: <b>get in / get out of</b>.</li><li>Soru: <b>How do you get to school?</b> = Okula nasıl gidersin? Cevap: <i>By bus.</i> ya da <i>I walk.</i></li></ul><h3>Yolda</h3><table><tr><th>English</th><th>Türkçe</th><th>Örnek</th></tr><tr><td><b>bus stop</b></td><td>otobüs durağı</td><td><i>Wait at the bus stop.</i></td></tr><tr><td><b>station</b></td><td>istasyon</td><td><i>The train station is near.</i></td></tr><tr><td><b>airport</b></td><td>havalimanı</td><td><i>The airport is very busy.</i></td></tr><tr><td><b>ticket</b></td><td>bilet</td><td><i>I need a bus ticket.</i></td></tr><tr><td><b>driver / passenger</b></td><td>şoför / yolcu</td><td><i>The driver says hello to every passenger.</i></td></tr><tr><td><b>traffic jam</b></td><td>trafik sıkışıklığı</td><td><i>There is a traffic jam today.</i></td></tr><tr><td><b>traffic lights</b></td><td>trafik ışıkları</td><td><i>Stop at the traffic lights.</i></td></tr><tr><td><b>seatbelt</b></td><td>emniyet kemeri</td><td><i>Fasten your seatbelt.</i></td></tr></table><h3>Dikkat!</h3><ul><li>Türkçedeki “otobüsle” <b>with</b> değil <b>by</b> olur ve <b>the</b> almaz: <i>I go with the bus.</i> → <i>I go by bus.</i></li><li>Yürüyerek <b>on foot</b>’tur: <i>by foot</i> → <i>on foot</i></li><li>Bisiklet sürmek <b>ride</b>’dır: <i>I drive a bike.</i> → <i>I ride a bike.</i></li><li>Otobüse binmek <b>get on</b>’dur: <i>Get in the bus.</i> → <i>Get on the bus.</i></li></ul><h3>Kısaca</h3><p>Taşıtla gitmeyi <b>by bus, by train, by plane</b> diye anlatırsın; yürüyorsan <b>on foot</b> dersin. Bisiklete <b>ride</b>, arabaya <b>drive</b> kullan ve otobüse <b>get on</b> ile bin.</p>","ornekler":[{"en":"I go to school by bus every morning.","tr":"Her sabah okula otobüsle giderim."},{"en":"How do you get to school? I walk.","tr":"Okula nasıl gidersin? Yürüyerek."},{"en":"We crossed the sea by ferry.","tr":"Denizi vapurla geçtik."},{"en":"Mert rides his bike to the park.","tr":"Mert parka bisikletiyle gider."},{"en":"Fasten your seatbelt, please.","tr":"Lütfen emniyet kemerini tak."},{"en":"There is a traffic jam, so we are late.","tr":"Trafik sıkışıklığı var, bu yüzden geç kaldık."},{"en":"The bus stop is in front of our school.","tr":"Otobüs durağı okulumuzun önünde."},{"en":"Is the train faster than the bus? Yes, it is.","tr":"Tren otobüsten daha hızlı mı? Evet."},{"en":"Get off the bus at the next stop.","tr":"Bir sonraki durakta otobüsten in."},{"en":"We are going to Antalya by plane.","tr":"Antalya'ya uçakla gidiyoruz."}],"test":[{"tip":"secim","soru":"\"Ferry\" ne demektir?","secenekler":["vapur","uçak","tramvay"],"dogru":0,"aciklama":"Ferry vapurdur. Uçak plane, tramvay tram'dır."},{"tip":"bosluk","soru":"I go to school ___ bus.","tr":"Okula otobüsle giderim.","secenekler":["with","by","on"],"dogru":1,"aciklama":"Taşıtla gitmek: by + taşıt. With kullanılmaz."},{"tip":"bosluk","soru":"Ece walks to school. She goes ___ foot.","tr":"Ece okula yürür. Yürüyerek gider.","secenekler":["by","with","on"],"dogru":2,"aciklama":"Yürüyerek: on foot. Taşıtlarda by, yürürken on kullanılır."},{"tip":"secim","soru":"\"Bisiklet sürmek\" İngilizcede nasıl söylenir?","secenekler":["drive a bike","ride a bike","go a bike"],"dogru":1,"aciklama":"Bisiklet ve at için ride kullanılır. Drive araba sürmektir."},{"tip":"secim","soru":"Uçakların kalkıp indiği yere İngilizcede ne denir?","secenekler":["station","bus stop","airport"],"dogru":2,"aciklama":"Havalimanı airport'tur. Station tren istasyonu, bus stop otobüs durağıdır."},{"tip":"bosluk","soru":"Get ___ the bus at the next stop.","tr":"Bir sonraki durakta otobüsten in.","secenekler":["out","off","down"],"dogru":1,"aciklama":"Otobüs, tren ve uçaktan inmek get off'tur. Get out of arabadan inmek için kullanılır."},{"tip":"secim","soru":"Arkadaşın soruyor: \"How do you get to school?\" Hangisi uygun cevaptır?","secenekler":["By car. My dad drives me.","Yes, I get.","At eight o'clock."],"dogru":0,"aciklama":"Nasıl gittiğin soruluyor, taşıtı söylersin: By car."},{"tip":"siralama","soru":"Kelimeleri sırala, soruyu kur.","parcalar":["How","do","you","get","to","school"],"cevap":"How do you get to school?","tr":"Okula nasıl gidersin?","aciklama":"Soru kalıbı: How do you get to + yer?"},{"tip":"siralama","soru":"Kelimeleri sırala, cümleyi kur.","parcalar":["We","crossed","the","sea","by","ferry"],"cevap":"We crossed the sea by ferry.","tr":"Denizi vapurla geçtik.","aciklama":"Taşıt cümlenin sonunda by ile gelir: by ferry."},{"tip":"dogruyanlis","soru":"Otobüse binmek için \"get on the bus\", arabaya binmek için \"get in the car\" denir. Bu doğru mu?","dogru":true,"aciklama":"Doğru! Büyük taşıtlarda get on, araba ve taksi için get in kullanılır."}],"kelimeSozlugu":{"ferry":{"tr":"vapur, feribot","alt":""},"subway":{"tr":"metro","alt":"İngiltere'de underground"},"bike":{"tr":"bisiklet","alt":"bicycle'ın kısası"},"ride":{"tr":"sürmek (bisiklet, at)","alt":""},"traffic jam":{"tr":"trafik sıkışıklığı","alt":""},"seatbelt":{"tr":"emniyet kemeri","alt":""},"bus stop":{"tr":"otobüs durağı","alt":""},"airport":{"tr":"havalimanı","alt":""},"station":{"tr":"istasyon","alt":""},"passenger":{"tr":"yolcu","alt":""}}}$dm$::jsonb where id = '2b772531-e29e-469d-86b4-0d6ca62c6e96' and topic_name = 'Transport — Ulaşım ve Taşımacılık';
